export enum UserStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum UserRole {
  VOLUNTEER = 'VOLUNTEER',
  ADMIN = 'ADMIN'
}

export interface VolunteerProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
  photoUrl: string;
  skills: string[];
  bio: string;
  status: UserStatus;
  role: UserRole;
  joinedAt: string;
}

export interface Shift {
  id: string;
  volunteerId: string;
  title: string;
  startTime: string; // ISO String
  endTime: string;   // ISO String
  location: string;
  description: string;
}

export interface AppState {
  currentUser: VolunteerProfile | null;
  volunteers: VolunteerProfile[];
  shifts: Shift[];
}

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const suggestSkills = async (bio: string): Promise<string[]> => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Based on the following volunteer bio, suggest a list of 5 relevant skills. Bio: "${bio}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            skills: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    const data = JSON.parse(response.text || '{"skills": []}');
    return data.skills;
  } catch (error) {
    console.error("Skill suggestion failed", error);
    return [];
  }
};

export const generateProfileSummary = async (profile: any): Promise<string> => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Create a professional and encouraging 2-sentence summary for a volunteer profile. 
      Name: ${profile.name}, Skills: ${profile.skills.join(', ')}, Bio: ${profile.bio}`,
    });
    return response.text || "";
  } catch (error) {
    return "Helpful volunteer dedicated to making a difference.";
  }
};

