import { GoogleGenAI, Type } from "@google/genai";

// Always use const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const suggestSkills = async (bio: string): Promise<string[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Based on the following volunteer bio, suggest a list of 5 relevant skills. Bio: "${bio}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            skills: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    // Directly access the text property as a string
    const data = JSON.parse(response.text || '{"skills": []}');
    return data.skills;
  } catch (error) {
    console.error("Skill suggestion failed", error);
    return [];
  }
};

export const generateProfileSummary = async (profile: any): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Create a professional and encouraging 2-sentence summary for a volunteer profile. 
      Name: ${profile.name}, Skills: ${profile.skills.join(', ')}, Bio: ${profile.bio}`,
    });
    // Directly access the text property as a string
    return response.text || "";
  } catch (error) {
    return "Helpful volunteer dedicated to making a difference.";
  }
};

import React, { useState } from 'react';
import { 
  format, 
  addMonths, 
  subMonths, 
  startOfMonth, 
  endOfMonth, 
  startOfWeek, 
  endOfWeek, 
  eachDayOfInterval, 
  isSameMonth, 
  isSameDay, 
  addHours,
  parseISO,
  isAfter,
  startOfToday
} from 'date-fns';
// Added Calendar to the imports from lucide-react
import { ChevronLeft, ChevronRight, Plus, Clock, MapPin, CheckCircle2, Calendar } from 'lucide-react';
import { Shift, VolunteerProfile } from '../types';

interface ShiftCalendarProps {
  shifts: Shift[];
  currentUser: VolunteerProfile;
  onAddShift: (shift: Omit<Shift, 'id' | 'volunteerId'>) => void;
  onRemoveShift: (shiftId: string) => void;
}

const ShiftCalendar: React.FC<ShiftCalendarProps> = ({ 
  shifts, 
  currentUser, 
  onAddShift, 
  onRemoveShift 
}) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [showAddModal, setShowAddModal] = useState(false);
  const [newShift, setNewShift] = useState({
    title: 'General Volunteering',
    startTime: '09:00',
    duration: 4,
    location: 'Community Center',
    description: ''
  });

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(monthStart);
  const startDate = startOfWeek(monthStart);
  const endDate = endOfWeek(monthEnd);

  const calendarDays = eachDayOfInterval({ start: startDate, end: endDate });

  const getShiftsForDay = (day: Date) => {
    return shifts.filter(s => isSameDay(parseISO(s.startTime), day));
  };

  const handleAddShift = () => {
    const start = parseISO(`${format(selectedDate, 'yyyy-MM-dd')}T${newShift.startTime}:00`);
    const end = addHours(start, newShift.duration);

    onAddShift({
      title: newShift.title,
      startTime: start.toISOString(),
      endTime: end.toISOString(),
      location: newShift.location,
      description: newShift.description
    });
    setShowAddModal(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Volunteer Schedule</h2>
          <p className="text-slate-500">View and manage your volunteering commitments</p>
        </div>
        <div className="flex items-center gap-2 bg-white p-1 rounded-xl shadow-sm border border-slate-200">
          <button onClick={() => setCurrentDate(subMonths(currentDate, 1))} className="p-2 hover:bg-slate-50 rounded-lg">
            <ChevronLeft size={20} />
          </button>
          <span className="px-4 font-bold min-w-[140px] text-center">
            {format(currentDate, 'MMMM yyyy')}
          </span>
          <button onClick={() => setCurrentDate(addMonths(currentDate, 1))} className="p-2 hover:bg-slate-50 rounded-lg">
            <ChevronRight size={20} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-px bg-slate-200 border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
          <div key={day} className="bg-slate-50 p-4 text-center text-xs font-bold text-slate-400 uppercase tracking-wider">
            {day}
          </div>
        ))}
        {calendarDays.map((day, idx) => {
          const dayShifts = getShiftsForDay(day);
          const isSelected = isSameDay(day, selectedDate);
          const isCurrentMonth = isSameMonth(day, monthStart);
          const isToday = isSameDay(day, new Date());

          return (
            <div
              key={idx}
              onClick={() => setSelectedDate(day)}
              className={`min-h-[120px] p-2 transition-all cursor-pointer group bg-white hover:bg-indigo-50/30 ${
                !isCurrentMonth ? 'bg-slate-50/50 text-slate-300' : 'text-slate-700'
              } ${isSelected ? 'ring-2 ring-inset ring-indigo-500 bg-indigo-50/50' : ''}`}
            >
              <div className="flex justify-between items-start mb-2">
                <span className={`text-sm font-semibold w-7 h-7 flex items-center justify-center rounded-full ${
                  isToday ? 'bg-indigo-600 text-white' : ''
                }`}>
                  {format(day, 'd')}
                </span>
                {dayShifts.length > 0 && (
                  <span className="flex h-2 w-2 rounded-full bg-indigo-500"></span>
                )}
              </div>
              <div className="space-y-1">
                {dayShifts.slice(0, 2).map(shift => (
                  <div key={shift.id} className="text-[10px] p-1.5 bg-indigo-100 text-indigo-700 rounded-md font-medium truncate">
                    {format(parseISO(shift.startTime), 'HH:mm')} - {shift.title}
                  </div>
                ))}
                {dayShifts.length > 2 && (
                  <div className="text-[10px] text-center text-slate-400 font-medium">
                    + {dayShifts.length - 2} more
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Daily Detail and Add Shift */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-2 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-slate-800">
              Shifts for {format(selectedDate, 'MMMM d, yyyy')}
            </h3>
            {isAfter(selectedDate, startOfToday()) && (
              <button 
                onClick={() => setShowAddModal(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-sm text-sm font-medium"
              >
                <Plus size={18} /> Add Shift
              </button>
            )}
          </div>

          <div className="space-y-3">
            {getShiftsForDay(selectedDate).length === 0 ? (
              <div className="p-12 text-center border-2 border-dashed border-slate-200 rounded-2xl bg-white">
                <Calendar className="mx-auto text-slate-300 mb-3" size={48} />
                <p className="text-slate-400">No shifts scheduled for this day.</p>
              </div>
            ) : (
              getShiftsForDay(selectedDate).map(shift => (
                <div key={shift.id} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-start justify-between group">
                  <div className="space-y-3">
                    <div className="flex items-center gap-2">
                      <span className="bg-green-100 text-green-700 p-1 rounded-md">
                        <CheckCircle2 size={16} />
                      </span>
                      <h4 className="font-bold text-slate-800">{shift.title}</h4>
                    </div>
                    <div className="flex flex-wrap gap-4 text-sm text-slate-500">
                      <div className="flex items-center gap-1.5">
                        <Clock size={16} />
                        {format(parseISO(shift.startTime), 'p')} - {format(parseISO(shift.endTime), 'p')}
                      </div>
                      <div className="flex items-center gap-1.5">
                        <MapPin size={16} />
                        {shift.location}
                      </div>
                    </div>
                  </div>
                  {shift.volunteerId === currentUser.id && (
                    <button 
                      onClick={() => onRemoveShift(shift.id)}
                      className="text-slate-400 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                    >
                      Cancel
                    </button>
                  )}
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-indigo-900 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
            <div className="relative z-10">
              <h3 className="text-xl font-bold mb-2">Impact Summary</h3>
              <p className="text-indigo-200 text-sm mb-6">Your contribution this month</p>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-2xl font-bold">{shifts.filter(s => s.volunteerId === currentUser.id && isSameMonth(parseISO(s.startTime), currentDate)).length}</p>
                  <p className="text-xs text-indigo-300 uppercase font-semibold">Shifts</p>
                </div>
                <div>
                  <p className="text-2xl font-bold">{shifts.filter(s => s.volunteerId === currentUser.id && isSameMonth(parseISO(s.startTime), currentDate)).length * 4}</p>
                  <p className="text-xs text-indigo-300 uppercase font-semibold">Hours</p>
                </div>
              </div>
            </div>
            <div className="absolute -right-8 -bottom-8 w-32 h-32 bg-indigo-500 rounded-full blur-3xl opacity-20"></div>
          </div>
        </div>
      </div>

      {/* Add Shift Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl animate-in fade-in zoom-in duration-200">
            <h3 className="text-2xl font-bold text-slate-800 mb-6">Schedule Shift</h3>
            <div className="space-y-5">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Shift Title</label>
                <select 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none"
                  value={newShift.title}
                  onChange={e => setNewShift({...newShift, title: e.target.value})}
                >
                  <option>General Volunteering</option>
                  <option>Reception Desk</option>
                  <option>Kitchen Help</option>
                  <option>Community Garden</option>
