export enum UserStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum UserRole {
  VOLUNTEER = 'VOLUNTEER',
  ADMIN = 'ADMIN'
}

export type ShiftPeriod = 'MORNING' | 'AFTERNOON';

export interface VolunteerProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
  photoUrl: string;
  status: UserStatus;
  role: UserRole;
  joinedAt: string;
}

export interface Shift {
  id: string;
  volunteerId: string;
  date: string; // ISO Date String (YYYY-MM-DD)
  period: ShiftPeriod;
}

export interface AppState {
  currentUser: VolunteerProfile | null;
  volunteers: VolunteerProfile[];
  shifts: Shift[];
}

import React, { useState } from 'react';
import { 
  format, 
  addMonths, 
  subMonths, 
  startOfMonth, 
  endOfMonth, 
  startOfWeek, 
  endOfWeek, 
  eachDayOfInterval, 
  isSameMonth, 
  isSameDay, 
  parseISO,
  isAfter,
  startOfToday
} from 'date-fns';
import { ChevronLeft, ChevronRight, Plus, Clock, Calendar, Trash2 } from 'lucide-react';
import { Shift, VolunteerProfile, ShiftPeriod } from '../types';

interface ShiftCalendarProps {
  shifts: Shift[];
  currentUser: VolunteerProfile;
  onAddShift: (shift: Omit<Shift, 'id' | 'volunteerId'>) => void;
  onRemoveShift: (shiftId: string) => void;
}

const ShiftCalendar: React.FC<ShiftCalendarProps> = ({ 
  shifts, 
  currentUser, 
  onAddShift, 
  onRemoveShift 
}) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedPeriod, setSelectedPeriod] = useState<ShiftPeriod>('MORNING');

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(monthStart);
  const startDate = startOfWeek(monthStart);
  const endDate = endOfWeek(monthEnd);

  const calendarDays = eachDayOfInterval({ start: startDate, end: endDate });

  const getShiftsForDay = (day: Date) => {
    const dateStr = format(day, 'yyyy-MM-dd');
    return shifts.filter(s => s.date === dateStr);
  };

  const handleAddShift = () => {
    onAddShift({
      date: format(selectedDate, 'yyyy-MM-dd'),
      period: selectedPeriod
    });
    setShowAddModal(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Volunteer Schedule</h2>
          <p className="text-slate-500">Pick a day and select Morning or Afternoon</p>
        </div>
        <div className="flex items-center gap-2 bg-white p-1 rounded-xl shadow-sm border border-slate-200">
          <button onClick={() => setCurrentDate(subMonths(currentDate, 1))} className="p-2 hover:bg-slate-50 rounded-lg transition-colors">
            <ChevronLeft size={20} />
          </button>
          <span className="px-4 font-bold min-w-[140px] text-center">
            {format(currentDate, 'MMMM yyyy')}
          </span>
          <button onClick={() => setCurrentDate(addMonths(currentDate, 1))} className="p-2 hover:bg-slate-50 rounded-lg transition-colors">
            <ChevronRight size={20} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-px bg-slate-200 border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
          <div key={day} className="bg-slate-50 p-4 text-center text-xs font-bold text-slate-400 uppercase tracking-wider">
            {day}
          </div>
        ))}
        {calendarDays.map((day, idx) => {
          const dayShifts = getShiftsForDay(day);
          const isSelected = isSameDay(day, selectedDate);
          const isCurrentMonth = isSameMonth(day, monthStart);
          const isToday = isSameDay(day, new Date());

          return (
            <div
              key={idx}
              onClick={() => setSelectedDate(day)}
              className={`min-h-[100px] p-2 transition-all cursor-pointer group bg-white hover:bg-indigo-50/30 ${
                !isCurrentMonth ? 'bg-slate-50/50 text-slate-300' : 'text-slate-700'
              } ${isSelected ? 'ring-2 ring-inset ring-indigo-500 bg-indigo-50/50' : ''}`}
            >
              <div className="flex justify-between items-start mb-2">
                <span className={`text-sm font-semibold w-7 h-7 flex items-center justify-center rounded-full ${
                  isToday ? 'bg-indigo-600 text-white' : ''
                }`}>
                  {format(day, 'd')}
                </span>
              </div>
              <div className="flex flex-col gap-1">
                {dayShifts.map(shift => (
                  <div 
                    key={shift.id} 
                    className={`text-[9px] px-1.5 py-0.5 rounded-full font-bold text-center uppercase tracking-tighter ${
                      shift.period === 'MORNING' ? 'bg-blue-100 text-blue-700' : 'bg-amber-100 text-amber-700'
                    }`}
                  >
                    {shift.period === 'MORNING' ? 'Morning' : 'Afternoon'}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-2 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-slate-800">
              Shifts for {format(selectedDate, 'eeee, MMMM d')}
            </h3>
            {isAfter(selectedDate, startOfToday()) && (
              <button 
                onClick={() => setShowAddModal(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-sm text-sm font-medium"
              >
                <Plus size={18} /> Add Shift
              </button>
            )}
          </div>

          <div className="space-y-3">
            {getShiftsForDay(selectedDate).length === 0 ? (
              <div className="p-12 text-center border-2 border-dashed border-slate-200 rounded-2xl bg-white">
                <Calendar className="mx-auto text-slate-300 mb-3" size={48} />
                <p className="text-slate-400">No shifts scheduled.</p>
              </div>
            ) : (
              getShiftsForDay(selectedDate).map(shift => (
                <div key={shift.id} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between group">
                  <div className="flex items-center gap-4">
                    <div className={`p-3 rounded-xl ${shift.period === 'MORNING' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'}`}>
                      <Clock size={20} />
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-800">
                        {shift.period === 'MORNING' ? 'Morning Shift' : 'Afternoon Shift'}
                      </h4>
                      <p className="text-sm text-slate-500 uppercase tracking-widest font-semibold">
                        {format(parseISO(shift.date), 'eeee')}
                      </p>
                    </div>
                  </div>
                  {shift.volunteerId === currentUser.id && (
                    <button 
                      onClick={() => onRemoveShift(shift.id)}
                      className="text-slate-400 hover:text-red-500 transition-colors p-2"
                      title="Cancel Shift"
                    >
                      <Trash2 size={18} />
                    </button>
                  )}
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-lg relative overflow-hidden">
            <div className="relative z-10">
              <h3 className="text-xl font-bold mb-2">My Stats</h3>
              <p className="text-slate-400 text-sm mb-6">Total shifts this month</p>
              <div className="flex items-end gap-2">
                <p className="text-4xl font-bold text-indigo-400">
                  {shifts.filter(s => s.volunteerId === currentUser.id && isSameMonth(parseISO(s.date), currentDate)).length}
                </p>
                <p className="text-sm text-slate-500 mb-1 font-bold uppercase">Confirmed</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl w-full max-w-sm p-8 shadow-2xl animate-in fade-in zoom-in duration-200">
            <h3 className="text-xl font-bold text-slate-800 mb-2">Schedule Shift</h3>
            <p className="text-slate-500 text-sm mb-6">Select a period for {format(selectedDate, 'MMM d')}</p>

            <div className="space-y-3">
              <button 
                onClick={() => setSelectedPeriod('MORNING')}
                className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${
                  selectedPeriod === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-100 bg-slate-50 text-slate-600'
                }`}
              >
                <div className="flex items-center gap-3 font-bold">
                  <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Clock size={16} /></div>
                  Morning
                </div>
                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${selectedPeriod === 'MORNING' ? 'border-indigo-600' : 'border-slate-300'}`}>
                  {selectedPeriod === 'MORNING' && <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full"></div>}
                </div>
              </button>

              <button 
                onClick={() => setSelectedPeriod('AFTERNOON')}
                className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${
                  selectedPeriod === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-100 bg-slate-50 text-slate-600'
                }`}
              >
                <div className="flex items-center gap-3 font-bold">
                  <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><Clock size={16} /></div>
                  Afternoon
                </div>
                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${selectedPeriod === 'AFTERNOON' ? 'border-indigo-600' : 'border-slate-300'}`}>
                  {selectedPeriod === 'AFTERNOON' && <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full"></div>}
                </div>
              </button>

              <div className="flex gap-3 pt-6">
                <button 
                  onClick={() => setShowAddModal(false)}
                  className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleAddShift}
                  className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-lg"
                >
                  Confirm
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ShiftCalendar;

import React, { useState, useEffect } from 'react';
import { 
  UserStatus, 
  UserRole, 
  VolunteerProfile, 
  Shift, 
  AppState 
} from './types';
import Layout from './components/Layout';
import ShiftCalendar from './components/ShiftCalendar';
import AdminDashboard from './components/AdminDashboard';
import { 
  Heart, 
  Mail, 
  Phone, 
  ShieldCheck, 
  Upload, 
  Search,
  CheckCircle2,
  Clock,
  ExternalLink,
  ArrowRight
} from 'lucide-react';

// Initial Mock Data simplified
const INITIAL_VOLUNTEERS: VolunteerProfile[] = [
  {
    id: 'admin-1',
    name: 'Sarah Admin',
    email: 'admin@handson.org',
    phone: '555-0101',
    photoUrl: 'https://picsum.photos/seed/admin/100/100',
    status: UserStatus.APPROVED,
    role: UserRole.ADMIN,
    joinedAt: new Date().toISOString()
  },
  {
    id: 'vol-1',
    name: 'Alex Johnson',
    email: 'alex@example.com',
    phone: '555-0202',
    photoUrl: 'https://picsum.photos/seed/alex/100/100',
    status: UserStatus.APPROVED,
    role: UserRole.VOLUNTEER,
    joinedAt: new Date().toISOString()
  }
];

// Simplified Shifts (Morning/Afternoon only)
const INITIAL_SHIFTS: Shift[] = [
  {
    id: 's1',
    volunteerId: 'vol-1',
    date: new Date().toISOString().split('T')[0],
    period: 'MORNING'
  }
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
      }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [regForm, setRegForm] = useState({
    name: '',
    email: '',
    phone: ''
  });
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    localStorage.setItem('handson_state', JSON.stringify(appState));
  }, [appState]);

  const handleLogin = (email: string) => {
    if (!email) {
      alert("Please enter an email address.");
      return;
    }
    const user = appState.volunteers.find(v => v.email.toLowerCase() === email.toLowerCase());
    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (user.role === UserRole.ADMIN) setActiveTab('admin');
      else setActiveTab('calendar');
    } else {
      alert("User not found. Try 'admin@handson.org' or apply as a new volunteer.");
    }
  };

  const handleRegister = async () => {
    if (!regForm.name || !regForm.email || !regForm.phone) {
      alert("Please fill in all fields (Name, Email, and Phone).");
      return;
    }

    const newVol: VolunteerProfile = {
      id: Math.random().toString(36).substr(2, 9),
      name: regForm.name,
      email: regForm.email,
      phone: regForm.phone,
      photoUrl: `https://picsum.photos/seed/${regForm.name}/100/100`,
      status: UserStatus.PENDING,
      role: UserRole.VOLUNTEER,
      joinedAt: new Date().toISOString()
    };

    setAppState(prev => ({
      ...prev,
      volunteers: [...prev.volunteers, newVol],
      currentUser: newVol
    }));
    setIsRegistering(false);
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => {
      const updatedVolunteers = prev.volunteers.map(v => v.id === id ? { ...v, status } : v);
      const updatedCurrentUser = prev.currentUser?.id === id 
        ? { ...prev.currentUser, status } 
        : prev.currentUser;

      return {
        ...prev,
        volunteers: updatedVolunteers,
        currentUser: updatedCurrentUser
      };
    });
  };

  const addShift = (shiftData: Omit<Shift, 'id' | 'volunteerId'>) => {
    if (!appState.currentUser) return;
    const newShift: Shift = {
      ...shiftData,
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: appState.currentUser.id
    };
    setAppState(prev => ({
      ...prev,
      shifts: [...prev.shifts, newShift]
    }));
  };

  const removeShift = (id: string) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.filter(s => s.id !== id)
    }));
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-md bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100">
          <div className="bg-indigo-600 p-8 text-center">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 backdrop-blur-md">
              <Heart size={32} fill="currentColor" />
            </div>
            <h1 className="text-3xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 mt-2">Volunteer Portal</p>
          </div>

          {!isRegistering ? (
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Volunteer Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="email" 
                    placeholder="Enter your email"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    onKeyDown={e => e.key === 'Enter' && handleLogin((e.target as HTMLInputElement).value)}
                  />
                </div>
              </div>
              <button 
                onClick={() => {
                  const input = document.querySelector('input[type="email"]') as HTMLInputElement;
                  handleLogin(input.value);
                }}
                className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 flex items-center justify-center gap-2"
              >
                Sign In <ArrowRight size={20} />
              </button>
              <div className="relative py-2">
                <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-100"></div></div>
                <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-slate-400 font-semibold tracking-widest">or join us</span></div>
              </div>
              <button 
                onClick={() => setIsRegistering(true)}
                className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600 transition-all"
              >
                Apply to Volunteer
              </button>
              <div className="text-center">
                <p className="text-xs text-slate-400">Admin Login: admin@handson.org</p>
              </div>
            </div>
          ) : (
            <div className="p-8 space-y-6">
              <div className="flex items-center justify-between">
                <h2 className="text-xl font-bold text-slate-800">New Application</h2>
                <ShieldCheck className="text-indigo-500" size={24} />
              </div>
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase">Full Name</label>
                  <input 
                    placeholder="John Doe"
                    className="w-full mt-1 p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                    value={regForm.name}
                    onChange={e => setRegForm({...regForm, name: e.target.value})}
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase">Email Address</label>
                  <input 
                    placeholder="john@example.com"
                    type="email"
                    className="w-full mt-1 p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                    value={regForm.email}
                    onChange={e => setRegForm({...regForm, email: e.target.value})}
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase">Telephone Number</label>
                  <div className="relative">
                    <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input 
                      placeholder="+1 (555) 000-0000"
                      type="tel"
                      className="w-full pl-10 pr-4 py-3 mt-1 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                      value={regForm.phone}
                      onChange={e => setRegForm({...regForm, phone: e.target.value})}
                    />
                  </div>
                </div>
              </div>
              <div className="flex gap-3 pt-4">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition-colors">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold shadow-lg shadow-indigo-100 transition-transform active:scale-95">Submit</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (appState.currentUser.status === UserStatus.PENDING) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 text-center">
        <div className="max-w-md bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-6">
          <div className="w-24 h-24 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto animate-pulse">
            <Clock size={48} />
          </div>
          <h1 className="text-3xl font-bold text-slate-800">Application Pending</h1>
          <p className="text-slate-500 leading-relaxed">
            Thanks for applying, <span className="font-bold text-indigo-600">{appState.currentUser.name}</span>! 
            Our admins are currently reviewing your details. We'll grant you full access once approved.
          </p>
          <button 
            onClick={() => setAppState(prev => ({...prev, currentUser: null}))}
            className="w-full py-4 bg-slate-800 text-white rounded-2xl font-bold hover:bg-slate-900 transition-colors shadow-lg"
          >
            Sign Out
          </button>
        </div>
      </div>
    );
  }

  const filteredVolunteers = appState.volunteers.filter(v => 
    v.status === UserStatus.APPROVED && 
    (v.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
     v.phone.includes(searchTerm))
  );

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={(t: any) => setActiveTab(t)}
      onLogout={() => setAppState(prev => ({ ...prev, currentUser: null }))}
      role={appState.currentUser.role}
      userName={appState.currentUser.name}
    >
      {activeTab === 'calendar' && (
        <ShiftCalendar 
          shifts={appState.shifts}
          currentUser={appState.currentUser}
          onAddShift={addShift}
          onRemoveShift={removeShift}
        />
      )}

      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">Our Community</h2>
              <p className="text-slate-500">Volunteers dedicated to our cause</p>
            </div>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Search by name or phone..."
                className="w-full md:w-80 pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm hover:shadow-md transition-shadow group">
                <div className="flex items-center gap-4 mb-4">
                  <div className="relative">
                    <img 
                      src={volunteer.photoUrl} 
                      className="w-16 h-16 rounded-2xl object-cover ring-4 ring-indigo-50" 
                      alt={volunteer.name} 
                    />
                    <div className="absolute -bottom-1 -right-1 bg-green-500 w-4 h-4 rounded-full border-2 border-white"></div>
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-800">{volunteer.name}</h3>
                    <p className="text-xs text-indigo-600 font-bold uppercase tracking-wide">Volunteer</p>
                  </div>
                </div>

                <div className="space-y-2 py-2 border-t border-slate-50 mt-2">
                  <div className="flex items-center gap-2 text-sm text-slate-500">
                    <Mail size={14} className="text-indigo-400" />
                    <span className="truncate">{volunteer.email}</span>
                  </div>
                  <div className="flex items-center gap-2 text-sm text-slate-500">
                    <Phone size={14} className="text-indigo-400" />
                    <span>{volunteer.phone}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto space-y-8">
          <div className="bg-white rounded-3xl p-8 border border-slate-100 shadow-sm relative overflow-hidden">
            <div className="absolute top-0 right-0 p-8">
              <span className="px-4 py-1.5 bg-green-100 text-green-700 rounded-full text-xs font-bold flex items-center gap-1.5">
                <ShieldCheck size={14} /> Approved Member
              </span>
            </div>

            <div className="flex flex-col md:flex-row items-center gap-8 relative z-10">
              <div className="relative group">
                <img 
                  src={appState.currentUser.photoUrl} 
                  className="w-32 h-32 md:w-40 md:h-40 rounded-[2.5rem] object-cover ring-8 ring-indigo-50"
                  alt="Profile"
                />
                <button className="absolute bottom-2 right-2 bg-indigo-600 text-white p-2 rounded-xl shadow-lg opacity-0 group-hover:opacity-100 transition-opacity">
                  <Upload size={16} />
                </button>
              </div>
              <div className="flex-1 text-center md:text-left space-y-2">
                <h2 className="text-3xl font-bold text-slate-800">{appState.currentUser.name}</h2>
                <div className="flex flex-wrap justify-center md:justify-start gap-6 text-slate-500">
                  <span className="flex items-center gap-1.5 font-medium"><Mail size={18} className="text-indigo-500" /> {appState.currentUser.email}</span>
                  <span className="flex items-center gap-1.5 font-medium"><Phone size={18} className="text-indigo-500" /> {appState.currentUser.phone}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="md:col-span-2 space-y-6">
              <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm space-y-6 text-center md:text-left">
                <h3 className="text-xl font-bold text-slate-800">Membership Details</h3>
                <div className="grid grid-cols-2 gap-4">
                   <div className="p-4 bg-slate-50 rounded-2xl">
                     <p className="text-xs text-slate-400 font-bold uppercase tracking-wider">Joined</p>
                     <p className="font-bold text-slate-700">{new Date(appState.currentUser.joinedAt).toLocaleDateString()}</p>
                   </div>
                   <div className="p-4 bg-slate-50 rounded-2xl">
                     <p className="text-xs text-slate-400 font-bold uppercase tracking-wider">Status</p>
                     <p className="font-bold text-green-600">Active</p>
                   </div>
                </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100">
                <h4 className="font-bold text-indigo-900 mb-4 flex items-center gap-2">
                  <CheckCircle2 size={18} /> Quick Actions
                </h4>
                <div className="space-y-2">
                  <button onClick={() => setActiveTab('calendar')} className="w-full text-left p-3 bg-white hover:bg-indigo-600 hover:text-white rounded-xl text-sm font-bold text-indigo-700 transition-all flex items-center justify-between group">
                    Schedule Next Shift
                    <ExternalLink size={14} className="opacity-0 group-hover:opacity-100" />
                  </button>
                  <button onClick={() => setActiveTab('volunteers')} className="w-full text-left p-3 bg-white hover:bg-indigo-600 hover:text-white rounded-xl text-sm font-bold text-indigo-700 transition-all flex items-center justify-between group">
                    View Community
                    <ExternalLink size={14} className="opacity-0 group-hover:opacity-100" />
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'admin' && appState.currentUser.role === UserRole.ADMIN && (
        <AdminDashboard 
          volunteers={appState.volunteers}
          onUpdateStatus={updateVolunteerStatus}
        />
      )}
    </Layout>
  );
};

export default App;

export enum UserStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum UserRole {
  VOLUNTEER = 'VOLUNTEER',
  ADMIN = 'ADMIN'
}

export type ShiftPeriod = 'MORNING' | 'AFTERNOON';

export interface VolunteerProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
  photoUrl: string;
  status: UserStatus;
  role: UserRole;
  joinedAt: string;
}

export interface Shift {
  id: string;
  volunteerId: string;
  daysOfWeek: number[]; // 0 for Sunday, 1 for Monday, etc.
  period: ShiftPeriod;
}

export interface AppState {
  currentUser: VolunteerProfile | null;
  volunteers: VolunteerProfile[];
  shifts: Shift[];
}

import React, { useState, useEffect } from 'react';
import { 
  UserStatus, 
  UserRole, 
  VolunteerProfile, 
  Shift, 
  AppState 
} from './types';
import Layout from './components/Layout';
import ShiftCalendar from './components/ShiftCalendar';
import AdminDashboard from './components/AdminDashboard';
import { 
  Heart, 
  Mail, 
  Phone, 
  ShieldCheck, 
  Search,
  CheckCircle2,
  Clock,
  ExternalLink,
  ArrowRight,
  CalendarDays
} from 'lucide-react';

const INITIAL_VOLUNTEERS: VolunteerProfile[] = [
  {
    id: 'admin-1',
    name: 'Sarah Admin',
    email: 'admin@handson.org',
    phone: '555-0101',
    photoUrl: 'https://picsum.photos/seed/admin/100/100',
    status: UserStatus.APPROVED,
    role: UserRole.ADMIN,
    joinedAt: new Date().toISOString()
  },
  {
    id: 'vol-1',
    name: 'Alex Johnson',
    email: 'alex@example.com',
    phone: '555-0202',
    photoUrl: 'https://picsum.photos/seed/alex/100/100',
    status: UserStatus.APPROVED,
    role: UserRole.VOLUNTEER,
    joinedAt: new Date().toISOString()
  }
];

const INITIAL_SHIFTS: Shift[] = [
  {
    id: 's1',
    volunteerId: 'vol-1',
    daysOfWeek: [1, 3, 5], // Mon, Wed, Fri
    period: 'MORNING'
  }
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
      }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [regForm, setRegForm] = useState({ name: '', email: '', phone: '' });
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    localStorage.setItem('handson_state', JSON.stringify(appState));
  }, [appState]);

  const handleLogin = (email: string) => {
    if (!email) {
      alert("Please enter an email address.");
      return;
    }
    const user = appState.volunteers.find(v => v.email.toLowerCase() === email.toLowerCase());
    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (user.role === UserRole.ADMIN) setActiveTab('admin');
      else setActiveTab('calendar');
    } else {
      alert("User not found. Try 'admin@handson.org' or apply as a new volunteer.");
    }
  };

  const handleRegister = async () => {
    if (!regForm.name || !regForm.email || !regForm.phone) {
      alert("Please fill in all fields (Name, Email, and Phone).");
      return;
    }

    const newVol: VolunteerProfile = {
      id: Math.random().toString(36).substr(2, 9),
      name: regForm.name,
      email: regForm.email,
      phone: regForm.phone,
      photoUrl: `https://picsum.photos/seed/${regForm.name}/100/100`,
      status: UserStatus.PENDING,
      role: UserRole.VOLUNTEER,
      joinedAt: new Date().toISOString()
    };

    setAppState(prev => ({
      ...prev,
      volunteers: [...prev.volunteers, newVol],
      currentUser: newVol
    }));
    setIsRegistering(false);
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, status } : prev.currentUser
    }));
  };

  const addShift = (shiftData: Omit<Shift, 'id' | 'volunteerId'>) => {
    if (!appState.currentUser) return;
    const newShift: Shift = {
      ...shiftData,
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: appState.currentUser.id
    };
    setAppState(prev => ({
      ...prev,
      shifts: [...prev.shifts, newShift]
    }));
  };

  const updateShift = (id: string, updatedData: Partial<Shift>) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updatedData } : s)
    }));
  };

  const removeShift = (id: string) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.filter(s => s.id !== id)
    }));
  };

  const getDaysLabel = (days: number[]) => {
    const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return days.sort((a, b) => a - b).map(d => names[d]).join(', ');
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-md bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100">
          <div className="bg-indigo-600 p-8 text-center">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 backdrop-blur-md">
              <Heart size={32} fill="currentColor" />
            </div>
            <h1 className="text-3xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 mt-2">Volunteer Portal</p>
          </div>
          {!isRegistering ? (
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Volunteer Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="email" 
                    placeholder="Enter your email"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                    onKeyDown={e => e.key === 'Enter' && handleLogin((e.target as HTMLInputElement).value)}
                  />
                </div>
              </div>
              <button 
                onClick={() => {
                  const input = document.querySelector('input[type="email"]') as HTMLInputElement;
                  handleLogin(input.value);
                }}
                className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg"
              >
                Sign In <ArrowRight size={20} className="ml-2 inline" />
              </button>
              <div className="relative py-2 text-center">
                <span className="bg-white px-2 text-slate-400 text-xs font-semibold uppercase tracking-widest">or join us</span>
                <div className="absolute inset-0 flex items-center -z-10"><div className="w-full border-t border-slate-100"></div></div>
              </div>
              <button onClick={() => setIsRegistering(true)} className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600">Apply to Volunteer</button>
              <p className="text-center text-xs text-slate-400">Admin Login: admin@handson.org</p>
            </div>
          ) : (
            <div className="p-8 space-y-6">
              <h2 className="text-xl font-bold text-slate-800">New Application</h2>
              <div className="space-y-4">
                <input placeholder="Full Name" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                <input placeholder="Email Address" type="email" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                <input placeholder="Phone Number" type="tel" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
              </div>
              <div className="flex gap-3">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-3 text-slate-500 font-bold">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold">Submit</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (appState.currentUser.status === UserStatus.PENDING) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 text-center">
        <div className="max-w-md bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-6">
          <div className="w-24 h-24 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto animate-pulse">
            <Clock size={48} />
          </div>
          <h1 className="text-3xl font-bold text-slate-800">Application Pending</h1>
          <p className="text-slate-500 leading-relaxed">
            Thanks for applying! Our admins are currently reviewing your details.
          </p>
          <button onClick={() => setAppState(prev => ({...prev, currentUser: null}))} className="w-full py-4 bg-slate-800 text-white rounded-2xl font-bold">Sign Out</button>
        </div>
      </div>
    );
  }

  const filteredVolunteers = appState.volunteers.filter(v => 
    v.status === UserStatus.APPROVED && 
    (v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.phone.includes(searchTerm))
  );

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={(t: any) => setActiveTab(t)}
      onLogout={() => setAppState(prev => ({ ...prev, currentUser: null }))}
      role={appState.currentUser.role}
      userName={appState.currentUser.name}
    >
      {activeTab === 'calendar' && (
        <ShiftCalendar 
          shifts={appState.shifts}
          volunteers={appState.volunteers}
          currentUser={appState.currentUser}
          onAddShift={addShift}
          onUpdateShift={updateShift}
          onRemoveShift={removeShift}
        />
      )}

      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">Our Community</h2>
              <p className="text-slate-500">Volunteers dedicated to our cause</p>
            </div>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Search..."
                className="w-full md:w-80 pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl outline-none"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => {
              const volunteerShifts = appState.shifts.filter(s => s.volunteerId === volunteer.id);
              return (
                <div key={volunteer.id} className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm">
                  <div className="flex items-center gap-4 mb-4">
                    <img src={volunteer.photoUrl} className="w-16 h-16 rounded-2xl object-cover ring-4 ring-indigo-50" alt={volunteer.name} />
                    <div>
                      <h3 className="font-bold text-slate-800">{volunteer.name}</h3>
                      <p className="text-xs text-indigo-600 font-bold uppercase tracking-wide">Volunteer</p>
                    </div>
                  </div>
                  <div className="space-y-2 py-2 border-t border-slate-50 mt-2">
                    <p className="text-sm text-slate-500 flex items-center gap-2"><Phone size={14} className="text-indigo-400" /> {volunteer.phone}</p>
                    {volunteerShifts.length > 0 && (
                      <div className="mt-2 space-y-1">
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Schedule</p>
                        {volunteerShifts.map(s => (
                          <div key={s.id} className="flex items-center gap-1.5 text-xs font-semibold text-slate-600 bg-slate-50 p-1.5 rounded-lg">
                            <CalendarDays size={12} className="text-indigo-500" />
                            <span>{getDaysLabel(s.daysOfWeek)}</span>
                            <span className="text-[10px] text-indigo-400">({s.period})</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto space-y-8">
          <div className="bg-white rounded-3xl p-8 border border-slate-100 shadow-sm relative overflow-hidden">
            <div className="flex flex-col md:flex-row items-center gap-8 relative z-10">
              <img src={appState.currentUser.photoUrl} className="w-32 h-32 md:w-40 md:h-40 rounded-[2.5rem] object-cover ring-8 ring-indigo-50" alt="Profile" />
              <div className="flex-1 text-center md:text-left space-y-2">
                <h2 className="text-3xl font-bold text-slate-800">{appState.currentUser.name}</h2>
                <div className="flex flex-wrap justify-center md:justify-start gap-6 text-slate-500">
                  <span className="flex items-center gap-1.5 font-medium"><Mail size={18} className="text-indigo-500" /> {appState.currentUser.email}</span>
                  <span className="flex items-center gap-1.5 font-medium"><Phone size={18} className="text-indigo-500" /> {appState.currentUser.phone}</span>
                </div>
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm space-y-4">
              <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2"><CheckCircle2 className="text-indigo-500" /> Membership Status</h3>
              <div className="grid grid-cols-2 gap-4">
                 <div className="p-4 bg-slate-50 rounded-2xl"><p className="text-xs text-slate-400 font-bold uppercase">Joined</p><p className="font-bold text-slate-700">{new Date(appState.currentUser.joinedAt).toLocaleDateString()}</p></div>
                 <div className="p-4 bg-green-50 rounded-2xl"><p className="text-xs text-green-400 font-bold uppercase">Status</p><p className="font-bold text-green-600">Active</p></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'admin' && appState.currentUser.role === UserRole.ADMIN && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} />
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  format, 
  addMonths, 
  subMonths, 
  startOfMonth, 
  endOfMonth, 
  startOfWeek, 
  endOfWeek, 
  eachDayOfInterval, 
  isSameMonth, 
  isSameDay, 
  getDay,
  parseISO
} from 'date-fns';
import { ChevronLeft, ChevronRight, Plus, Clock, Calendar, Trash2, Edit2, CalendarDays } from 'lucide-react';
import { Shift, VolunteerProfile, ShiftPeriod } from '../types';

interface ShiftCalendarProps {
  shifts: Shift[];
  volunteers: VolunteerProfile[];
  currentUser: VolunteerProfile;
  onAddShift: (shift: Omit<Shift, 'id' | 'volunteerId'>) => void;
  onUpdateShift: (id: string, updated: Partial<Shift>) => void;
  onRemoveShift: (shiftId: string) => void;
}

const ShiftCalendar: React.FC<ShiftCalendarProps> = ({ 
  shifts, 
  volunteers,
  currentUser, 
  onAddShift, 
  onUpdateShift,
  onRemoveShift 
}) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [editingShiftId, setEditingShiftId] = useState<string | null>(null);

  // Form State
  const [selectedPeriod, setSelectedPeriod] = useState<ShiftPeriod>('MORNING');
  const [selectedDays, setSelectedDays] = useState<number[]>([]);

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(monthStart);
  const startDate = startOfWeek(monthStart);
  const endDate = endOfWeek(monthEnd);
  const calendarDays = eachDayOfInterval({ start: startDate, end: endDate });

  const getShiftsForDay = (day: Date) => {
    const dayOfWeek = getDay(day);
    return shifts.filter(s => s.daysOfWeek.includes(dayOfWeek));
  };

  const handleOpenAdd = () => {
    setEditingShiftId(null);
    setSelectedPeriod('MORNING');
    setSelectedDays([getDay(selectedDate)]);
    setShowModal(true);
  };

  const handleOpenEdit = (shift: Shift) => {
    setEditingShiftId(shift.id);
    setSelectedPeriod(shift.period);
    setSelectedDays([...shift.daysOfWeek]);
    setShowModal(true);
  };

  const handleSave = () => {
    if (selectedDays.length === 0) {
      alert("Please select at least one day.");
      return;
    }

    if (editingShiftId) {
      onUpdateShift(editingShiftId, {
        period: selectedPeriod,
        daysOfWeek: selectedDays
      });
    } else {
      onAddShift({
        period: selectedPeriod,
        daysOfWeek: selectedDays
      });
    }
    setShowModal(false);
  };

  const toggleDay = (day: number) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const dayNames = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
  const fullDayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Community Schedule</h2>
          <p className="text-slate-500">Volunteers commit to recurring weekly blocks</p>
        </div>
        <div className="flex items-center gap-2 bg-white p-1 rounded-xl shadow-sm border border-slate-200">
          <button onClick={() => setCurrentDate(subMonths(currentDate, 1))} className="p-2 hover:bg-slate-50 rounded-lg"><ChevronLeft size={20} /></button>
          <span className="px-4 font-bold min-w-[140px] text-center">{format(currentDate, 'MMMM yyyy')}</span>
          <button onClick={() => setCurrentDate(addMonths(currentDate, 1))} className="p-2 hover:bg-slate-50 rounded-lg"><ChevronRight size={20} /></button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-px bg-slate-200 border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
          <div key={day} className="bg-slate-50 p-4 text-center text-xs font-bold text-slate-400 uppercase tracking-wider">{day}</div>
        ))}
        {calendarDays.map((day, idx) => {
          const dayShifts = getShiftsForDay(day);
          const isSelected = isSameDay(day, selectedDate);
          const isCurrentMonth = isSameMonth(day, monthStart);
          const isToday = isSameDay(day, new Date());

          return (
            <div
              key={idx}
              onClick={() => setSelectedDate(day)}
              className={`min-h-[120px] p-2 transition-all cursor-pointer bg-white hover:bg-indigo-50/30 ${!isCurrentMonth ? 'bg-slate-50/50 text-slate-300' : 'text-slate-700'} ${isSelected ? 'ring-2 ring-inset ring-indigo-500 bg-indigo-50/50' : ''}`}
            >
              <div className="flex justify-between items-start mb-2">
                <span className={`text-sm font-semibold w-7 h-7 flex items-center justify-center rounded-full ${isToday ? 'bg-indigo-600 text-white' : ''}`}>{format(day, 'd')}</span>
              </div>
              <div className="flex flex-col gap-1 overflow-hidden">
                {dayShifts.slice(0, 3).map(shift => {
                  const vol = volunteers.find(v => v.id === shift.volunteerId);
                  return (
                    <div key={shift.id} className={`text-[9px] px-1.5 py-0.5 rounded-md font-bold truncate ${shift.period === 'MORNING' ? 'bg-blue-100 text-blue-700' : 'bg-amber-100 text-amber-700'}`}>
                      {vol?.name}: {shift.period === 'MORNING' ? 'AM' : 'PM'}
                    </div>
                  );
                })}
                {dayShifts.length > 3 && <p className="text-[8px] text-slate-400 font-bold ml-1">+{dayShifts.length - 3} more</p>}
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-2 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-slate-800">My Recurring Blocks</h3>
            <button onClick={handleOpenAdd} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 shadow-sm text-sm font-medium"><Plus size={18} /> Add Block</button>
          </div>

          <div className="space-y-3">
            {shifts.filter(s => s.volunteerId === currentUser.id).length === 0 ? (
              <div className="p-12 text-center border-2 border-dashed border-slate-200 rounded-3xl bg-white">
                <CalendarDays className="mx-auto text-slate-200 mb-3" size={48} />
                <p className="text-slate-400">Set up your weekly availability to help us plan!</p>
              </div>
            ) : (
              shifts.filter(s => s.volunteerId === currentUser.id).map(shift => (
                <div key={shift.id} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between group">
                  <div className="flex items-center gap-4">
                    <div className={`p-3 rounded-xl ${shift.period === 'MORNING' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'}`}><Clock size={20} /></div>
                    <div>
                      <h4 className="font-bold text-slate-800">{shift.period === 'MORNING' ? 'Morning Shift' : 'Afternoon Shift'}</h4>
                      <p className="text-xs text-slate-500 font-semibold">{shift.daysOfWeek.sort().map(d => fullDayNames[d]).join(', ')}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => handleOpenEdit(shift)} className="text-slate-400 hover:text-indigo-600 p-2"><Edit2 size={18} /></button>
                    <button onClick={() => onRemoveShift(shift.id)} className="text-slate-400 hover:text-red-500 p-2"><Trash2 size={18} /></button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-slate-900 text-white p-6 rounded-3xl shadow-lg">
            <h3 className="text-xl font-bold mb-2">Team Activity</h3>
            <p className="text-slate-400 text-sm mb-6">Total recurring commitments</p>
            <div className="flex items-end gap-2">
              <p className="text-4xl font-bold text-indigo-400">{shifts.length}</p>
              <p className="text-sm text-slate-500 mb-1 font-bold uppercase">Weekly Blocks</p>
            </div>
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md">
          <div className="bg-white rounded-[2rem] w-full max-w-md p-8 shadow-2xl animate-in fade-in zoom-in duration-200">
            <h3 className="text-2xl font-bold text-slate-800 mb-2">{editingShiftId ? 'Edit Weekly Schedule' : 'New Weekly Block'}</h3>
            <p className="text-slate-500 text-sm mb-8">Choose when you'll be helping out every week.</p>

            <div className="space-y-6">
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 block">1. Select Days of the Week</label>
                <div className="flex justify-between gap-1">
                  {[0,1,2,3,4,5,6].map(d => (
                    <button
                      key={d}
                      onClick={() => toggleDay(d)}
                      className={`w-10 h-10 rounded-xl font-bold text-sm transition-all border-2 ${selectedDays.includes(d) ? 'bg-indigo-600 border-indigo-600 text-white' : 'border-slate-100 text-slate-400 hover:border-indigo-100'}`}
                    >
                      {dayNames[d]}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 block">2. Select Time Period</label>
                <div className="grid grid-cols-2 gap-3">
                  <button onClick={() => setSelectedPeriod('MORNING')} className={`flex flex-col items-center p-4 rounded-2xl border-2 transition-all ${selectedPeriod === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-100 bg-slate-50 text-slate-400'}`}>
                    <Clock size={24} className="mb-2" />
                    <span className="font-bold">Morning</span>
                  </button>
                  <button onClick={() => setSelectedPeriod('AFTERNOON')} className={`flex flex-col items-center p-4 rounded-2xl border-2 transition-all ${selectedPeriod === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-100 bg-slate-50 text-slate-400'}`}>
                    <Clock size={24} className="mb-2" />
                    <span className="font-bold">Afternoon</span>
                  </button>
                </div>
              </div>

              <div className="flex gap-3 pt-6">
                <button onClick={() => setShowModal(false)} className="flex-1 py-4 text-slate-500 font-bold hover:bg-slate-50 rounded-2xl transition-colors">Cancel</button>
                <button onClick={handleSave} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100">Save Changes</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

