import React, { useState } from 'react';
import { 
  format, 
  addMonths, 
  subMonths, 
  startOfMonth, 
  endOfMonth, 
  startOfWeek, 
  endOfWeek, 
  eachDayOfInterval, 
  isSameMonth, 
  isSameDay, 
  getDay,
  parseISO
} from 'date-fns';
import { ChevronLeft, ChevronRight, Plus, Clock, Calendar, Trash2, Edit2, CalendarDays } from 'lucide-react';
import { Shift, VolunteerProfile, ShiftPeriod } from '../types';

interface ShiftCalendarProps {
  shifts: Shift[];
  volunteers: VolunteerProfile[];
  currentUser: VolunteerProfile;
  onAddShift: (shift: Omit<Shift, 'id' | 'volunteerId'>) => void;
  onUpdateShift: (id: string, updated: Partial<Shift>) => void;
  onRemoveShift: (shiftId: string) => void;
}

const ShiftCalendar: React.FC<ShiftCalendarProps> = ({ 
  shifts, 
  volunteers,
  currentUser, 
  onAddShift, 
  onUpdateShift,
  onRemoveShift 
}) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [editingShiftId, setEditingShiftId] = useState<string | null>(null);

  const [selectedPeriod, setSelectedPeriod] = useState<ShiftPeriod>('MORNING');
  const [selectedDays, setSelectedDays] = useState<number[]>([]);

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(monthStart);
  const startDate = startOfWeek(monthStart);
  const endDate = endOfWeek(monthEnd);
  const calendarDays = eachDayOfInterval({ start: startDate, end: endDate });

  const getShiftsForDay = (day: Date) => {
    const dayOfWeek = getDay(day);
    return shifts.filter(s => s.daysOfWeek.includes(dayOfWeek));
  };

  const handleOpenAdd = () => {
    setEditingShiftId(null);
    setSelectedPeriod('MORNING');
    setSelectedDays([getDay(selectedDate)]);
    setShowModal(true);
  };

  const handleOpenEdit = (shift: Shift) => {
    setEditingShiftId(shift.id);
    setSelectedPeriod(shift.period);
    setSelectedDays([...shift.daysOfWeek]);
    setShowModal(true);
  };

  const handleSave = () => {
    if (selectedDays.length === 0) {
      alert("Please select at least one day.");
      return;
    }
    if (editingShiftId) {
      onUpdateShift(editingShiftId, { period: selectedPeriod, daysOfWeek: selectedDays });
    } else {
      onAddShift({ period: selectedPeriod, daysOfWeek: selectedDays });
    }
    setShowModal(false);
  };

  const toggleDay = (day: number) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const dayNamesShort = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
  const dayNamesMid = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const fullDayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Schedule</h2>
          <p className="text-slate-500 font-medium">Weekly recurring volunteer commitments</p>
        </div>
        <div className="flex items-center gap-1 bg-white p-1 rounded-2xl shadow-sm border border-slate-200">
          <button onClick={() => setCurrentDate(subMonths(currentDate, 1))} className="p-2.5 hover:bg-slate-50 rounded-xl transition-colors text-slate-600">
            <ChevronLeft size={20} />
          </button>
          <span className="px-6 font-bold min-w-[150px] text-center text-slate-800">
            {format(currentDate, 'MMMM yyyy')}
          </span>
          <button onClick={() => setCurrentDate(addMonths(currentDate, 1))} className="p-2.5 hover:bg-slate-50 rounded-xl transition-colors text-slate-600">
            <ChevronRight size={20} />
          </button>
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[2.5rem] overflow-hidden shadow-xl shadow-slate-200/50">
        <div className="grid grid-cols-7 border-b border-slate-100 bg-slate-50/50">
          {dayNamesMid.map(day => (
            <div key={day} className="py-4 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">{day}</div>
          ))}
        </div>
        <div className="grid grid-cols-7">
          {calendarDays.map((day, idx) => {
            const dayShifts = getShiftsForDay(day);
            const isSelected = isSameDay(day, selectedDate);
            const isCurrentMonth = isSameMonth(day, monthStart);
            const isToday = isSameDay(day, new Date());

            return (
              <div
                key={idx}
                onClick={() => setSelectedDate(day)}
                className={`min-h-[100px] md:min-h-[140px] p-2 transition-all cursor-pointer relative ${
                  !isCurrentMonth ? 'bg-slate-50/30 text-slate-300' : 'text-slate-700 bg-white'
                } ${isSelected ? 'z-10 bg-indigo-50/30 ring-2 ring-inset ring-indigo-500' : 'hover:bg-slate-50/80'}`}
              >
                <div className="flex justify-between items-start mb-2">
                  <span className={`text-xs md:text-sm font-bold w-7 h-7 flex items-center justify-center rounded-xl transition-colors ${
                    isToday ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : isSelected ? 'text-indigo-600' : ''
                  }`}>
                    {format(day, 'd')}
                  </span>
                </div>
                <div className="flex flex-col gap-1.5 px-0.5">
                  {dayShifts.slice(0, 3).map(shift => {
                    const vol = volunteers.find(v => v.id === shift.volunteerId);
                    return (
                      <div 
                        key={shift.id} 
                        className={`text-[9px] px-2 py-1 rounded-lg font-bold truncate border shadow-sm ${
                          shift.period === 'MORNING' 
                            ? 'bg-blue-50 border-blue-100 text-blue-700' 
                            : 'bg-amber-50 border-amber-100 text-amber-700'
                        }`}
                      >
                        <span className="opacity-60">{shift.period === 'MORNING' ? 'AM' : 'PM'}</span> {vol?.name}
                      </div>
                    );
                  })}
                  {dayShifts.length > 3 && (
                    <p className="text-[9px] text-slate-400 font-bold px-1 mt-0.5">+{dayShifts.length - 3} more</p>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-xl font-bold text-slate-900">My Availability</h3>
              <p className="text-sm text-slate-500 font-medium">Your personal weekly commitment</p>
            </div>
            <button 
              onClick={handleOpenAdd} 
              className="group flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-200 transition-all active:scale-95 font-bold text-sm"
            >
              <Plus size={20} className="group-hover:rotate-90 transition-transform" /> 
              Add New Block
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 gap-4">
            {shifts.filter(s => s.volunteerId === currentUser.id).length === 0 ? (
              <div className="col-span-full p-16 text-center border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white">
                <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 mx-auto mb-4">
                  <CalendarDays size={32} />
                </div>
                <h4 className="font-bold text-slate-800 mb-1">No weekly schedule set</h4>
                <p className="text-slate-400 text-sm max-w-xs mx-auto font-medium">Add a recurring morning or afternoon block to start volunteering.</p>
              </div>
            ) : (
              shifts.filter(s => s.volunteerId === currentUser.id).map(shift => (
                <div key={shift.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between hover:shadow-md transition-shadow">
                  <div className="flex items-center gap-5">
                    <div className={`p-4 rounded-2xl ${
                      shift.period === 'MORNING' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'
                    }`}>
                      <Clock size={24} />
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg">
                        {shift.period === 'MORNING' ? 'Morning Shift' : 'Afternoon Shift'}
                      </h4>
                      <div className="flex flex-wrap gap-1 mt-1">
                        {shift.daysOfWeek.sort().map(d => (
                          <span key={d} className="text-[10px] font-black uppercase tracking-wider text-slate-400 bg-slate-50 px-2 py-0.5 rounded-md">
                            {dayNamesMid[d]}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => handleOpenEdit(shift)} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"><Edit2 size={18} /></button>
                    <button onClick={() => onRemoveShift(shift.id)} className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white relative overflow-hidden group shadow-2xl shadow-slate-900/20">
            <div className="absolute top-0 right-0 p-8 text-white/5 group-hover:text-white/10 transition-colors">
              <Calendar size={120} />
            </div>
            <div className="relative z-10">
              <h3 className="text-xl font-bold mb-1">Overall Impact</h3>
              <p className="text-slate-400 text-sm font-medium mb-8">Active recurring shifts</p>
              <div className="flex items-baseline gap-3">
                <span className="text-6xl font-black text-indigo-400 tracking-tighter">{shifts.length}</span>
                <div className="space-y-0.5">
                  <p className="text-xs font-black uppercase tracking-widest text-slate-500">Active</p>
                  <p className="text-xs font-black uppercase tracking-widest text-slate-500">Blocks</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl animate-in zoom-in slide-in-from-bottom-8 duration-500">
            <h3 className="text-3xl font-black text-slate-900 mb-2">{editingShiftId ? 'Edit Schedule' : 'New Schedule'}</h3>
            <p className="text-slate-500 font-medium mb-10">Set up your weekly recurring availability.</p>

            <div className="space-y-8">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 block">Days of the Week</label>
                <div className="grid grid-cols-7 gap-2">
                  {[0,1,2,3,4,5,6].map(d => (
                    <button
                      key={d}
                      onClick={() => toggleDay(d)}
                      className={`h-11 rounded-2xl font-black text-xs transition-all border-2 ${
                        selectedDays.includes(d) 
                          ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100' 
                          : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'
                      }`}
                    >
                      {dayNamesShort[d]}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 block">Preferred Period</label>
                <div className="grid grid-cols-2 gap-4">
                  <button 
                    onClick={() => setSelectedPeriod('MORNING')} 
                    className={`flex flex-col items-center gap-3 p-6 rounded-3xl border-2 transition-all group ${
                      selectedPeriod === 'MORNING' 
                        ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700 shadow-lg shadow-indigo-50' 
                        : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                    }`}
                  >
                    <div className={`p-3 rounded-2xl transition-colors ${selectedPeriod === 'MORNING' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-white'}`}>
                      <Clock size={20} />
                    </div>
                    <span className="font-black text-sm uppercase tracking-widest">Morning</span>
                  </button>
                  <button 
                    onClick={() => setSelectedPeriod('AFTERNOON')} 
                    className={`flex flex-col items-center gap-3 p-6 rounded-3xl border-2 transition-all group ${
                      selectedPeriod === 'AFTERNOON' 
                        ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700 shadow-lg shadow-indigo-50' 
                        : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                    }`}
                  >
                    <div className={`p-3 rounded-2xl transition-colors ${selectedPeriod === 'AFTERNOON' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-white'}`}>
                      <Clock size={20} />
                    </div>
                    <span className="font-black text-sm uppercase tracking-widest">Afternoon</span>
                  </button>
                </div>
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => setShowModal(false)} 
                  className="flex-1 py-5 text-slate-400 font-black uppercase tracking-widest text-xs hover:text-slate-600 hover:bg-slate-50 rounded-2xl transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleSave} 
                  className="flex-1 py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:shadow-indigo-200 transition-all active:scale-95"
                >
                  {editingShiftId ? 'Update' : 'Confirm'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

