  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum UserRole {
  VOLUNTEER = 'VOLUNTEER',
  ADMIN = 'ADMIN'
}

export type ShiftPeriod = 'MORNING' | 'AFTERNOON';

export interface VolunteerProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
  birthday: string;
  photoUrl: string;
  status: UserStatus;
  role: UserRole;
  joinedAt: string;
}

export interface Shift {
  id: string;
  volunteerId: string;
  daysOfWeek: number[]; // 0 for Sunday, 1 for Monday, etc.
  period: ShiftPeriod;
}

export interface AppState {
  currentUser: VolunteerProfile | null;
  volunteers: VolunteerProfile[];
  shifts: Shift[];
}

