    name: '', 
    email: '', 
    phone: '', 
    birthday: '',
    preferredPeriod: 'MORNING' as ShiftPeriod,
    selectedDays: [] as number[]
  });

  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    localStorage.setItem('handson_state', JSON.stringify(appState));
  }, [appState]);

  const handleLogin = (email: string) => {
    if (!email) {
      alert("Please enter an email address.");
      return;
    }
    const user = appState.volunteers.find(v => v.email.toLowerCase() === email.toLowerCase());
    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (user.role === UserRole.ADMIN) setActiveTab('admin');
      else setActiveTab('calendar');
    } else {
      alert("User not found. Try 'admin@handson.org' or apply as a new volunteer.");
    }
  };

  const handleRegister = async () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) {
      alert("Please fill in all basic details (Name, Email, Phone, and Birthday).");
      return;
    }

    if (regForm.selectedDays.length === 0) {
      alert("Please select at least one day for your volunteer schedule.");
      return;
    }

    const volunteerId = Math.random().toString(36).substr(2, 9);

    const newVol: VolunteerProfile = {
      id: volunteerId,
      name: regForm.name,
      email: regForm.email,
      phone: regForm.phone,
      birthday: regForm.birthday,
      photoUrl: `https://picsum.photos/seed/${regForm.name}/100/100`,
      status: UserStatus.PENDING,
      role: UserRole.VOLUNTEER,
      joinedAt: new Date().toISOString()
    };

    const newShift: Shift = {
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: volunteerId,
      daysOfWeek: regForm.selectedDays,
      period: regForm.preferredPeriod
    };

    setAppState(prev => ({
      ...prev,
      volunteers: [...prev.volunteers, newVol],
      shifts: [...prev.shifts, newShift],
      currentUser: newVol
    }));
    setIsRegistering(false);
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, status } : prev.currentUser
    }));
  };

  const addShift = (shiftData: Omit<Shift, 'id' | 'volunteerId'>) => {
    if (!appState.currentUser) return;
    const newShift: Shift = {
      ...shiftData,
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: appState.currentUser.id
    };
    setAppState(prev => ({
      ...prev,
      shifts: [...prev.shifts, newShift]
    }));
  };

  const updateShift = (id: string, updatedData: Partial<Shift>) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updatedData } : s)
    }));
  };

  const removeShift = (id: string) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.filter(s => s.id !== id)
    }));
  };

  const toggleRegDay = (day: number) => {
    setRegForm(prev => ({
      ...prev,
      selectedDays: prev.selectedDays.includes(day) 
        ? prev.selectedDays.filter(d => d !== day) 
        : [...prev.selectedDays, day]
    }));
  };

  const getDaysLabel = (days: number[]) => {
    const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return days.sort((a, b) => a - b).map(d => names[d]).join(', ');
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-md'} bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100 transition-all duration-500`}>
          <div className="bg-indigo-600 p-8 text-center">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 backdrop-blur-md">
              <Heart size={32} fill="currentColor" />
            </div>
            <h1 className="text-3xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 mt-2">Volunteer Portal</p>
          </div>

          {!isRegistering ? (
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Volunteer Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="email" 
                    placeholder="Enter your email"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    onKeyDown={e => e.key === 'Enter' && handleLogin((e.target as HTMLInputElement).value)}
                  />
                </div>
              </div>
              <button 
                onClick={() => {
                  const input = document.querySelector('input[type="email"]') as HTMLInputElement;
                  handleLogin(input.value);
                }}
                className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg active:scale-95"
              >
                Sign In <ArrowRight size={20} className="ml-2 inline" />
              </button>
              <div className="relative py-2 text-center">
                <span className="bg-white px-2 text-slate-400 text-xs font-semibold uppercase tracking-widest">or join us</span>
                <div className="absolute inset-0 flex items-center -z-10"><div className="w-full border-t border-slate-100"></div></div>
              </div>
              <button onClick={() => setIsRegistering(true)} className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600 transition-all">Apply to Volunteer</button>
              <p className="text-center text-xs text-slate-400 mt-4">Admin Login: admin@handson.org</p>
            </div>
          ) : (
            <div className="p-8 space-y-10 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div>
                <h2 className="text-2xl font-black text-slate-800 tracking-tight">New Application</h2>
                <p className="text-slate-500 font-medium">Join our mission to help the community.</p>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Personal Details</label>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input placeholder="Full Name" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                    <input placeholder="Email Address" type="email" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                    <input placeholder="Phone Number" type="tel" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    <div className="relative">
                      <Cake className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input 
                        type="date" 
                        title="Birthday"
                        className="w-full pl-10 pr-3 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" 
                        value={regForm.birthday} 
                        onChange={e => setRegForm({...regForm, birthday: e.target.value})} 
                      />
                    </div>
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Weekly Availability</label>
                  <div className="space-y-4">
                    <div className="grid grid-cols-7 gap-1.5">
                      {['S','M','T','W','T','F','S'].map((day, i) => (
                        <button
                          key={i}
                          onClick={() => toggleRegDay(i)}
                          className={`h-10 rounded-xl font-bold text-xs transition-all border-2 ${
                            regForm.selectedDays.includes(i) 
                              ? 'bg-indigo-600 border-indigo-600 text-white shadow-md shadow-indigo-100' 
                              : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'
                          }`}
                        >
                          {day}
                        </button>
                      ))}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <button 
                        onClick={() => setRegForm({...regForm, preferredPeriod: 'MORNING'})}
                        className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all ${
                          regForm.preferredPeriod === 'MORNING' 
                            ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700' 
                            : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                        }`}
                      >
                        <Sun size={18} />
                        <span className="font-bold text-xs uppercase tracking-widest">Morning</span>
                      </button>
                      <button 
                        onClick={() => setRegForm({...regForm, preferredPeriod: 'AFTERNOON'})}
                        className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all ${
                          regForm.preferredPeriod === 'AFTERNOON' 
                            ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700' 
                            : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                        }`}
                      >
                        <Moon size={18} />
                        <span className="font-bold text-xs uppercase tracking-widest">Afternoon</span>
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex gap-4 pt-4 sticky bottom-0 bg-white py-4 border-t border-slate-50">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-black uppercase tracking-widest text-xs hover:text-slate-600 hover:bg-slate-50 rounded-2xl transition-all">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all active:scale-95">Submit Application</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (appState.currentUser.status === UserStatus.PENDING) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 text-center">
        <div className="max-w-md bg-white p-10 rounded-[2.5rem] shadow-xl border border-slate-100 space-y-6">
          <div className="w-24 h-24 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto animate-pulse">
            <Clock size={48} />
          </div>
          <h1 className="text-3xl font-bold text-slate-800">Application Pending</h1>
          <p className="text-slate-500 leading-relaxed">
            Thanks for applying, {appState.currentUser.name}! Our admins are currently reviewing your profile and availability.
          </p>
          <button onClick={() => setAppState(prev => ({...prev, currentUser: null}))} className="w-full py-4 bg-slate-800 text-white rounded-2xl font-bold hover:bg-slate-900 transition-all active:scale-95">Sign Out</button>
        </div>
      </div>
    );
  }

  const filteredVolunteers = appState.volunteers.filter(v => 
    v.status === UserStatus.APPROVED && 
    (v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.phone.includes(searchTerm))
  );

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={(t: any) => setActiveTab(t)}
      onLogout={() => setAppState(prev => ({ ...prev, currentUser: null }))}
      role={appState.currentUser.role}
      userName={appState.currentUser.name}
    >
      {activeTab === 'calendar' && (
        <ShiftCalendar 
          shifts={appState.shifts}
          volunteers={appState.volunteers}
          currentUser={appState.currentUser}
          onAddShift={addShift}
          onUpdateShift={updateShift}
          onRemoveShift={removeShift}
        />
      )}

      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">Our Community</h2>
              <p className="text-slate-500">Volunteers dedicated to our cause</p>
            </div>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="Search community..."
                className="w-full md:w-80 pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all shadow-sm"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => {
              const volunteerShifts = appState.shifts.filter(s => s.volunteerId === volunteer.id);
              return (
                <div key={volunteer.id} className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm hover:shadow-md transition-all">
                  <div className="flex items-center gap-4 mb-4">
                    <img src={volunteer.photoUrl} className="w-16 h-16 rounded-2xl object-cover ring-4 ring-indigo-50" alt={volunteer.name} />
                    <div>
                      <h3 className="font-bold text-slate-800">{volunteer.name}</h3>
                      <p className="text-xs text-indigo-600 font-bold uppercase tracking-wide">Volunteer</p>
                    </div>
                  </div>
                  <div className="space-y-3 py-4 border-t border-slate-50 mt-2">
                    <div className="flex flex-col gap-1.5">
                       <p className="text-sm text-slate-500 flex items-center gap-2"><Phone size={14} className="text-indigo-400" /> {volunteer.phone}</p>
                       <p className="text-sm text-slate-500 flex items-center gap-2"><Cake size={14} className="text-indigo-400" /> Born: {new Date(volunteer.birthday).toLocaleDateString()}</p>
                    </div>
                    {volunteerShifts.length > 0 && (
                      <div className="mt-2 space-y-1">
                        <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Schedule</p>
                        <div className="flex flex-wrap gap-1.5">
                          {volunteerShifts.map(s => (
                            <div key={s.id} className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-tight px-3 py-1.5 rounded-lg border ${
                              s.period === 'MORNING' ? 'bg-blue-50 border-blue-100 text-blue-600' : 'bg-amber-50 border-amber-100 text-amber-600'
                            }`}>
                              {s.period === 'MORNING' ? <Sun size={10}/> : <Moon size={10}/>}
                              <span>{getDaysLabel(s.daysOfWeek)}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto space-y-8">
          <div className="bg-white rounded-3xl p-10 border border-slate-100 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-12 text-slate-50/50 group-hover:scale-110 transition-transform">
              <UserCircle size={200} />
            </div>
            <div className="flex flex-col md:flex-row items-center gap-10 relative z-10">
              <img src={appState.currentUser.photoUrl} className="w-32 h-32 md:w-40 md:h-40 rounded-[2.5rem] object-cover ring-8 ring-indigo-50 shadow-xl" alt="Profile" />
              <div className="flex-1 text-center md:text-left space-y-4">
                <h2 className="text-4xl font-black text-slate-800 tracking-tight">{appState.currentUser.name}</h2>
                <div className="flex flex-wrap justify-center md:justify-start gap-6">
                  <span className="flex items-center gap-2 text-slate-500 font-bold"><Mail size={20} className="text-indigo-500" /> {appState.currentUser.email}</span>
                  <span className="flex items-center gap-2 text-slate-500 font-bold"><Phone size={20} className="text-indigo-500" /> {appState.currentUser.phone}</span>
                </div>
                <div className="flex items-center justify-center md:justify-start gap-2 px-4 py-2 bg-slate-50 rounded-full border border-slate-100 w-fit">
                   <Cake size={16} className="text-indigo-400" />
                   <span className="text-xs font-black uppercase text-slate-400">Birthday: {new Date(appState.currentUser.birthday).toLocaleDateString()}</span>
                </div>
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm space-y-6">
              <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg"><CheckCircle2 size={18} /></div>
                Account Details
              </h3>
              <div className="grid grid-cols-2 gap-4">
                 <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100"><p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Joined</p><p className="font-bold text-slate-700">{new Date(appState.currentUser.joinedAt).toLocaleDateString()}</p></div>
                 <div className="p-6 bg-green-50 rounded-[2rem] border border-green-100"><p className="text-[10px] text-green-400 font-black uppercase tracking-widest mb-1">Status</p><p className="font-bold text-green-600">Active</p></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'admin' && appState.currentUser.role === UserRole.ADMIN && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  UserStatus, 
  UserRole, 
  VolunteerProfile, 
  Shift, 
  AppState,
  ShiftPeriod
} from './types';
