               <div>
                 <h3 className="text-3xl font-black text-slate-900 mb-1">Edit Volunteer</h3>
                 <p className="text-slate-500 font-medium italic">{editingVolunteer.name}'s Profile</p>
               </div>
               <button onClick={() => setEditingVolunteer(null)} className="p-3 hover:bg-slate-50 rounded-2xl transition-all text-slate-400 hover:text-slate-600">
                 <X size={24} />
               </button>
            </div>

            <div className="space-y-10">
              {/* Profile Information Section */}
              <section className="space-y-6">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Profile Information</label>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <p className="text-[10px] font-bold text-slate-400 ml-2">Full Name</p>
                    <input 
                      className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-semibold" 
                      value={editingVolunteer.name} 
                      onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { name: e.target.value })} 
                    />
                  </div>
                  <div className="space-y-1.5">
                    <p className="text-[10px] font-bold text-slate-400 ml-2">Email Address</p>
                    <input 
                      className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-semibold" 
                      value={editingVolunteer.email} 
                      onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { email: e.target.value })} 
                    />
                  </div>
                  <div className="space-y-1.5">
                    <p className="text-[10px] font-bold text-slate-400 ml-2">Phone Number</p>
                    <input 
                      className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-semibold" 
                      value={editingVolunteer.phone} 
                      onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { phone: e.target.value })} 
                    />
                  </div>
                  <div className="space-y-1.5">
                    <p className="text-[10px] font-bold text-slate-400 ml-2">Birthday</p>
                    <input 
                      type="date"
                      className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-semibold" 
                      value={editingVolunteer.birthday} 
                      onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { birthday: e.target.value })} 
                    />
                  </div>
                </div>
              </section>

              {/* Schedule Management Section */}
              <section className="space-y-6 pt-4 border-t border-slate-100">
                <div className="flex items-center justify-between">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Weekly Schedule</label>
                  <button 
                    onClick={() => addShiftForVolunteer(editingVolunteer.id, { daysOfWeek: [1], period: 'MORNING' })}
                    className="flex items-center gap-1.5 text-[10px] font-black uppercase text-indigo-600 hover:text-indigo-700 transition-all"
                  >
                    <Plus size={14} /> Add Block
                  </button>
                </div>

                <div className="space-y-3">
                  {appState.shifts.filter(s => s.volunteerId === editingVolunteer.id).length === 0 ? (
                    <p className="text-center py-6 text-sm text-slate-400 italic bg-slate-50 rounded-2xl">No shifts assigned yet.</p>
                  ) : (
                    appState.shifts.filter(s => s.volunteerId === editingVolunteer.id).map(shift => (
                      <div key={shift.id} className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm space-y-4">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                             <button 
                               onClick={() => updateShift(shift.id, { period: 'MORNING' })}
                               className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 transition-all ${
                                 shift.period === 'MORNING' ? 'bg-blue-600 text-white shadow-md shadow-blue-100' : 'bg-slate-50 text-slate-400'
                               }`}
                             >
                               <Sun size={12} /> Morning
                             </button>
                             <button 
                               onClick={() => updateShift(shift.id, { period: 'AFTERNOON' })}
                               className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 transition-all ${
                                 shift.period === 'AFTERNOON' ? 'bg-amber-600 text-white shadow-md shadow-amber-100' : 'bg-slate-50 text-slate-400'
                               }`}
                             >
                               <Moon size={12} /> Afternoon
                             </button>
                          </div>
                          <button 
                            onClick={() => removeShift(shift.id)}
                            className="p-2 text-slate-300 hover:text-red-500 transition-all"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>

                        <div className="flex flex-wrap gap-1.5">
                          {['S','M','T','W','T','F','S'].map((name, i) => (
                            <button
                              key={i}
                              onClick={() => {
                                const newDays = shift.daysOfWeek.includes(i) 
                                  ? shift.daysOfWeek.filter(d => d !== i) 
                                  : [...shift.daysOfWeek, i];
                                updateShift(shift.id, { daysOfWeek: newDays });
                              }}
                              className={`w-9 h-9 rounded-xl text-[10px] font-black transition-all border-2 ${
                                shift.daysOfWeek.includes(i)
                                  ? 'bg-indigo-600 border-indigo-600 text-white'
                                  : 'bg-white border-slate-50 text-slate-300 hover:border-slate-200'
                              }`}
                            >
                              {name}
                            </button>
                          ))}
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </section>

              <div className="flex gap-4 pt-6">
                <button 
                  onClick={() => setEditingVolunteer(null)} 
                  className="w-full py-5 bg-indigo-600 text-white rounded-[2rem] font-black uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
                >
                  Finished Editing
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

