// Reusable Image Capture Component
const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
}> = ({ currentImage, onImageChange, label = "Profile Photo" }) => {
  const [isCameraActive, setIsCameraActive] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCameraActive(true);
      }
    } catch (err) {
      alert("Could not access camera. Please check permissions.");
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        onImageChange(dataUrl);
        stopCamera();
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onImageChange(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-4">
      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">{label}</label>
      <div className="relative group w-32 h-32 mx-auto md:mx-0">
        <img 
          src={currentImage || 'https://via.placeholder.com/150?text=No+Photo'} 
          className="w-full h-full rounded-[2rem] object-cover ring-4 ring-indigo-50 shadow-lg"
          alt="Preview"
        />
        <div className="absolute inset-0 bg-black/40 rounded-[2rem] opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-2 bg-white/20 hover:bg-white/40 rounded-xl text-white transition-all"
            title="Upload Photo"
          >
            <Upload size={18} />
          </button>
          <button 
            onClick={startCamera}
            className="p-2 bg-white/20 hover:bg-white/40 rounded-xl text-white transition-all"
            title="Use Camera"
          >
            <Camera size={18} />
          </button>
        </div>
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileUpload}
      />

      {isCameraActive && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/90 backdrop-blur-xl p-6">
          <div className="bg-white rounded-[3rem] overflow-hidden w-full max-w-lg shadow-2xl animate-in zoom-in duration-300">
            <div className="relative aspect-video bg-black">
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                className="w-full h-full object-cover"
              />
            </div>
            <div className="p-8 flex items-center justify-center gap-6">
              <button 
                onClick={stopCamera}
                className="px-8 py-4 text-slate-400 font-black uppercase tracking-widest text-xs hover:text-slate-600 transition-all"
              >
                Cancel
              </button>
              <button 
                onClick={capturePhoto}
                className="w-16 h-16 bg-indigo-600 text-white rounded-full flex items-center justify-center shadow-xl shadow-indigo-200 hover:scale-110 active:scale-95 transition-all"
              >
                <Camera size={28} />
              </button>
            </div>
          </div>
          <canvas ref={canvasRef} className="hidden" />
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
      }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);

  const [regForm, setRegForm] = useState({ 
    name: '', 
    email: '', 
    phone: '', 
    birthday: '',
    photoUrl: 'https://picsum.photos/seed/newvol/100/100',
    preferredPeriod: 'MORNING' as ShiftPeriod,
    selectedDays: [] as number[]
  });

  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    localStorage.setItem('handson_state', JSON.stringify(appState));
  }, [appState]);

  const handleLogin = (email: string) => {
    if (!email) {
      alert("Please enter an email address.");
      return;
    }
    const user = appState.volunteers.find(v => v.email.toLowerCase() === email.toLowerCase());
    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (user.role === UserRole.ADMIN) setActiveTab('admin');
      else setActiveTab('calendar');
    } else {
      alert("User not found. Try 'admin@handson.org' or apply as a new volunteer.");
    }
  };

  const handleRegister = async () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) {
      alert("Please fill in all basic details (Name, Email, Phone, and Birthday).");
      return;
    }

    if (regForm.selectedDays.length === 0) {
      alert("Please select at least one day for your volunteer schedule.");
      return;
    }

    const volunteerId = Math.random().toString(36).substr(2, 9);

    const newVol: VolunteerProfile = {
      id: volunteerId,
      name: regForm.name,
      email: regForm.email,
      phone: regForm.phone,
      birthday: regForm.birthday,
      photoUrl: regForm.photoUrl,
      status: UserStatus.PENDING,
      role: UserRole.VOLUNTEER,
      joinedAt: new Date().toISOString()
    };

    const newShift: Shift = {
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: volunteerId,
      daysOfWeek: regForm.selectedDays,
      period: regForm.preferredPeriod
    };

    setAppState(prev => ({
      ...prev,
      volunteers: [...prev.volunteers, newVol],
      shifts: [...prev.shifts, newShift],
      currentUser: newVol
    }));
    setIsRegistering(false);
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, status } : prev.currentUser
    }));
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, status }) : null);
    }
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, ...updates } : prev.currentUser
    }));
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const addShiftForVolunteer = (volunteerId: string, shiftData: Omit<Shift, 'id' | 'volunteerId'>) => {
    const newShift: Shift = {
      ...shiftData,
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: volunteerId
    };
    setAppState(prev => ({
      ...prev,
      shifts: [...prev.shifts, newShift]
    }));
  };

  const updateShift = (id: string, updatedData: Partial<Shift>) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updatedData } : s)
    }));
  };

  const removeShift = (id: string) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.filter(s => s.id !== id)
    }));
  };

  const toggleRegDay = (day: number) => {
    setRegForm(prev => ({
      ...prev,
      selectedDays: prev.selectedDays.includes(day) 
        ? prev.selectedDays.filter(d => d !== day) 
        : [...prev.selectedDays, day]
    }));
  };

  const getDaysLabel = (days: number[]) => {
    const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return days.sort((a, b) => a - b).map(d => names[d]).join(', ');
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(
      appState.volunteers
        .filter(v => v.status === UserStatus.APPROVED)
        .map(v => v.id)
    );
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-md'} bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100 transition-all duration-500`}>
          <div className="bg-indigo-600 p-8 text-center">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 backdrop-blur-md">
              <Heart size={32} fill="currentColor" />
            </div>
            <h1 className="text-3xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 mt-2">Volunteer Portal</p>
          </div>

          {!isRegistering ? (
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Volunteer Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="email" 
                    placeholder="Enter your email"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    onKeyDown={e => e.key === 'Enter' && handleLogin((e.target as HTMLInputElement).value)}
                  />
                </div>
              </div>
              <button 
                onClick={() => {
                  const input = document.querySelector('input[type="email"]') as HTMLInputElement;
                  handleLogin(input.value);
                }}
                className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg active:scale-95"
              >
                Sign In <ArrowRight size={20} className="ml-2 inline" />
              </button>
              <div className="relative py-2 text-center">
                <span className="bg-white px-2 text-slate-400 text-xs font-semibold uppercase tracking-widest">or join us</span>
                <div className="absolute inset-0 flex items-center -z-10"><div className="w-full border-t border-slate-100"></div></div>
              </div>
              <button onClick={() => setIsRegistering(true)} className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600 transition-all">Apply to Volunteer</button>
              <p className="text-center text-xs text-slate-400 mt-4">Admin Login: admin@handson.org</p>
            </div>
          ) : (
            <div className="p-8 space-y-10 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div>
                <h2 className="text-2xl font-black text-slate-800 tracking-tight">New Application</h2>
                <p className="text-slate-500 font-medium">Join our mission to help the community.</p>
              </div>

              <div className="space-y-6">
                {/* Photo Selection in Registration */}
                <ImageCapture 
                  currentImage={regForm.photoUrl} 
                  onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} 
                  label="Upload or Capture Photo"
                />

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Personal Details</label>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input placeholder="Full Name" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                    <input placeholder="Email Address" type="email" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                    <input placeholder="Phone Number" type="tel" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    <div className="relative">
                      <Cake className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input 
                        type="date" 
                        title="Birthday"
                        className="w-full pl-10 pr-3 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" 
                        value={regForm.birthday} 
                        onChange={e => setRegForm({...regForm, birthday: e.target.value})} 
                      />
                    </div>
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Weekly Availability</label>
                  <div className="space-y-4">
                    <div className="grid grid-cols-7 gap-1.5">
                      {['S','M','T','W','T','F','S'].map((day, i) => (
                        <button
                          key={i}
                          onClick={() => toggleRegDay(i)}
                          className={`h-10 rounded-xl font-bold text-xs transition-all border-2 ${
                            regForm.selectedDays.includes(i) 
                              ? 'bg-indigo-600 border-indigo-600 text-white shadow-md shadow-indigo-100' 
                              : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'
                          }`}
                        >
                          {day}
                        </button>
                      ))}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <button 
                        onClick={() => setRegForm({...regForm, preferredPeriod: 'MORNING'})}
                        className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all ${
                          regForm.preferredPeriod === 'MORNING' 
                            ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700' 
                            : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                        }`}
                      >
                        <Sun size={18} />
                        <span className="font-bold text-xs uppercase tracking-widest">Morning</span>
                      </button>
                      <button 
                        onClick={() => setRegForm({...regForm, preferredPeriod: 'AFTERNOON'})}
                        className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all ${
                          regForm.preferredPeriod === 'AFTERNOON' 
                            ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700' 
                            : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                        }`}
                      >
                        <Moon size={18} />
                        <span className="font-bold text-xs uppercase tracking-widest">Afternoon</span>
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex gap-4 pt-4 sticky bottom-0 bg-white py-4 border-t border-slate-50">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-black uppercase tracking-widest text-xs hover:text-slate-600 hover:bg-slate-50 rounded-2xl transition-all">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all active:scale-95">Submit Application</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={(t: any) => setActiveTab(t)}
      onLogout={() => setAppState(prev => ({ ...prev, currentUser: null }))}
      role={appState.currentUser.role}
      userName={appState.currentUser.name}
    >
      {activeTab === 'calendar' && (
        <ShiftCalendar 
          shifts={activeShifts}
          volunteers={appState.volunteers}
          currentUser={appState.currentUser}
          onAddShift={(data) => addShiftForVolunteer(appState.currentUser!.id, data)}
          onUpdateShift={updateShift}
          onRemoveShift={removeShift}
        />
      )}

      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div>
              <h2 className="text-3xl font-black text-slate-800 tracking-tight">Our Community</h2>
              <p className="text-slate-500 font-medium">Volunteers dedicated to our cause</p>
            </div>

            <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
              {isAdmin && (
                <button 
                  onClick={() => setShowInactiveInCommunity(!showInactiveInCommunity)}
                  className={`flex items-center justify-center gap-3 px-6 py-3 rounded-2xl font-bold text-sm transition-all border-2 ${
                    showInactiveInCommunity 
                      ? 'bg-slate-800 border-slate-800 text-white shadow-lg' 
                      : 'bg-white border-slate-200 text-slate-500 hover:border-slate-400'
                  }`}
                >
                  {showInactiveInCommunity ? <Eye size={18} /> : <EyeOff size={18} />}
                  <span>{showInactiveInCommunity ? 'Showing Inactive' : 'Hide Inactive'}</span>
                </button>
              )}

              <div className="relative group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors" size={18} />
                <input 
                  type="text" 
                  placeholder="Search community..."
                  className="w-full sm:w-80 pl-11 pr-4 py-3.5 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all shadow-sm"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
              </div>
            </div>
          </div>

          {filteredVolunteers.length === 0 ? (
            <div className="p-20 text-center bg-white border-2 border-dashed border-slate-200 rounded-[3rem]">
              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center text-slate-300 mx-auto mb-6">
                <Search size={40} />
              </div>
              <h3 className="text-xl font-bold text-slate-800 mb-2">No volunteers found</h3>
              <p className="text-slate-400 font-medium">Try adjusting your search or filters.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredVolunteers.map(volunteer => {
                const volunteerShifts = appState.shifts.filter(s => s.volunteerId === volunteer.id);
                const isInactive = volunteer.status === UserStatus.REJECTED;

                return (
                  <div key={volunteer.id} className={`bg-white rounded-[2.5rem] p-8 border transition-all relative overflow-hidden group ${
                    isInactive ? 'border-red-100 bg-slate-50/50 opacity-80' : 'border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1'
                  }`}>
                    {isAdmin && (
                      <button 
                        onClick={() => setEditingVolunteer(volunteer)}
                        className="absolute top-6 right-6 p-2.5 bg-slate-100/50 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"
                      >
                        <Edit2 size={16} />
                      </button>
                    )}

                    <div className="flex items-center gap-5 mb-6">
                      <div className="relative">
                        <img 
                          src={volunteer.photoUrl} 
                          className={`w-20 h-20 rounded-3xl object-cover ring-4 ${isInactive ? 'ring-red-100 grayscale' : 'ring-indigo-50'}`} 
                          alt={volunteer.name} 
                        />
                        {isInactive && (
                          <div className="absolute -bottom-2 -right-2 p-1 bg-red-500 text-white rounded-lg shadow-lg">
                            <Power size={12} />
                          </div>
                        )}
                      </div>
                      <div>
                        <h3 className={`font-black text-xl leading-tight ${isInactive ? 'text-slate-500 italic line-through' : 'text-slate-800'}`}>
                          {volunteer.name}
                        </h3>
                        <div className="flex items-center gap-2 mt-1">
                          {isInactive ? (
                            <span className="text-[10px] font-black uppercase tracking-widest px-2 py-1 bg-red-100 text-red-600 rounded-md">Inactive</span>
                          ) : (
                            <span className="text-[10px] font-black uppercase tracking-widest px-2 py-1 bg-indigo-100 text-indigo-600 rounded-md">Active</span>
                          )}
                        </div>
                      </div>
                    </div>

                    <div className="space-y-4 py-6 border-y border-slate-50">
                      <div className="flex flex-col gap-3">
                         <div className="flex items-center gap-3">
                           <div className="p-2 bg-slate-50 text-slate-400 rounded-lg"><Phone size={14} /></div>
                           <p className="text-sm font-bold text-slate-600">{volunteer.phone}</p>
                         </div>
                         <div className="flex items-center gap-3">
                           <div className="p-2 bg-slate-50 text-slate-400 rounded-lg"><Cake size={14} /></div>
                           <p className="text-sm font-bold text-slate-600">Born: {new Date(volunteer.birthday).toLocaleDateString()}</p>
                         </div>
                      </div>
                    </div>

                    {!isInactive && volunteerShifts.length > 0 && (
                      <div className="mt-6 space-y-3">
                        <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest px-1">Schedule</p>
                        <div className="flex flex-wrap gap-2">
                          {volunteerShifts.map(s => (
                            <div key={s.id} className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-tight px-3 py-2 rounded-xl border ${
                              s.period === 'MORNING' ? 'bg-blue-50 border-blue-100 text-blue-600' : 'bg-amber-50 border-amber-100 text-amber-600'
                            }`}>
                              {s.period === 'MORNING' ? <Sun size={12}/> : <Moon size={12}/>}
                              <span>{getDaysLabel(s.daysOfWeek)}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-8 duration-500">
          <div className="bg-white rounded-[3rem] p-12 border border-slate-100 shadow-sm relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-12 text-slate-50/50 group-hover:scale-110 transition-transform">
              <UserCircle size={240} />
            </div>
            <div className="flex flex-col md:flex-row items-center gap-12 relative z-10">
              {/* Photo Update in My Profile */}
              <ImageCapture 
                currentImage={appState.currentUser.photoUrl}
                onImageChange={(url) => handleUpdateVolunteerProfile(appState.currentUser!.id, { photoUrl: url })}
                label="Update My Photo"
              />
              <div className="flex-1 text-center md:text-left space-y-6">
                <h2 className="text-5xl font-black text-slate-800 tracking-tight">{appState.currentUser.name}</h2>
                <div className="flex flex-wrap justify-center md:justify-start gap-8">
                  <span className="flex items-center gap-3 text-slate-500 font-bold text-lg"><Mail size={24} className="text-indigo-500" /> {appState.currentUser.email}</span>
                  <span className="flex items-center gap-3 text-slate-500 font-bold text-lg"><Phone size={24} className="text-indigo-500" /> {appState.currentUser.phone}</span>
                </div>
                <div className="flex items-center justify-center md:justify-start gap-3 px-6 py-2.5 bg-slate-50 rounded-full border border-slate-100 w-fit">
                   <Cake size={18} className="text-indigo-400" />
                   <span className="text-sm font-black uppercase text-slate-400">Birthday: {new Date(appState.currentUser.birthday).toLocaleDateString()}</span>
                </div>
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm space-y-8">
              <h3 className="text-2xl font-black text-slate-800 flex items-center gap-3">
                <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl"><CheckCircle2 size={24} /></div>
                Account Details
              </h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                 <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-100">
                   <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-2">Joined</p>
