// Reusable Image Capture Component with fixed camera logic
const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
}> = ({ currentImage, onImageChange, label = "Profile Photo" }) => {
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [isInitializing, setIsInitializing] = useState(false);
  const [videoReady, setVideoReady] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Function to stop the camera and cleanup
  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
    setVideoReady(false);
  };

  // Start camera effect
  useEffect(() => {
    let mounted = true;

    const initCamera = async () => {
      if (isCameraActive) {
        setIsInitializing(true);
        setVideoReady(false);
        try {
          // Give the DOM a moment to render the video element if needed
          await new Promise(resolve => setTimeout(resolve, 100));

          const stream = await navigator.mediaDevices.getUserMedia({ 
            video: { 
              facingMode: 'user',
              width: { ideal: 1280 },
              height: { ideal: 720 }
            } 
          });

          if (!mounted) {
            stream.getTracks().forEach(t => t.stop());
            return;
          }

          streamRef.current = stream;
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
            // Explicitly call play() to handle browsers with strict policies
            await videoRef.current.play();
          }
        } catch (err) {
          console.error("Camera access error:", err);
          alert("Could not access camera. Please check permissions.");
          if (mounted) setIsCameraActive(false);
        } finally {
          if (mounted) setIsInitializing(false);
        }
      }
    };

    initCamera();

    return () => {
      mounted = false;
      // We don't stop camera here because this component stays mounted 
      // when isCameraActive toggles. stopCamera handles the toggle.
    };
  }, [isCameraActive]);

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current && videoReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      const width = video.videoWidth;
      const height = video.videoHeight;

      if (width === 0 || height === 0) {
        console.warn("Video dimensions not available");
        return;
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Draw the current frame
        ctx.drawImage(video, 0, 0, width, height);
        // High quality JPEG capture
        const dataUrl = canvas.toDataURL('image/jpeg', 0.92);
        onImageChange(dataUrl);
        stopCamera();
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onImageChange(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-4">
      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">{label}</label>
      <div className="relative group w-32 h-32 mx-auto md:mx-0">
        <img 
          src={currentImage || 'https://via.placeholder.com/150?text=No+Photo'} 
          className="w-full h-full rounded-[2.5rem] object-cover ring-4 ring-indigo-50 shadow-lg transition-all group-hover:scale-[1.02]"
          alt="Preview"
        />
        <div className="absolute inset-0 bg-slate-900/60 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center gap-3 backdrop-blur-[2px]">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-3 bg-white/20 hover:bg-white text-white hover:text-indigo-600 rounded-2xl transition-all hover:scale-110"
            title="Upload Photo"
          >
            <Upload size={18} />
          </button>
          <button 
            onClick={() => setIsCameraActive(true)}
            className="p-3 bg-white/20 hover:bg-white text-white hover:text-indigo-600 rounded-2xl transition-all hover:scale-110"
            title="Use Camera"
          >
            <Camera size={18} />
          </button>
        </div>
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept="image/*" 
        onChange={handleFileUpload}
      />

      {isCameraActive && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/90 backdrop-blur-xl p-6 animate-in fade-in duration-300">
          <div className="bg-white rounded-[3.5rem] overflow-hidden w-full max-w-xl shadow-2xl animate-in zoom-in duration-500 relative">
            <button 
              onClick={stopCamera}
              className="absolute top-6 right-6 z-20 p-4 bg-black/20 hover:bg-black/40 text-white rounded-full backdrop-blur-md transition-all"
            >
              <X size={20} />
            </button>

            <div className="relative aspect-video bg-slate-950 flex items-center justify-center overflow-hidden">
              {isInitializing && (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-white gap-4 bg-slate-900 z-10">
                   <Loader2 className="animate-spin" size={40} />
                   <p className="text-sm font-black uppercase tracking-widest opacity-60">Connecting Camera...</p>
                </div>
              )}

              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted
                onLoadedMetadata={() => setVideoReady(true)}
                className={`w-full h-full object-cover transition-opacity duration-500 ${videoReady ? 'opacity-100' : 'opacity-0'}`}
              />

              {!videoReady && !isInitializing && (
                <div className="absolute inset-0 flex items-center justify-center bg-slate-900 text-white">
                  <p className="text-xs font-bold uppercase tracking-widest opacity-40">Awaiting Video Stream...</p>
                </div>
              )}
            </div>

            <div className="p-10 flex flex-col items-center gap-6">
              <div className="text-center space-y-1">
                <h4 className="text-xl font-black text-slate-800">Camera View</h4>
                <p className="text-slate-400 text-sm font-medium">Capture a clear photo of yourself</p>
              </div>

              <div className="flex items-center gap-8">
                <button 
                  onClick={stopCamera}
                  className="px-8 py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:text-slate-600 transition-all"
                >
                  Cancel
                </button>
                <button 
                  onClick={capturePhoto}
                  disabled={!videoReady}
                  className={`w-20 h-20 rounded-full flex items-center justify-center shadow-2xl transition-all active:scale-90 ${
                    videoReady 
                      ? 'bg-indigo-600 text-white shadow-indigo-200 hover:scale-110' 
                      : 'bg-slate-100 text-slate-300 cursor-not-allowed'
                  }`}
                >
                  <Camera size={32} />
                </button>
                <div className="w-[60px]"></div>
              </div>
            </div>
          </div>
          <canvas ref={canvasRef} className="hidden" />
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
      }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);

  const [regForm, setRegForm] = useState({ 
    name: '', 
    email: '', 
    phone: '', 
    birthday: '',
    photoUrl: 'https://picsum.photos/seed/newvol/100/100',
    preferredPeriod: 'MORNING' as ShiftPeriod,
    selectedDays: [] as number[]
  });

  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    localStorage.setItem('handson_state', JSON.stringify(appState));
  }, [appState]);

  const handleLogin = (email: string) => {
    if (!email) {
      alert("Please enter an email address.");
      return;
    }
    const user = appState.volunteers.find(v => v.email.toLowerCase() === email.toLowerCase());
    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (user.role === UserRole.ADMIN) setActiveTab('admin');
      else setActiveTab('calendar');
    } else {
      alert("User not found. Try 'admin@handson.org' or apply as a new volunteer.");
    }
  };

  const handleRegister = async () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) {
      alert("Please fill in all basic details (Name, Email, Phone, and Birthday).");
      return;
    }

    if (regForm.selectedDays.length === 0) {
      alert("Please select at least one day for your volunteer schedule.");
      return;
    }

    const volunteerId = Math.random().toString(36).substr(2, 9);

    const newVol: VolunteerProfile = {
      id: volunteerId,
      name: regForm.name,
      email: regForm.email,
      phone: regForm.phone,
      birthday: regForm.birthday,
      photoUrl: regForm.photoUrl,
      status: UserStatus.PENDING,
      role: UserRole.VOLUNTEER,
      joinedAt: new Date().toISOString()
    };

    const newShift: Shift = {
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: volunteerId,
      daysOfWeek: regForm.selectedDays,
      period: regForm.preferredPeriod
    };

    setAppState(prev => ({
      ...prev,
      volunteers: [...prev.volunteers, newVol],
      shifts: [...prev.shifts, newShift],
      currentUser: newVol
    }));
    setIsRegistering(false);
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, status } : prev.currentUser
    }));
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, status }) : null);
    }
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, ...updates } : prev.currentUser
    }));
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const addShiftForVolunteer = (volunteerId: string, shiftData: Omit<Shift, 'id' | 'volunteerId'>) => {
    const newShift: Shift = {
      ...shiftData,
      id: Math.random().toString(36).substr(2, 9),
      volunteerId: volunteerId
    };
    setAppState(prev => ({
      ...prev,
      shifts: [...prev.shifts, newShift]
    }));
  };

  const updateShift = (id: string, updatedData: Partial<Shift>) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updatedData } : s)
    }));
  };

  const removeShift = (id: string) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.filter(s => s.id !== id)
    }));
  };

  const toggleRegDay = (day: number) => {
    setRegForm(prev => ({
      ...prev,
      selectedDays: prev.selectedDays.includes(day) 
        ? prev.selectedDays.filter(d => d !== day) 
        : [...prev.selectedDays, day]
    }));
  };

  const getDaysLabel = (days: number[]) => {
    const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return days.sort((a, b) => a - b).map(d => names[d]).join(', ');
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(
      appState.volunteers
        .filter(v => v.status === UserStatus.APPROVED)
        .map(v => v.id)
    );
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  const filteredVolunteers = useMemo(() => {
    return appState.volunteers.filter(v => {
      const searchMatch = 
        v.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.phone.includes(searchTerm);

      if (!searchMatch) return false;
      if (v.role === UserRole.ADMIN) return false;

      const isApproved = v.status === UserStatus.APPROVED;
      const isRejected = v.status === UserStatus.REJECTED;

      if (showInactiveInCommunity) {
        return isApproved || isRejected;
      }
      return isApproved;
    });
  }, [appState.volunteers, searchTerm, showInactiveInCommunity]);

  const isAdmin = appState.currentUser?.role === UserRole.ADMIN;

  if (!appState.currentUser) {
