                <span className="bg-white px-2 text-slate-400 text-xs font-semibold uppercase tracking-widest">or join us</span>
                <div className="absolute inset-0 flex items-center -z-10"><div className="w-full border-t border-slate-100"></div></div>
              </div>
              <button onClick={() => setIsRegistering(true)} className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600 transition-all">Apply to Volunteer</button>
              <p className="text-center text-xs text-slate-400 mt-4">Admin Login: admin@handson.org</p>
            </div>
          ) : (
            <div className="p-8 space-y-10 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div>
