                    <input placeholder="Full Name" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                    <input placeholder="Email Address" type="email" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                    <input placeholder="Phone Number" type="tel" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
