/**
 * Simplified Image Capture Component
 * Uses native device camera/file picker.
 * Resizes images to keep localStorage strings manageable.
 */
const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
}> = ({ currentImage, onImageChange, label = "Profile Photo" }) => {
  const libraryInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const resizeImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 400;
        const MAX_HEIGHT = 400;
        let width = img.width;
        let height = img.height;

        if (width > height) {
          if (width > MAX_WIDTH) {
            height *= MAX_WIDTH / width;
            width = MAX_WIDTH;
          }
        } else {
          if (height > MAX_HEIGHT) {
            width *= MAX_HEIGHT / height;
            height = MAX_HEIGHT;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const resized = await resizeImage(reader.result as string);
        onImageChange(resized);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-4">
      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">{label}</label>
      <div className="flex flex-col md:flex-row items-center gap-6">
        <div className="relative w-32 h-32">
          {isProcessing ? (
            <div className="w-full h-full rounded-[2.5rem] bg-slate-100 flex items-center justify-center border-2 border-indigo-100">
               <Loader2 className="animate-spin text-indigo-500" size={24} />
            </div>
          ) : (
            <img 
              src={currentImage || 'https://via.placeholder.com/150?text=No+Photo'} 
              className="w-full h-full rounded-[2.5rem] object-cover ring-4 ring-indigo-50 shadow-lg"
              alt="Preview"
            />
          )}
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <button 
            type="button"
            onClick={() => cameraInputRef.current?.click()}
            className="flex items-center gap-2 px-5 py-3 bg-indigo-600 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg active:scale-95"
          >
            <Camera size={18} />
            Camera
          </button>

          <button 
            type="button"
            onClick={() => libraryInputRef.current?.click()}
            className="flex items-center gap-2 px-5 py-3 bg-white border-2 border-slate-100 text-slate-600 rounded-2xl font-bold text-xs uppercase tracking-widest hover:border-indigo-200 hover:text-indigo-600 transition-all active:scale-95"
          >
            <ImageIcon size={18} />
            Library
          </button>
        </div>
      </div>

      <input type="file" ref={libraryInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
      <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
    </div>
  );
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error("Failed to load state", e);
      }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);

  const [regForm, setRegForm] = useState({ 
    name: '', 
    email: '', 
    phone: '', 
    birthday: '',
    photoUrl: 'https://picsum.photos/seed/newvol/100/100',
    preferredPeriod: 'MORNING' as ShiftPeriod,
    selectedDays: [] as number[]
  });

  const [searchTerm, setSearchTerm] = useState('');

  // Save state to localStorage with quota protection
  useEffect(() => {
    try {
      localStorage.setItem('handson_state', JSON.stringify(appState));
    } catch (e) {
      console.warn("LocalStorage quota exceeded, could not save state changes.");
    }
  }, [appState]);

  const handleLogin = (email: string) => {
    if (!email) return alert("Enter your email.");
    const user = appState.volunteers.find(v => v.email.toLowerCase() === email.trim().toLowerCase());
    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      setActiveTab(user.role === UserRole.ADMIN ? 'admin' : 'calendar');
    } else {
      alert("User not found. Try 'admin@handson.org' or apply as a new volunteer.");
    }
  };

  const handleRegister = () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) {
      return alert("Please fill in all details.");
    }
    if (regForm.selectedDays.length === 0) {
      return alert("Select at least one day for your schedule.");
    }

    const volunteerId = Math.random().toString(36).substring(2, 11);
    const newVol: VolunteerProfile = {
      id: volunteerId,
      name: regForm.name,
      email: regForm.email,
      phone: regForm.phone,
      birthday: regForm.birthday,
      photoUrl: regForm.photoUrl,
      status: UserStatus.PENDING,
      role: UserRole.VOLUNTEER,
      joinedAt: new Date().toISOString()
    };

    const newShift: Shift = {
      id: Math.random().toString(36).substring(2, 11),
      volunteerId: volunteerId,
      daysOfWeek: regForm.selectedDays,
      period: regForm.preferredPeriod
    };

    setAppState(prev => ({
      ...prev,
      volunteers: [...prev.volunteers, newVol],
      shifts: [...prev.shifts, newShift],
      currentUser: newVol
    }));
    setActiveTab('calendar');
    setIsRegistering(false);
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, status } : prev.currentUser
    }));
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser, ...updates } : prev.currentUser
    }));
  };

  const addShiftForVolunteer = (volunteerId: string, shiftData: Omit<Shift, 'id' | 'volunteerId'>) => {
    setAppState(prev => ({
      ...prev,
      shifts: [...prev.shifts, { ...shiftData, id: Math.random().toString(36).substring(2, 11), volunteerId }]
    }));
  };

  const updateShift = (id: string, updatedData: Partial<Shift>) => {
    setAppState(prev => ({
      ...prev,
      shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updatedData } : s)
    }));
  };

  const removeShift = (id: string) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.filter(s => s.id !== id) }));
  };

  const toggleRegDay = (day: number) => {
    setRegForm(prev => ({
      ...prev,
      selectedDays: prev.selectedDays.includes(day) 
        ? prev.selectedDays.filter(d => d !== day) 
        : [...prev.selectedDays, day]
    }));
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(
      appState.volunteers.filter(v => v.status === UserStatus.APPROVED).map(v => v.id)
    );
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  const filteredVolunteers = useMemo(() => {
    return appState.volunteers.filter(v => {
      const searchMatch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!searchMatch || v.role === UserRole.ADMIN) return false;
      return showInactiveInCommunity || v.status === UserStatus.APPROVED;
    });
  }, [appState.volunteers, searchTerm, showInactiveInCommunity]);

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-md'} bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-100 transition-all duration-500`}>
          <div className="bg-indigo-600 p-8 text-center">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 backdrop-blur-md">
              <Heart size={32} fill="currentColor" />
            </div>
            <h1 className="text-3xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 mt-2">Volunteer Portal</p>
          </div>

          {!isRegistering ? (
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Volunteer Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="email" 
                    placeholder="Enter your email"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    onKeyDown={e => e.key === 'Enter' && handleLogin((e.target as HTMLInputElement).value)}
                  />
                </div>
              </div>
              <button 
                onClick={() => handleLogin((document.querySelector('input[type="email"]') as HTMLInputElement)?.value || '')}
                className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2"
              >
                Sign In <ArrowRight size={20} />
              </button>
              <div className="relative py-2 text-center">
                <span className="bg-white px-2 text-slate-400 text-xs font-semibold uppercase tracking-widest">or join us</span>
                <div className="absolute inset-0 flex items-center -z-10"><div className="w-full border-t border-slate-100"></div></div>
              </div>
              <button onClick={() => setIsRegistering(true)} className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600 transition-all">Apply to Volunteer</button>
              <p className="text-center text-[10px] text-slate-400 mt-4 uppercase font-black tracking-widest">Admin: admin@handson.org</p>
            </div>
          ) : (
            <div className="p-8 space-y-10 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight">New Application</h2>
                  <p className="text-slate-500 font-medium">Join our mission to help the community.</p>
                </div>
                <button onClick={() => setIsRegistering(false)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors"><X size={24} /></button>
              </div>

              <div className="space-y-8">
                <ImageCapture 
                  currentImage={regForm.photoUrl} 
                  onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} 
                  label="Profile Photo"
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <input placeholder="Full Name" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  <input placeholder="Email" type="email" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                  <input placeholder="Phone" type="tel" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                  <input type="date" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Availability</label>
                  <div className="grid grid-cols-7 gap-1.5">
                    {['S','M','T','W','T','F','S'].map((day, i) => (
                      <button key={i} onClick={() => toggleRegDay(i)} className={`h-10 rounded-xl font-bold text-xs transition-all border-2 ${regForm.selectedDays.includes(i) ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>
                        {day}
                      </button>
                    ))}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'MORNING'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}>
                      <Sun size={18} /> Morning
                    </button>
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'AFTERNOON'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}>
                      <Moon size={18} /> Afternoon
                    </button>
                  </div>
                </div>
              </div>

              <div className="pt-4 sticky bottom-0 bg-white py-4 border-t border-slate-50 flex gap-4">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-bold uppercase tracking-widest text-xs hover:bg-slate-50 rounded-2xl transition-all">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Submit Application</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={(t: any) => setActiveTab(t)}
      onLogout={() => setAppState(prev => ({ ...prev, currentUser: null }))}
      role={appState.currentUser.role}
      userName={appState.currentUser.name}
    >
      {activeTab === 'calendar' && (
        <ShiftCalendar 
          shifts={activeShifts}
          volunteers={appState.volunteers}
          currentUser={appState.currentUser}
          onAddShift={(data) => addShiftForVolunteer(appState.currentUser!.id, data)}
          onUpdateShift={updateShift}
          onRemoveShift={removeShift}
        />
      )}

      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex items-center justify-between">
            <h2 className="text-3xl font-black text-slate-800 tracking-tight">Community</h2>
            <div className="flex items-center gap-4">
               {isAdmin && (
                <button onClick={() => setShowInactiveInCommunity(!showInactiveInCommunity)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${showInactiveInCommunity ? 'bg-slate-800 border-slate-800 text-white' : 'bg-white border-slate-200 text-slate-500'}`}>
                  {showInactiveInCommunity ? 'Showing Inactive' : 'Hide Inactive'}
                </button>
               )}
               <input type="text" placeholder="Search..." className="p-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm w-48 md:w-64" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm relative group hover:shadow-lg transition-all">
                <div className="flex items-center gap-4">
                  <img src={volunteer.photoUrl} className={`w-16 h-16 rounded-2xl object-cover ring-4 ${volunteer.status === UserStatus.APPROVED ? 'ring-indigo-50' : 'ring-red-50 grayscale'}`} />
                  <div>
                    <h3 className="font-bold text-slate-800 truncate max-w-[150px]">{volunteer.name}</h3>
                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{volunteer.status}</p>
                  </div>
                </div>
                {isAdmin && (
                  <button onClick={() => setEditingVolunteer(volunteer)} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-indigo-600 transition-all"><Edit2 size={16} /></button>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'profile' && (
        <div className="max-w-xl mx-auto bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm space-y-8">
          <ImageCapture 
            currentImage={appState.currentUser.photoUrl}
            onImageChange={(url) => handleUpdateVolunteerProfile(appState.currentUser!.id, { photoUrl: url })}
            label="My Profile Photo"
          />
          <div className="space-y-4">
             <div>
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Full Name</label>
               <input className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-700" value={appState.currentUser.name} readOnly />
             </div>
             <div>
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Email</label>
               <input className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-700" value={appState.currentUser.email} readOnly />
             </div>
          </div>
        </div>
      )}

      {activeTab === 'admin' && isAdmin && (
        <AdminDashboard 
          volunteers={appState.volunteers} 
          onUpdateStatus={updateVolunteerStatus} 
          onEditVolunteer={setEditingVolunteer}
        />
      )}

      {editingVolunteer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-md">
          <div className="bg-white rounded-[3rem] w-full max-w-lg p-10 shadow-2xl space-y-8 max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between">
               <h3 className="text-2xl font-black text-slate-900">Edit Profile</h3>
               <button onClick={() => setEditingVolunteer(null)} className="p-2 text-slate-400 hover:text-slate-600 transition-all"><X size={24} /></button>
            </div>
            <ImageCapture 
              currentImage={editingVolunteer.photoUrl}
              onImageChange={(url) => handleUpdateVolunteerProfile(editingVolunteer.id, { photoUrl: url })}
            />
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.APPROVED)} className={`p-4 rounded-2xl border-2 font-bold text-xs uppercase transition-all ${editingVolunteer.status === UserStatus.APPROVED ? 'border-green-600 bg-green-50 text-green-700' : 'border-slate-50 text-slate-400'}`}>Approve</button>
                <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.REJECTED)} className={`p-4 rounded-2xl border-2 font-bold text-xs uppercase transition-all ${editingVolunteer.status === UserStatus.REJECTED ? 'border-red-600 bg-red-50 text-red-700' : 'border-slate-50 text-slate-400'}`}>Deactivate</button>
              </div>
            </div>
            <button onClick={() => setEditingVolunteer(null)} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold uppercase text-xs tracking-widest">Done</button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Users, 
  Calendar, 
  UserCircle, 
  LogOut, 
  LayoutDashboard,
  Heart,
  Menu,
  X
} from 'lucide-react';
import { UserRole } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
  onLogout: () => void;
  role: UserRole;
  userName: string;
}

const Layout: React.FC<LayoutProps> = ({ 
  children, 
  activeTab, 
  onTabChange, 
  onLogout, 
  role,
  userName 
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const isAdmin = role === UserRole.ADMIN;

  const navItems = [
    ...(isAdmin ? [{ id: 'admin', label: 'Admin Dashboard', icon: LayoutDashboard }] : []),
    { id: 'calendar', label: 'Schedule', icon: Calendar },
    { id: 'volunteers', label: 'Community', icon: Users },
    { id: 'profile', label: 'My Profile', icon: UserCircle },
  ];

  const currentNavItem = navItems.find(i => i.id === activeTab);

  const handleNavClick = (id: string) => {
    onTabChange(id);
    setIsOpen(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-inter">
      <header className="sticky top-0 z-[60] bg-white/80 backdrop-blur-xl border-b border-slate-200 px-6 py-4 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsOpen(!isOpen)}
            className="p-2.5 bg-slate-100 hover:bg-slate-200 rounded-xl transition-all text-slate-600"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>

          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
              <Heart size={20} fill="currentColor" />
            </div>
            <span className="font-black text-xl text-slate-900 tracking-tight hidden sm:block">HandsOn</span>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="hidden md:flex items-center gap-3 px-4 py-2 bg-slate-50 rounded-full border border-slate-100">
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
            <span className="text-xs font-bold text-slate-600 truncate max-w-[150px]">{userName}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-slate-400 hover:text-red-500 transition-colors">
            <LogOut size={20} />
          </button>
        </div>
      </header>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-[55] bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsOpen(false)} />
          <div className="fixed top-[73px] left-0 bottom-0 w-80 bg-white z-[56] border-r border-slate-200 shadow-2xl animate-in slide-in-from-left duration-300 flex flex-col">
            <nav className="flex-1 p-6 space-y-2">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 px-3">Navigation</p>
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavClick(item.id)}
                  className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all group ${
                    activeTab === item.id ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <item.icon size={22} />
                  <span className="font-bold">{item.label}</span>
                </button>
              ))}
            </nav>
          </div>
        </>
      )}

      <main className="flex-1">
        <div className="max-w-6xl mx-auto p-6 md:p-10">
          {currentNavItem && (
            <div className="mb-8 flex items-center gap-3">
               <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
                  {React.createElement(currentNavItem.icon, { size: 18 })}
               </div>
               <h2 className="text-sm font-black uppercase tracking-[0.2em] text-slate-400">
                 {currentNavItem.label}
               </h2>
            </div>
          )}
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserStatus, 
  UserRole, 
  VolunteerProfile, 
  Shift, 
  AppState,
  ShiftPeriod
} from './types';
import Layout from './components/Layout';
import ShiftCalendar from './components/ShiftCalendar';
import AdminDashboard from './components/AdminDashboard';
