const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
}> = ({ currentImage, onImageChange, label = "Profile Photo" }) => {
  const libraryInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const resizeImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_SIZE = 400;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const resized = await resizeImage(reader.result as string);
        onImageChange(resized);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-4">
      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">{label}</label>
      <div className="flex flex-col md:flex-row items-center gap-6">
        <div className="relative w-32 h-32 shrink-0">
          {isProcessing ? (
            <div className="w-full h-full rounded-[2.5rem] bg-slate-100 flex items-center justify-center border-2 border-indigo-100">
               <Loader2 className="animate-spin text-indigo-500" size={24} />
            </div>
          ) : (
            <img 
              src={currentImage || 'https://via.placeholder.com/150?text=No+Photo'} 
              className="w-full h-full rounded-[2.5rem] object-cover ring-4 ring-indigo-50 shadow-lg"
              alt="Preview"
            />
          )}
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <button type="button" onClick={() => cameraInputRef.current?.click()} className="flex items-center gap-2 px-5 py-3 bg-indigo-600 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg active:scale-95">
            <Camera size={18} /> Camera
          </button>
          <button type="button" onClick={() => libraryInputRef.current?.click()} className="flex items-center gap-2 px-5 py-3 bg-white border-2 border-slate-100 text-slate-600 rounded-2xl font-bold text-xs uppercase tracking-widest hover:border-indigo-200 hover:text-indigo-600 transition-all active:scale-95">
            <ImageIcon size={18} /> Library
          </button>
        </div>
      </div>
      <input type="file" ref={libraryInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
      <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
    </div>
  );
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return {
          currentUser: parsed.currentUser || null,
          volunteers: parsed.volunteers || INITIAL_VOLUNTEERS,
          shifts: parsed.shifts || INITIAL_SHIFTS
        };
      } catch (e) { console.error("Failed to load state", e); }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', preferredPeriod: 'MORNING' as ShiftPeriod, selectedDays: [] as number[], volunteerType: VolunteerType.VTC, area: ''
  });

  useEffect(() => {
    try { localStorage.setItem('handson_state', JSON.stringify(appState)); } catch (e) { console.warn("Storage error:", e); }
  }, [appState]);

  const handleLogout = () => {
    setAppState(prev => ({ ...prev, currentUser: null }));
    setActiveTab('calendar');
    setIsRegistering(false);
  };

  const handleLogin = (email: string) => {
    if (!email) return alert("Please enter your email.");
    const user = appState.volunteers.find(v => v.email.toLowerCase() === email.trim().toLowerCase());
    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      setActiveTab(user.role === UserRole.ADMIN ? 'admin' : 'calendar');
    } else { alert("Account not found. Apply to join us!"); }
  };

  const handleRegister = () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return alert("Please fill in all details.");
    if (regForm.volunteerType === VolunteerType.BASE && !regForm.area) return alert("Please specify your Area for BASE role.");
    if (regForm.selectedDays.length === 0) return alert("Select at least one day for your schedule.");

    const volunteerId = Math.random().toString(36).substring(2, 11);
    const newVol: VolunteerProfile = { 
      id: volunteerId, 
      name: regForm.name, 
      email: regForm.email, 
      phone: regForm.phone, 
      birthday: regForm.birthday, 
      photoUrl: regForm.photoUrl, 
      status: UserStatus.PENDING, 
      role: UserRole.VOLUNTEER, 
      volunteerType: regForm.volunteerType,
      area: regForm.volunteerType === VolunteerType.BASE ? regForm.area : undefined,
      joinedAt: new Date().toISOString() 
    };

    const newShift: Shift = { id: Math.random().toString(36).substring(2, 11), volunteerId: volunteerId, daysOfWeek: regForm.selectedDays, period: regForm.preferredPeriod };
    setAppState(prev => ({ ...prev, volunteers: [...prev.volunteers, newVol], shifts: [...prev.shifts, newShift], currentUser: newVol }));
    setActiveTab('profile');
    setIsRegistering(false);
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, status } : prev.currentUser
    }));
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => {
      const newVols = prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v);
      return {
        ...prev,
        volunteers: newVols,
        currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, ...updates } : prev.currentUser,
      };
    });
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const handleUpdateShift = (id: string, updated: Partial<Shift>) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updated } : s) }));
  };

  const handleAddShift = (shift: Omit<Shift, 'id'>) => {
    const newShift = { ...shift, id: Math.random().toString(36).substring(2, 11) };
    setAppState(prev => ({ ...prev, shifts: [...prev.shifts, newShift] }));
  };

  const handleRemoveShift = (id: string) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.filter(s => s.id !== id) }));
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(appState.volunteers.filter(v => v.status === UserStatus.APPROVED).map(v => v.id));
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  const filteredVolunteers = useMemo(() => {
    return appState.volunteers.filter(v => {
      const searchMatch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!searchMatch || v.role === UserRole.ADMIN) return false;
      return showInactiveInCommunity || v.status === UserStatus.APPROVED;
    });
  }, [appState.volunteers, searchTerm, showInactiveInCommunity]);

  const getStatusLabel = (status: UserStatus) => {
    switch (status) {
      case UserStatus.APPROVED: return 'Active';
      case UserStatus.REJECTED: return 'Inactive';
      case UserStatus.PENDING: return 'Pending';
      default: return status;
    }
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-md'} bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-100 transition-all duration-500`}>
          <div className="bg-indigo-600 p-8 text-center">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 backdrop-blur-md"><Heart size={32} fill="currentColor" /></div>
            <h1 className="text-3xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 mt-2">Volunteer Portal</p>
          </div>
          {!isRegistering ? (
            <div className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Volunteer Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="email" placeholder="Enter your email" className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" onKeyDown={e => e.key === 'Enter' && handleLogin((e.target as HTMLInputElement).value)} />
                </div>
              </div>
              <button onClick={() => handleLogin((document.querySelector('input[type="email"]') as HTMLInputElement)?.value || '')} className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2">
                Sign In <ArrowRight size={20} />
              </button>
              <div className="relative py-2 text-center">
                <span className="bg-white px-2 text-slate-400 text-xs font-semibold uppercase tracking-widest">or join us</span>
                <div className="absolute inset-0 flex items-center -z-10"><div className="w-full border-t border-slate-100"></div></div>
              </div>
              <button onClick={() => setIsRegistering(true)} className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600 transition-all">Apply to Volunteer</button>
            </div>
          ) : (
            <div className="p-8 space-y-10 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <div className="flex items-center justify-between">
                <div><h2 className="text-2xl font-black text-slate-800 tracking-tight">Application</h2><p className="text-slate-500 font-medium">Become a part of HandsOn.</p></div>
                <button onClick={() => setIsRegistering(false)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors"><X size={24} /></button>
              </div>
              <div className="space-y-8">
                <ImageCapture currentImage={regForm.photoUrl} onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} label="Profile Photo" />

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Personal Information</label>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input placeholder="Full Name" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                    <input placeholder="Email" type="email" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                    <input placeholder="Phone" type="tel" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    <input type="date" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Role Assignment</label>
                  <div className="grid grid-cols-3 gap-3">
                    {[VolunteerType.VTC, VolunteerType.VTP, VolunteerType.BASE].map(type => (
                      <button 
                        key={type}
                        onClick={() => setRegForm({...regForm, volunteerType: type})}
                        className={`p-3 rounded-xl border-2 font-bold text-xs transition-all ${regForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
                      >
                        {type}
                      </button>
                    ))}
                  </div>
                  {regForm.volunteerType === VolunteerType.BASE && (
                    <div className="animate-in slide-in-from-top-2 duration-300">
                      <input 
                        placeholder="Specify Area (e.g. Hospital, School, Park)" 
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                        value={regForm.area}
                        onChange={e => setRegForm({...regForm, area: e.target.value})}
                      />
                    </div>
                  )}
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Recurring Availability</label>
                  <div className="grid grid-cols-7 gap-1.5">
                    {['S','M','T','W','T','F','S'].map((day, i) => (
                      <button key={i} onClick={() => setRegForm(prev => ({ ...prev, selectedDays: prev.selectedDays.includes(i) ? prev.selectedDays.filter(d => d !== i) : [...prev.selectedDays, i] }))} className={`h-10 rounded-xl font-bold text-xs transition-all border-2 ${regForm.selectedDays.includes(i) ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{day}</button>
                    ))}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'MORNING'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}><Sun size={18} /> Morning</button>
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'AFTERNOON'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}><Moon size={18} /> Afternoon</button>
                  </div>
                </div>
              </div>
              <div className="pt-4 sticky bottom-0 bg-white py-4 border-t border-slate-50 flex gap-4">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-bold uppercase tracking-widest text-xs hover:bg-slate-50 rounded-2xl transition-all">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Submit Application</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (appState.currentUser.role !== UserRole.ADMIN && appState.currentUser.status !== UserStatus.APPROVED) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <div className="w-full max-w-md bg-white rounded-[3rem] p-12 shadow-2xl border border-slate-100 space-y-8 animate-in zoom-in duration-500">
          <div className={`w-24 h-24 mx-auto rounded-[2rem] flex items-center justify-center shadow-inner ${appState.currentUser.status === UserStatus.PENDING ? 'bg-amber-50 text-amber-500' : 'bg-red-50 text-red-500'}`}>{appState.currentUser.status === UserStatus.PENDING ? <Clock size={48} /> : <ShieldAlert size={48} />}</div>
          <div className="space-y-3"><h2 className="text-3xl font-black text-slate-900 tracking-tight">{appState.currentUser.status === UserStatus.PENDING ? 'Application Pending' : 'Account Inactive'}</h2><p className="text-slate-500 font-medium leading-relaxed">{appState.currentUser.status === UserStatus.PENDING ? "Your application is currently being reviewed by our team." : "Your account is currently inactive."}</p></div>
          <div className="pt-4 border-t border-slate-50 flex flex-col gap-3"><div className="flex items-center gap-3 justify-center mb-2"><img src={appState.currentUser.photoUrl} className="w-10 h-10 rounded-xl object-cover ring-2 ring-slate-100" /><span className="font-bold text-slate-700">{appState.currentUser.name}</span></div><button onClick={handleLogout} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold uppercase tracking-widest text-xs hover:bg-black transition-all flex items-center justify-center gap-2"><LogOut size={16} /> Sign Out</button></div>
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={appState.currentUser.role} userName={appState.currentUser.name}>
      {activeTab === 'calendar' && (
        <ShiftCalendar 
          shifts={activeShifts} volunteers={appState.volunteers} currentUser={appState.currentUser}
          onAddShift={(data) => handleAddShift({ ...data, volunteerId: appState.currentUser!.id })}
          onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift}
        />
      )}
      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6"><div><h2 className="text-3xl font-black text-slate-800 tracking-tight">Community</h2><p className="text-slate-500 font-medium">Volunteers making an impact</p></div>
            <div className="flex items-center gap-4">{isAdmin && (<button onClick={() => setShowInactiveInCommunity(!showInactiveInCommunity)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${showInactiveInCommunity ? 'bg-slate-800 border-slate-800 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-500'}`}>{showInactiveInCommunity ? 'Showing Inactive' : 'Hide Inactive'}</button>)}<div className="relative group"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input type="text" placeholder="Search..." className="pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm w-48 md:w-64" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm relative group hover:shadow-lg transition-all flex flex-col gap-4">
                <div className="flex items-center gap-4">
                  <img src={volunteer.photoUrl} className={`w-16 h-16 rounded-2xl object-cover ring-4 ${volunteer.status === UserStatus.APPROVED ? 'ring-indigo-50' : 'ring-red-50 grayscale'}`} />
                  <div className="flex-1 min-w-0">
                    <h3 className="font-bold text-slate-800 truncate">{volunteer.name}</h3>
                    <div className="flex flex-wrap items-center gap-1.5 mt-1">
                      <span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded ${volunteer.status === UserStatus.APPROVED ? 'bg-indigo-50 text-indigo-600' : 'bg-red-50 text-red-600'}`}>
                        {getStatusLabel(volunteer.status)}
                      </span>
                      <span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded bg-slate-100 text-slate-500">
                        {volunteer.volunteerType}
                      </span>
                    </div>
                  </div>
                  {isAdmin && (<button onClick={() => setEditingVolunteer(volunteer)} className="p-2 text-slate-400 hover:text-indigo-600 transition-all"><Edit2 size={16} /></button>)}
                </div>
                {volunteer.volunteerType === VolunteerType.BASE && volunteer.area && (
                  <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100">
                    <MapPin size={12} className="text-slate-400" />
                    <span className="text-[10px] font-bold text-slate-500 truncate">{volunteer.area}</span>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-8 duration-500">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm space-y-10">
            <ImageCapture currentImage={appState.currentUser.photoUrl} onImageChange={(url) => handleUpdateVolunteerProfile(appState.currentUser!.id, { photoUrl: url })} label="My Profile Photo" />

            <div className="flex flex-wrap gap-2">
               <div className="inline-flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-2xl border border-indigo-100 shadow-sm">
                  <Tag size={16} />
                  <span className="text-xs font-black uppercase tracking-widest">{appState.currentUser.volunteerType}</span>
               </div>
               {appState.currentUser.area && (
                  <div className="inline-flex items-center gap-2 px-4 py-2 bg-slate-50 text-slate-600 rounded-2xl border border-slate-100 shadow-sm">
                    <MapPin size={16} />
                    <span className="text-xs font-black uppercase tracking-widest">{appState.currentUser.area}</span>
                  </div>
               )}
            </div>

            <div className="grid grid-cols-1 gap-6">
              <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Full Name</label><div className="p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-800">{appState.currentUser.name}</div></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Email Address</label><div className="p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-800 flex items-center gap-3"><Mail size={18} className="text-slate-400" /> {appState.currentUser.email}</div></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Phone Number</label><div className="p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-800 flex items-center gap-3"><Phone size={18} className="text-slate-400" /> {appState.currentUser.phone}</div></div>
            </div>
          </div>
        </div>
      )}
      {activeTab === 'admin' && isAdmin && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} onEditVolunteer={setEditingVolunteer} />
      )}

      {editingVolunteer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-md">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl p-8 md:p-12 shadow-2xl space-y-8 max-h-[90vh] overflow-y-auto relative animate-in zoom-in duration-300 custom-scrollbar">
            <div className="flex items-center justify-between">
              <div><h3 className="text-3xl font-black text-slate-900 tracking-tight">Edit Volunteer</h3><p className="text-slate-500 font-medium italic">Managing {editingVolunteer.name}</p></div>
              <button onClick={() => setEditingVolunteer(null)} className="p-2 text-slate-400 hover:text-slate-600 transition-all"><X size={28} /></button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-8">
                <ImageCapture currentImage={editingVolunteer.photoUrl} onImageChange={(url) => handleUpdateVolunteerProfile(editingVolunteer.id, { photoUrl: url })} label="Volunteer Photo" />
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Account Status</label>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => { updateVolunteerStatus(editingVolunteer.id, UserStatus.APPROVED); setEditingVolunteer(null); }} className={`p-4 rounded-2xl border-2 font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.APPROVED ? 'border-green-600 bg-green-50 text-green-700' : 'border-slate-50 text-slate-400'}`}><CheckCircle2 size={18} /> Active</button>
                    <button onClick={() => { updateVolunteerStatus(editingVolunteer.id, UserStatus.REJECTED); setEditingVolunteer(null); }} className={`p-4 rounded-2xl border-2 font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.REJECTED ? 'border-red-600 bg-red-50 text-red-700' : 'border-slate-50 text-slate-400'}`}><Power size={18} /> Inactive</button>
                  </div>
                </div>
              </div>
              <div className="space-y-6">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Profile & Role</label>
                <div className="space-y-4">
                  <input placeholder="Name" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.name} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { name: e.target.value })} />
                  <input placeholder="Email" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.email} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { email: e.target.value })} />

                  <div className="grid grid-cols-3 gap-2">
                    {[VolunteerType.VTC, VolunteerType.VTP, VolunteerType.BASE].map(type => (
                      <button 
                        key={type}
                        onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { volunteerType: type })}
                        className={`py-3 rounded-xl border-2 font-bold text-[10px] transition-all ${editingVolunteer.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}
                      >
                        {type}
                      </button>
                    ))}
                  </div>

                  {editingVolunteer.volunteerType === VolunteerType.BASE && (
                    <input placeholder="Area" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500 animate-in slide-in-from-top-1" value={editingVolunteer.area || ''} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { area: e.target.value })} />
                  )}

                  <input placeholder="Phone" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.phone} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { phone: e.target.value })} />
                  <input type="date" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.birthday} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { birthday: e.target.value })} />
                </div>
              </div>
            </div>
            <div className="border-t border-slate-100 pt-8 space-y-6">
              <div className="flex items-center justify-between"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Shift Schedule</label>
                <button onClick={() => handleAddShift({ volunteerId: editingVolunteer.id, daysOfWeek: [1], period: 'MORNING' })} className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-indigo-100 transition-all"><Plus size={14} /> Add Shift</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {appState.shifts.filter(s => s.volunteerId === editingVolunteer.id).map(shift => (
                  <div key={shift.id} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">{shift.period === 'MORNING' ? <Sun size={16} className="text-blue-500" /> : <Moon size={16} className="text-amber-500" />}<span className="font-bold text-slate-800 text-sm">{shift.period}</span></div>
                      <button onClick={() => handleRemoveShift(shift.id)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16} /></button>
                    </div>
                    <div className="grid grid-cols-7 gap-1">
                      {['S','M','T','W','T','F','S'].map((name, i) => (
                        <button key={i} onClick={() => handleUpdateShift(shift.id, { daysOfWeek: shift.daysOfWeek.includes(i) ? shift.daysOfWeek.filter(d => d !== i) : [...shift.daysOfWeek, i] })} className={`h-8 rounded-lg font-bold text-[10px] transition-all ${shift.daysOfWeek.includes(i) ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}>{name}</button>
                      ))}
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => handleUpdateShift(shift.id, { period: 'MORNING' })} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${shift.period === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-transparent text-slate-400'}`}>Morning</button>
                      <button onClick={() => handleUpdateShift(shift.id, { period: 'AFTERNOON' })} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${shift.period === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-transparent text-slate-400'}`}>Afternoon</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
            <button onClick={() => setEditingVolunteer(null)} className="w-full py-5 bg-slate-900 text-white rounded-[2rem] font-black uppercase text-xs tracking-[0.2em] shadow-xl hover:bg-black transition-all">Save Changes</button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

export enum UserStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum UserRole {
  VOLUNTEER = 'VOLUNTEER',
  ADMIN = 'ADMIN'
}

export enum VolunteerType {
  VTC = 'VTC',
  VTP = 'VTP',
  BASE = 'BASE'
}

export type ShiftPeriod = 'MORNING' | 'AFTERNOON';

export interface VolunteerProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
  birthday: string;
  photoUrl: string;
  status: UserStatus;
  role: UserRole;
  volunteerType: VolunteerType;
  area?: string;
  joinedAt: string;
}

export interface Shift {
  id: string;
  volunteerId: string;
  daysOfWeek: number[]; // 0 for Sunday, 1 for Monday, etc.
  period: ShiftPeriod;
}

export interface AttendanceRecord {
  id: string;
  volunteerId: string;
  date: string; // YYYY-MM-DD
  timestamp: string; // Full ISO
}

export interface AppState {
  currentUser: VolunteerProfile | null;
  volunteers: VolunteerProfile[];
  shifts: Shift[];
  attendances: AttendanceRecord[];
}

import React, { useState } from 'react';
import { format, parseISO } from 'date-fns';
import { 
  CheckCircle2, 
  Calendar, 
  Clock, 
  User, 
  ClipboardCheck,
  AlertCircle,
  Search,
  History,
  CalendarDays
} from 'lucide-react';
import { AttendanceRecord, VolunteerProfile, UserRole } from '../types';

interface AttendanceViewProps {
  currentUser: VolunteerProfile;
  volunteers: VolunteerProfile[];
  attendances: AttendanceRecord[];
  onCheckIn: (date: string) => void;
}

const AttendanceView: React.FC<AttendanceViewProps> = ({ 
  currentUser, 
  volunteers, 
  attendances, 
  onCheckIn 
}) => {
  const [selectedDate, setSelectedDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [searchTerm, setSearchTerm] = useState('');

  const isAdmin = currentUser.role === UserRole.ADMIN;

  const userAttendances = attendances.filter(a => a.volunteerId === currentUser.id);
  const alreadyCheckedIn = userAttendances.some(a => a.date === selectedDate);

  const displayAttendances = (isAdmin ? attendances : userAttendances)
    .filter(a => {
      if (!isAdmin) return true;
      const vol = volunteers.find(v => v.id === a.volunteerId);
      return vol?.name.toLowerCase().includes(searchTerm.toLowerCase());
    })
    .sort((a, b) => b.timestamp.localeCompare(a.timestamp));

  const getVolunteer = (id: string) => volunteers.find(v => v.id === id);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Attendance</h2>
          <p className="text-slate-500 font-medium">Log your impact and track history</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        {/* Check In Card */}
        <div className="lg:col-span-1">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl shadow-indigo-100/20 space-y-8 sticky top-32">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block">Select Date</label>
              <div className="relative">
                <CalendarDays className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="date" 
                  value={selectedDate}
