                    <input type="date" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Role Assignment</label>
                  <div className="grid grid-cols-3 gap-3">
                    {[VolunteerType.VTC, VolunteerType.VTP, VolunteerType.BASE].map(type => (
                      <button 
                        key={type}
                        onClick={() => setRegForm({...regForm, volunteerType: type})}
                        className={`p-3 rounded-xl border-2 font-bold text-xs transition-all ${regForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-500'}`}
                      >
                        {type}
                      </button>
                    ))}
                  </div>
                  {regForm.volunteerType === VolunteerType.BASE && (
                    <div className="animate-in slide-in-from-top-2 duration-300">
                      <input 
                        placeholder="Specify Area (e.g. Hospital, School, Park)" 
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                        value={regForm.area}
                        onChange={e => setRegForm({...regForm, area: e.target.value})}
                      />
                    </div>
                  )}
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Recurring Availability</label>
                  <div className="grid grid-cols-7 gap-1.5">
                    {['S','M','T','W','T','F','S'].map((day, i) => (
                      <button key={i} onClick={() => setRegForm(prev => ({ ...prev, selectedDays: prev.selectedDays.includes(i) ? prev.selectedDays.filter(d => d !== i) : [...prev.selectedDays, i] }))} className={`h-10 rounded-xl font-bold text-xs transition-all border-2 ${regForm.selectedDays.includes(i) ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{day}</button>
                    ))}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'MORNING'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}><Sun size={18} /> Morning</button>
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'AFTERNOON'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}><Moon size={18} /> Afternoon</button>
                  </div>
                </div>
              </div>
              <div className="pt-4 sticky bottom-0 bg-white py-4 border-t border-slate-50 flex gap-4">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-bold uppercase tracking-widest text-xs hover:bg-slate-50 rounded-2xl transition-all">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Submit Application</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (appState.currentUser.role !== UserRole.ADMIN && appState.currentUser.status !== UserStatus.APPROVED) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <div className="w-full max-w-md bg-white rounded-[3rem] p-12 shadow-2xl border border-slate-100 space-y-8 animate-in zoom-in duration-500">
          <div className={`w-24 h-24 mx-auto rounded-[2rem] flex items-center justify-center shadow-inner ${appState.currentUser.status === UserStatus.PENDING ? 'bg-amber-50 text-amber-500' : 'bg-red-50 text-red-500'}`}>{appState.currentUser.status === UserStatus.PENDING ? <Clock size={48} /> : <ShieldAlert size={48} />}</div>
          <div className="space-y-3"><h2 className="text-3xl font-black text-slate-900 tracking-tight">{appState.currentUser.status === UserStatus.PENDING ? 'Application Pending' : 'Account Inactive'}</h2><p className="text-slate-500 font-medium leading-relaxed">{appState.currentUser.status === UserStatus.PENDING ? "Your application is currently being reviewed by our team." : "Your account is currently inactive."}</p></div>
          <div className="pt-4 border-t border-slate-50 flex flex-col gap-3"><div className="flex items-center gap-3 justify-center mb-2"><img src={appState.currentUser.photoUrl} className="w-10 h-10 rounded-xl object-cover ring-2 ring-slate-100" /><span className="font-bold text-slate-700">{appState.currentUser.name}</span></div><button onClick={handleLogout} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold uppercase tracking-widest text-xs hover:bg-black transition-all flex items-center justify-center gap-2"><LogOut size={16} /> Sign Out</button></div>
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={appState.currentUser.role} userName={appState.currentUser.name}>
