        <ShiftCalendar 
          shifts={activeShifts} volunteers={appState.volunteers} currentUser={appState.currentUser}
          onAddShift={(data) => handleAddShift({ ...data, volunteerId: appState.currentUser!.id })}
          onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift}
        />
      )}

      {activeTab === 'attendance' && (
        <AttendanceView 
          currentUser={appState.currentUser}
          volunteers={appState.volunteers}
          attendances={appState.attendances}
          onCheckIn={handleAttendanceCheckIn}
        />
      )}

      {activeTab === 'volunteers' && (
        <div className="space-y-8">
