                     <button onClick={() => setIsEditingProfile(true)} className="absolute -bottom-2 -right-2 p-2 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all">
                       <Camera size={16} />
                     </button>
                   )}
                 </div>
