                   <h2 className="text-3xl font-black text-slate-900 tracking-tight">{appState.currentUser.name}</h2>
                   <div className="flex items-center gap-2 mt-1">
                      <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded">
                        {appState.currentUser.role}
                      </span>
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest bg-slate-100 px-2 py-0.5 rounded">
                        Joined {new Date(appState.currentUser.joinedAt).toLocaleDateString()}
                      </span>
                   </div>
                 </div>
              </div>
              <button 
                onClick={isEditingProfile ? handleSaveProfile : startEditingProfile}
                className={`flex items-center justify-center gap-2 px-6 py-4 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-lg transition-all active:scale-95 ${isEditingProfile ? 'bg-green-600 text-white hover:bg-green-700 shadow-green-100' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'}`}
              >
                {isEditingProfile ? <><Save size={18} /> Save Changes</> : <><Edit2 size={18} /> Edit Profile</>}
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Contact Information</p>

                <div className="space-y-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 flex items-center gap-2"><User size={14} /> Full Name</label>
                    {isEditingProfile ? (
                      <input 
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                        value={profileEditForm.name || ''}
                        onChange={e => setProfileEditForm(prev => ({ ...prev, name: e.target.value }))}
                      />
                    ) : (
                      <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-800">{appState.currentUser.name}</div>
                    )}
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 flex items-center gap-2"><Mail size={14} /> Email Address</label>
                    {isEditingProfile ? (
                      <input 
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                        value={profileEditForm.email || ''}
                        onChange={e => setProfileEditForm(prev => ({ ...prev, email: e.target.value }))}
                      />
                    ) : (
                      <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-800">{appState.currentUser.email}</div>
                    )}
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 flex items-center gap-2"><Phone size={14} /> Phone Number</label>
                    {isEditingProfile ? (
                      <input 
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                        value={profileEditForm.phone || ''}
                        onChange={e => setProfileEditForm(prev => ({ ...prev, phone: e.target.value }))}
                      />
                    ) : (
                      <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-800">{appState.currentUser.phone}</div>
                    )}
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 flex items-center gap-2"><Cake size={14} /> Birthday</label>
                    {isEditingProfile ? (
                      <input 
                        type="date"
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                        value={profileEditForm.birthday || ''}
                        onChange={e => setProfileEditForm(prev => ({ ...prev, birthday: e.target.value }))}
                      />
                    ) : (
                      <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-800">{appState.currentUser.birthday}</div>
                    )}
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Assignment & Role</p>

                <div className="space-y-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 flex items-center gap-2"><Tag size={14} /> Volunteer Role</label>
                    {isEditingProfile ? (
                      <div className="grid grid-cols-3 gap-2">
                        {ROLE_ORDER.map(type => (
                          <button 
                            key={type}
                            onClick={() => setProfileEditForm(prev => ({ ...prev, volunteerType: type }))}
                            className={`py-3 rounded-xl border-2 font-bold text-[10px] transition-all ${profileEditForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-200 text-slate-400'}`}
                          >
                            {type}
                          </button>
                        ))}
                      </div>
                    ) : (
                      <div className="flex items-center gap-3 p-4 bg-indigo-50/50 border border-indigo-100 rounded-xl">
                        <Tag size={18} className="text-indigo-600" />
                        <span className="font-black text-indigo-700 uppercase text-xs tracking-widest">{appState.currentUser.volunteerType}</span>
                      </div>
                    )}
                  </div>

                  {(isEditingProfile ? profileEditForm.volunteerType === VolunteerType.BASE : appState.currentUser.volunteerType === VolunteerType.BASE) && (
                    <div className="space-y-1.5 animate-in slide-in-from-top-2">
                      <label className="text-xs font-bold text-slate-500 flex items-center gap-2"><MapPin size={14} /> Area Assignment</label>
                      {isEditingProfile ? (
                        <input 
                          placeholder="e.g. Central Hospital"
                          className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                          value={profileEditForm.area || ''}
                          onChange={e => setProfileEditForm(prev => ({ ...prev, area: e.target.value }))}
                        />
                      ) : (
                        <div className="flex items-center gap-3 p-4 bg-slate-50 border border-slate-100 rounded-xl">
                          <MapPin size={18} className="text-slate-400" />
                          <span className="font-bold text-slate-800 text-sm">{appState.currentUser.area || 'Not Assigned'}</span>
                        </div>
                      )}
                    </div>
                  )}

                  {!isEditingProfile && (
                    <div className="space-y-1.5 pt-4">
                      <div className="flex items-center gap-3 p-4 bg-green-50 border border-green-100 rounded-xl">
                        <CheckCircle2 size={18} className="text-green-600" />
                        <span className="font-black text-green-700 uppercase text-[10px] tracking-widest">Account Active & Verified</span>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {isEditingProfile && (
              <div className="flex gap-4 pt-4 animate-in slide-in-from-bottom-2">
                 <button 
                  onClick={() => setIsEditingProfile(false)}
                  className="flex-1 py-4 bg-slate-50 text-slate-400 rounded-2xl font-bold uppercase tracking-widest text-xs hover:bg-slate-100 transition-all"
                >
                  Discard Changes
                </button>
                <button 
                  onClick={handleSaveProfile}
                  className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-bold uppercase tracking-widest text-xs hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all"
                >
                  Confirm & Save
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'admin' && isAdmin && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} onEditVolunteer={setEditingVolunteer} />
      )}

      {editingVolunteer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-md">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl p-8 md:p-12 shadow-2xl space-y-8 max-h-[90vh] overflow-y-auto relative animate-in zoom-in duration-300 custom-scrollbar">
            <div className="flex items-center justify-between">
              <div><h3 className="text-3xl font-black text-slate-900 tracking-tight">Edit Volunteer</h3><p className="text-slate-500 font-medium italic">Managing {editingVolunteer.name}</p></div>
              <button onClick={() => setEditingVolunteer(null)} className="p-2 text-slate-400 hover:text-slate-600 transition-all"><X size={28} /></button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="space-y-8">
                <ImageCapture currentImage={editingVolunteer.photoUrl} onImageChange={(url) => handleUpdateVolunteerProfile(editingVolunteer.id, { photoUrl: url })} label="Volunteer Photo" />
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Account Status</label>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => { updateVolunteerStatus(editingVolunteer.id, UserStatus.APPROVED); setEditingVolunteer(null); }} className={`p-4 rounded-2xl border-2 font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.APPROVED ? 'border-green-600 bg-green-50 text-green-700' : 'border-slate-50 text-slate-400'}`}><CheckCircle2 size={18} /> Active</button>
                    <button onClick={() => { updateVolunteerStatus(editingVolunteer.id, UserStatus.REJECTED); setEditingVolunteer(null); }} className={`p-4 rounded-2xl border-2 font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.REJECTED ? 'border-red-600 bg-red-50 text-red-700' : 'border-slate-50 text-slate-400'}`}><Power size={18} /> Inactive</button>
                  </div>
                </div>
              </div>
              <div className="space-y-6">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Profile & Role</label>
                <div className="space-y-4">
                  <input placeholder="Name" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.name} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { name: e.target.value })} />
                  <input placeholder="Email" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.email} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { email: e.target.value })} />

                  <div className="grid grid-cols-3 gap-2">
                    {ROLE_ORDER.map(type => (
                      <button 
                        key={type}
                        onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { volunteerType: type })}
                        className={`py-3 rounded-xl border-2 font-bold text-[10px] transition-all ${editingVolunteer.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}
                      >
                        {type}
                      </button>
                    ))}
                  </div>

                  {editingVolunteer.volunteerType === VolunteerType.BASE && (
                    <input placeholder="Area" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500 animate-in slide-in-from-top-1" value={editingVolunteer.area || ''} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { area: e.target.value })} />
                  )}

                  <input placeholder="Phone" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.phone} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { phone: e.target.value })} />
                  <input type="date" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.birthday} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { birthday: e.target.value })} />
                </div>
              </div>
            </div>
            <div className="border-t border-slate-100 pt-8 space-y-6">
              <div className="flex items-center justify-between"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Shift Schedule</label>
                <button onClick={() => handleAddShift({ volunteerId: editingVolunteer.id, daysOfWeek: [1], period: 'MORNING' })} className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-indigo-100 transition-all"><Plus size={14} /> Add Shift</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {appState.shifts.filter(s => s.volunteerId === editingVolunteer.id).map(shift => (
                  <div key={shift.id} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">{shift.period === 'MORNING' ? <Sun size={16} className="text-blue-500" /> : <Moon size={16} className="text-amber-500" />}<span className="font-bold text-slate-800 text-sm">{shift.period}</span></div>
                      <button onClick={() => handleRemoveShift(shift.id)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16} /></button>
                    </div>
                    <div className="grid grid-cols-7 gap-1">
                      {['S','M','T','W','T','F','S'].map((name, i) => (
                        <button key={i} onClick={() => handleUpdateShift(shift.id, { daysOfWeek: shift.daysOfWeek.includes(i) ? shift.daysOfWeek.filter(d => d !== i) : [...shift.daysOfWeek, i] })} className={`h-8 rounded-lg font-bold text-[10px] transition-all ${shift.daysOfWeek.includes(i) ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}>{name}</button>
                      ))}
                    </div>
                    <div className="flex gap-2">
