                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {appState.shifts.filter(s => s.volunteerId === editingVolunteer.id).map(shift => (
                      <div key={shift.id} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">{shift.period === 'MORNING' ? <Sun size={16} className="text-blue-500" /> : <Moon size={16} className="text-amber-500" />}<span className="font-bold text-slate-800 text-sm">{shift.period}</span></div>
                          <button onClick={() => handleRemoveShift(shift.id)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16} /></button>
                        </div>
                        <div className="grid grid-cols-7 gap-1">
                          {['S','M','T','W','T','F','S'].map((name, i) => (
                            <button key={i} onClick={() => handleUpdateShift(shift.id, { daysOfWeek: shift.daysOfWeek.includes(i) ? shift.daysOfWeek.filter(d => d !== i) : [...shift.daysOfWeek, i] })} className={`h-8 rounded-lg font-bold text-[10px] transition-all ${shift.daysOfWeek.includes(i) ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}>{name}</button>
                          ))}
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => handleUpdateShift(shift.id, { period: 'MORNING' })} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${shift.period === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-transparent text-slate-400'}`}>Morning</button>
                          <button onClick={() => handleUpdateShift(shift.id, { period: 'AFTERNOON' })} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${shift.period === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-transparent text-slate-400'}`}>Afternoon</button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Attendance Statistics for Admin */}
              <div className="space-y-6">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Attendance Record History</label>
                <AttendanceHistory 
                  volunteerId={editingVolunteer.id} 
                  attendances={appState.attendances} 
                />
              </div>
            </div>

            <button onClick={() => setEditingVolunteer(null)} className="w-full py-5 bg-slate-900 text-white rounded-[2rem] font-black uppercase text-xs tracking-[0.2em] shadow-xl hover:bg-black transition-all">Close & Save Changes</button>
          </div>
        </div>
      )}
    </Layout>
  );
};

