                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-bold uppercase tracking-widest text-xs hover:bg-slate-50 rounded-2xl transition-all">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Submit Application</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={appState.currentUser.role} userName={appState.currentUser.name}>
      {activeTab === 'calendar' && (
        <ShiftCalendar shifts={activeShifts} volunteers={appState.volunteers} currentUser={appState.currentUser} onAddShift={(data) => handleAddShift({ ...data, volunteerId: appState.currentUser!.id })} onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift} />
      )}
      {activeTab === 'attendance' && (
        <AttendanceView currentUser={appState.currentUser} volunteers={appState.volunteers} attendances={appState.attendances} onCheckIn={handleAttendanceCheckIn} />
      )}
      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6"><div><h2 className="text-3xl font-black text-slate-800 tracking-tight">Community</h2><p className="text-slate-500 font-medium">Meet the people making an impact</p></div>
            <div className="flex items-center gap-4">{(isAdmin) && (<button onClick={() => setShowInactiveInCommunity(!showInactiveInCommunity)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${showInactiveInCommunity ? 'bg-slate-800 border-slate-800 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-500'}`}>{showInactiveInCommunity ? 'Showing Inactive' : 'Hide Inactive'}</button>)}<div className="relative group"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input type="text" placeholder="Search..." className="pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm w-48 md:w-64" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm relative group hover:shadow-lg transition-all flex flex-col gap-4">
                <div className="flex items-center gap-4">
                  <img src={volunteer.photoUrl} className={`w-16 h-16 rounded-2xl object-cover ring-4 ${volunteer.status === UserStatus.APPROVED ? 'ring-indigo-50' : 'ring-red-50 grayscale'}`} />
                  <div className="flex-1 min-w-0">
                    <h3 className="font-bold text-slate-800 truncate flex items-center gap-2">{volunteer.name}{volunteer.role === UserRole.ADMIN && <ShieldAlert size={14} className="text-indigo-600" title="Admin" />}</h3>
                    <div className="flex flex-wrap items-center gap-1.5 mt-1"><span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded ${volunteer.status === UserStatus.APPROVED ? 'bg-indigo-50 text-indigo-600' : 'bg-red-50 text-red-600'}`}>{getStatusLabel(volunteer.status)}</span><span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded bg-slate-100 text-slate-500">{volunteer.volunteerType}</span></div>
                  </div>
                  {isAdmin && (<button onClick={() => setEditingVolunteer(volunteer)} className="p-2 text-slate-400 hover:text-indigo-600 transition-all"><Edit2 size={16} /></button>)}
                </div>
                {volunteer.volunteerType === VolunteerType.BASE && volunteer.area && (
                  <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100"><MapPin size={12} className="text-slate-400" /><span className="text-[10px] font-bold text-slate-500 truncate">{volunteer.area}</span></div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-8 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-7 space-y-8">
              <div className="bg-white p-8 md:p-12 rounded-[3rem] border border-slate-100 shadow-xl shadow-indigo-100/20 space-y-10">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-50 pb-8">
                  <div className="flex items-center gap-6">
                    <div className="relative">
                      <img src={isEditingProfile ? (profileEditForm.photoUrl || appState.currentUser.photoUrl) : appState.currentUser.photoUrl} className="w-24 h-24 rounded-[2rem] object-cover ring-4 ring-indigo-50 shadow-lg" />
                      {isEditingProfile && (<button onClick={() => setIsEditingProfile(true)} className="absolute -bottom-2 -right-2 p-2 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Camera size={16} /></button>)}
                    </div>
                    <div><h2 className="text-3xl font-black text-slate-900 tracking-tight">{appState.currentUser.name}</h2><div className="flex items-center gap-2 mt-1"><span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded">{appState.currentUser.role}</span><span className="text-[10px] font-black text-slate-500 uppercase tracking-widest bg-slate-100 px-2 py-0.5 rounded">Joined {new Date(appState.currentUser.joinedAt).toLocaleDateString()}</span></div></div>
                  </div>
                  <button onClick={isEditingProfile ? handleSaveProfile : startEditingProfile} className={`flex items-center justify-center gap-2 px-6 py-4 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-lg transition-all active:scale-95 ${isEditingProfile ? 'bg-green-600 text-white hover:bg-green-700 shadow-green-100' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'}`}>{isEditingProfile ? <><Save size={18} /> Save Changes</> : <><Edit2 size={18} /> Edit Profile</>}</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6"><p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Contact</p>
                    <div className="space-y-4">
                      <div className="space-y-1.5"><label className="text-xs font-bold text-slate-500 flex items-center gap-2"><User size={14} /> Full Name</label>{isEditingProfile ? (<input className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={profileEditForm.name || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, name: e.target.value }))} />) : (<div className="p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-800">{appState.currentUser.name}</div>)}</div>
                      <div className="space-y-1.5"><label className="text-xs font-bold text-slate-500 flex items-center gap-2"><Mail size={14} /> Email</label>{isEditingProfile ? (<input className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-800 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={profileEditForm.email || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, email: e.target.value }))} />) : (<div className="p-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-800">{appState.currentUser.email}</div>)}</div>
                    </div>
                  </div>
                  <div className="space-y-6"><p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Assignment</p>
                    <div className="space-y-4">
                      <div className="space-y-1.5"><label className="text-xs font-bold text-slate-500 flex items-center gap-2"><Tag size={14} /> Role</label>
                        {isEditingProfile ? (<div className="grid grid-cols-3 gap-2">{ROLE_ORDER.map(type => (<button key={type} onClick={() => setProfileEditForm(prev => ({ ...prev, volunteerType: type }))} className={`py-3 rounded-xl border-2 font-bold text-[10px] transition-all ${profileEditForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-200 text-slate-400'}`}>{type}</button>))}</div>) : (<div className="flex items-center gap-3 p-4 bg-indigo-50/50 border border-indigo-100 rounded-xl"><Tag size={18} className="text-indigo-600" /><span className="font-black text-indigo-700 uppercase text-xs tracking-widest">{appState.currentUser.volunteerType}</span></div>)}
                      </div>
                    </div>
                  </div>
                </div>
                {isEditingProfile && (<div className="flex gap-4 pt-4 animate-in slide-in-from-bottom-2"><button onClick={() => setIsEditingProfile(false)} className="flex-1 py-4 bg-slate-50 text-slate-400 rounded-2xl font-bold uppercase tracking-widest text-xs hover:bg-slate-100 transition-all">Discard</button><button onClick={handleSaveProfile} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-bold uppercase tracking-widest text-xs hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all">Save</button></div>)}
              </div>
            </div>
            <div className="lg:col-span-5 space-y-6"><div className="flex items-center gap-3 px-4"><History className="text-indigo-600" size={24} /><h3 className="text-2xl font-black text-slate-800">Attendance Log</h3></div><AttendanceHistory volunteerId={appState.currentUser.id} attendances={appState.attendances} /></div>
          </div>
        </div>
      )}
      {activeTab === 'admin' && isAdmin && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} onEditVolunteer={setEditingVolunteer} />
      )}
      {editingVolunteer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-md">
          <div className="bg-white rounded-[3rem] w-full max-w-5xl p-8 md:p-12 shadow-2xl space-y-8 max-h-[90vh] overflow-y-auto relative animate-in zoom-in duration-300 custom-scrollbar">
            <div className="flex items-center justify-between"><div><h3 className="text-3xl font-black text-slate-900 tracking-tight">Edit Volunteer</h3><p className="text-slate-500 font-medium italic">Managing {editingVolunteer.name}</p></div><button onClick={() => setEditingVolunteer(null)} className="p-2 text-slate-400 hover:text-slate-600 transition-all"><X size={28} /></button></div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              <div className="space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-8">
                    <ImageCapture currentImage={editingVolunteer.photoUrl} onImageChange={(url) => handleUpdateVolunteerProfile(editingVolunteer.id, { photoUrl: url })} label="Volunteer Photo" />
                    <div className="space-y-4"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Account Status</label><div className="grid grid-cols-2 gap-3"><button onClick={() => { updateVolunteerStatus(editingVolunteer.id, UserStatus.APPROVED); setEditingVolunteer(null); }} className={`p-4 rounded-2xl border-2 font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.APPROVED ? 'border-green-600 bg-green-50 text-green-700' : 'border-slate-50 text-slate-400'}`}><CheckCircle2 size={18} /> Active</button><button onClick={() => { updateVolunteerStatus(editingVolunteer.id, UserStatus.REJECTED); setEditingVolunteer(null); }} className={`p-4 rounded-2xl border-2 font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.REJECTED ? 'border-red-600 bg-red-50 text-red-700' : 'border-slate-50 text-slate-400'}`}><Power size={18} /> Inactive</button></div></div>
                  </div>
                  <div className="space-y-6"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Profile & Role</label>
                    <div className="space-y-4"><input placeholder="Name" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.name} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { name: e.target.value })} /><input placeholder="Email" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.email} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { email: e.target.value })} />
                      <div className="grid grid-cols-3 gap-2">{ROLE_ORDER.map(type => (<button key={type} onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { volunteerType: type })} className={`py-3 rounded-xl border-2 font-bold text-[10px] transition-all ${editingVolunteer.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{type}</button>))}</div>
                      {editingVolunteer.volunteerType === VolunteerType.BASE && (<input placeholder="Area" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.area || ''} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { area: e.target.value })} />)}
                      <input placeholder="Phone" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.phone} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { phone: e.target.value })} /><input type="date" className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" value={editingVolunteer.birthday} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { birthday: e.target.value })} />
                    </div>
                  </div>
                </div>
                <div className="border-t border-slate-100 pt-8 space-y-6"><div className="flex items-center justify-between"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Shift Schedule</label><button onClick={() => handleAddShift({ volunteerId: editingVolunteer.id, daysOfWeek: [1], period: 'MORNING' })} className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-indigo-100 transition-all"><Plus size={14} /> Add Shift</button></div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {appState.shifts.filter(s => s.volunteerId === editingVolunteer.id).map(shift => (
                      <div key={shift.id} className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                        <div className="flex items-center justify-between"><div className="flex items-center gap-2">{shift.period === 'MORNING' ? <Sun size={16} className="text-blue-500" /> : <Moon size={16} className="text-amber-500" />}<span className="font-bold text-slate-800 text-sm">{shift.period}</span></div><button onClick={() => handleRemoveShift(shift.id)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 size={16} /></button></div>
                        <div className="grid grid-cols-7 gap-1">{['S','M','T','W','T','F','S'].map((name, i) => (<button key={i} onClick={() => handleUpdateShift(shift.id, { daysOfWeek: shift.daysOfWeek.includes(i) ? shift.daysOfWeek.filter(d => d !== i) : [...shift.daysOfWeek, i] })} className={`h-8 rounded-lg font-bold text-[10px] transition-all ${shift.daysOfWeek.includes(i) ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}>{name}</button>))}</div>
                        <div className="flex gap-2"><button onClick={() => handleUpdateShift(shift.id, { period: 'MORNING' })} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${shift.period === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-transparent text-slate-400'}`}>Morning</button><button onClick={() => handleUpdateShift(shift.id, { period: 'AFTERNOON' })} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${shift.period === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-transparent text-slate-400'}`}>Afternoon</button></div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
              <div className="space-y-6"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Attendance Record History</label><AttendanceHistory volunteerId={editingVolunteer.id} attendances={appState.attendances} /></div>
            </div>
            <button onClick={() => setEditingVolunteer(null)} className="w-full py-5 bg-slate-900 text-white rounded-[2rem] font-black uppercase text-xs tracking-[0.2em] shadow-xl hover:bg-black transition-all">Close & Save Changes</button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  format, 
  parseISO, 
  isSameMonth, 
  isSameYear, 
  addMonths, 
  subMonths 
} from 'date-fns';
import { 
  CheckCircle2, 
  Calendar, 
  Clock, 
  ClipboardCheck,
  AlertCircle,
  Search,
  History,
  CalendarDays,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';
import { AttendanceRecord, VolunteerProfile, UserRole } from '../types';

interface AttendanceViewProps {
  currentUser: VolunteerProfile;
  volunteers: VolunteerProfile[];
  attendances: AttendanceRecord[];
  onCheckIn: (date: string) => void;
}

const AttendanceView: React.FC<AttendanceViewProps> = ({ 
  currentUser, 
  volunteers, 
  attendances, 
  onCheckIn 
}) => {
  const [selectedDate, setSelectedDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [searchTerm, setSearchTerm] = useState('');
  const [viewingMonth, setViewingMonth] = useState(new Date());

  const isAdmin = currentUser.role === UserRole.ADMIN;

  const userAttendances = attendances.filter(a => a.volunteerId === currentUser.id);
  const alreadyCheckedIn = userAttendances.some(a => a.date === selectedDate);

  const displayAttendances = (isAdmin ? attendances : userAttendances)
    .filter(a => {
      // Search filter for Admin
      if (isAdmin && searchTerm) {
        const vol = volunteers.find(v => v.id === a.volunteerId);
        if (!vol?.name.toLowerCase().includes(searchTerm.toLowerCase())) return false;
      }

      // Month/Year filter
      const recordDate = parseISO(a.date);
      return isSameMonth(recordDate, viewingMonth) && isSameYear(recordDate, viewingMonth);
    })
    .sort((a, b) => b.timestamp.localeCompare(a.timestamp)); // Date descending

  const getVolunteer = (id: string) => volunteers.find(v => v.id === id);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Attendance</h2>
          <p className="text-slate-500 font-medium">Log your impact and track history</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        {/* Check In Card */}
        <div className="lg:col-span-1">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-xl shadow-indigo-100/20 space-y-8 sticky top-32">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block">Select Date</label>
              <div className="relative">
                <CalendarDays className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="date" 
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                />
              </div>
            </div>

            <div className="pt-4">
              {alreadyCheckedIn ? (
                <div className="flex flex-col items-center gap-6 p-10 bg-green-50 rounded-[2.5rem] border-2 border-green-100 animate-in zoom-in duration-500">
                  <div className="w-20 h-20 bg-green-600 rounded-[2rem] flex items-center justify-center text-white shadow-lg shadow-green-200">
                    <CheckCircle2 size={40} />
                  </div>
                  <div className="text-center">
                    <h3 className="text-xl font-black text-green-900">Successfully Logged</h3>
                    <p className="text-green-600 font-bold mt-1">Checked in for {format(parseISO(selectedDate), 'MMM do, yyyy')}</p>
                  </div>
                </div>
              ) : (
                <button 
                  onClick={() => onCheckIn(selectedDate)}
                  className="group w-full aspect-square bg-indigo-600 hover:bg-indigo-700 text-white rounded-[3rem] shadow-2xl shadow-indigo-200 flex flex-col items-center justify-center gap-4 transition-all active:scale-95"
                >
                  <div className="p-6 bg-white/10 rounded-[2rem] group-hover:scale-110 transition-transform">
                    <ClipboardCheck size={48} />
                  </div>
                  <div className="text-center">
                    <span className="text-2xl font-black block">Check In</span>
                    <span className="text-sm font-bold text-indigo-200">Register Attendance</span>
                  </div>
                </button>
              )}
            </div>

            {alreadyCheckedIn && (
              <p className="text-center text-xs font-bold text-slate-400 flex items-center justify-center gap-2">
                <AlertCircle size={14} /> Only one log per day allowed
              </p>
            )}
          </div>
        </div>

        {/* Attendance History */}
        <div className="lg:col-span-2 space-y-6">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl">
                <History size={24} />
              </div>
              <h3 className="text-2xl font-black text-slate-800">
                {isAdmin ? 'Global Registry' : 'My History'}
              </h3>
            </div>

            {isAdmin && (
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input 
                  type="text" 
                  placeholder="Search name..." 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm w-full sm:w-48 font-medium"
                />
              </div>
            )}
          </div>

          {/* Month Navigator */}
          <div className="flex items-center justify-between bg-white px-6 py-4 rounded-[2rem] border border-slate-100 shadow-sm">
            <button 
              onClick={() => setViewingMonth(subMonths(viewingMonth, 1))}
              className="p-2 hover:bg-slate-50 rounded-xl transition-all text-slate-400 hover:text-indigo-600"
            >
              <ChevronLeft size={24} />
            </button>
            <div className="text-center">
              <span className="text-lg font-black text-slate-800 tracking-tight">
                {format(viewingMonth, 'MMMM yyyy')}
              </span>
            </div>
            <button 
              onClick={() => setViewingMonth(addMonths(viewingMonth, 1))}
              className="p-2 hover:bg-slate-50 rounded-xl transition-all text-slate-400 hover:text-indigo-600"
            >
              <ChevronRight size={24} />
            </button>
          </div>

          <div className="space-y-4">
            {displayAttendances.length === 0 ? (
              <div className="bg-white p-20 rounded-[3rem] border-2 border-dashed border-slate-200 text-center">
                <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 mx-auto mb-4">
