                    <p className="text-xs font-bold text-yellow-700 mt-1 opacity-80 leading-relaxed">Login to automatically register your attendance for today.</p>
                  </div>
                </div>
              )}
              {loginError && (
                <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-start gap-3 animate-in fade-in slide-in-from-top-2">
