const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
  disabled?: boolean;
}> = ({ currentImage, onImageChange, label = "Profile Photo", disabled = false }) => {
  const libraryInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const resizeImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_SIZE = 400;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const resized = await resizeImage(reader.result as string);
        onImageChange(resized);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-4">
      {label && <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">{label}</label>}
      <div className="flex flex-col sm:flex-row items-center gap-6">
        <div className="relative w-32 h-32 shrink-0">
          {isProcessing ? (
            <div className="w-full h-full rounded-[2.5rem] bg-slate-100 flex items-center justify-center border-2 border-indigo-100">
               <Loader2 className="animate-spin text-indigo-500" size={24} />
            </div>
          ) : (
            <img 
              src={currentImage || 'https://via.placeholder.com/150?text=No+Photo'} 
              className="w-full h-full rounded-[2.5rem] object-cover ring-4 ring-indigo-50 shadow-lg"
              alt="Preview"
            />
          )}
        </div>
        {!disabled && (
          <div className="flex flex-col gap-2 w-full sm:w-auto">
            <button 
              type="button" 
              onClick={() => cameraInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-6 py-4 bg-indigo-600 text-white rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg active:scale-95"
            >
              <Camera size={18} /> Take Photo
            </button>
            <button 
              type="button" 
              onClick={() => libraryInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-6 py-4 bg-white border-2 border-slate-100 text-slate-600 rounded-2xl font-bold text-xs uppercase tracking-widest hover:border-indigo-200 hover:text-indigo-600 transition-all active:scale-95"
            >
              <ImageIcon size={18} /> Upload Image
            </button>
          </div>
        )}
      </div>
      <input type="file" ref={libraryInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
      <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
    </div>
  );
};

const AttendanceHistory: React.FC<{
  volunteerId: string;
  attendances: AttendanceRecord[];
}> = ({ volunteerId, attendances }) => {
  const [viewingMonth, setViewingMonth] = useState(new Date());

  const userAttendances = useMemo(() => 
    attendances.filter(a => a.volunteerId === volunteerId),
    [attendances, volunteerId]
  );

  const monthRecords = useMemo(() => 
    userAttendances.filter(a => {
      const d = parseISO(a.date);
      return isSameMonth(d, viewingMonth) && isSameYear(d, viewingMonth);
    }).sort((a, b) => b.date.localeCompare(a.date)),
    [userAttendances, viewingMonth]
  );

  const totalSum = userAttendances.length;
  const monthSum = monthRecords.length;

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="bg-indigo-600 p-8 rounded-[2rem] text-white shadow-xl shadow-indigo-100 flex flex-col justify-between min-h-[160px]">
          <TrendingUp size={24} className="opacity-50" />
          <div className="mt-4">
            <p className="text-5xl font-black">{totalSum}</p>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80 mt-1">Lifetime Total</p>
          </div>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col justify-between min-h-[160px]">
          <History size={24} className="text-indigo-600" />
          <div className="mt-4">
            <p className="text-5xl font-black text-slate-900">{monthSum}</p>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mt-1">This Month</p>
          </div>
        </div>
      </div>

      <div className="bg-white p-8 rounded-[2rem] border border-slate-100 space-y-6">
        <div className="flex items-center justify-between px-2">
          <button onClick={() => setViewingMonth(subMonths(viewingMonth, 1))} className="p-3 hover:bg-slate-50 rounded-xl transition-all text-slate-400 hover:text-indigo-600">
            <ChevronLeft size={24} />
          </button>
          <p className="font-black text-slate-800 text-lg uppercase tracking-widest">{format(viewingMonth, 'MMMM yyyy')}</p>
          <button onClick={() => setViewingMonth(addMonths(viewingMonth, 1))} className="p-3 hover:bg-slate-50 rounded-xl transition-all text-slate-400 hover:text-indigo-600">
            <ChevronRight size={24} />
          </button>
        </div>

        <div className="space-y-3 max-h-80 overflow-y-auto custom-scrollbar pr-2">
          {monthRecords.length === 0 ? (
            <div className="py-12 text-center text-slate-300 font-bold text-sm italic">No entries for this month</div>
          ) : (
            monthRecords.map(record => (
              <div key={record.id} className="flex items-center justify-between p-5 bg-slate-50 rounded-2xl border border-slate-100 group">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center text-indigo-600 shadow-sm">
                    <ClipboardCheck size={20} />
                  </div>
                  <div>
                    <p className="font-black text-slate-800 text-base">{format(parseISO(record.date), 'EEEE, do')}</p>
                    <p className="text-xs font-black uppercase tracking-widest text-slate-400">{format(parseISO(record.timestamp), 'hh:mm a')}</p>
                  </div>
                </div>
                <div className="px-4 py-1.5 bg-green-100 text-green-700 rounded-full text-[10px] font-black uppercase tracking-widest">Logged</div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return {
          currentUser: parsed.currentUser || null,
          volunteers: parsed.volunteers || INITIAL_VOLUNTEERS,
          shifts: parsed.shifts || INITIAL_SHIFTS,
          attendances: parsed.attendances || []
        };
      } catch (e) { console.error("Failed to load state", e); }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS, attendances: [] };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isAutoCheckInPending, setIsAutoCheckInPending] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', preferredPeriod: 'MORNING' as ShiftPeriod, selectedDays: [] as number[], volunteerType: VolunteerType.VTP, area: ''
  });

  const [profileEditForm, setProfileEditForm] = useState<Partial<VolunteerProfile>>({});

  useEffect(() => {
    const checkHash = () => {
      if (window.location.hash === '#check-in') {
        setIsAutoCheckInPending(true);
      }
    };
    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  useEffect(() => {
    if (appState.currentUser && isAutoCheckInPending && appState.currentUser.status === UserStatus.APPROVED) {
      const today = format(new Date(), 'yyyy-MM-dd');
      handleAttendanceCheckIn(today);
      setIsAutoCheckInPending(false);
      window.history.replaceState(null, '', window.location.pathname + window.location.search);
      setActiveTab('attendance');
    }
  }, [appState.currentUser, isAutoCheckInPending]);

  useEffect(() => {
    try { localStorage.setItem('handson_state', JSON.stringify(appState)); } catch (e) { console.warn("Storage error:", e); }
  }, [appState]);

  const handleLogout = () => {
    setAppState(prev => ({ ...prev, currentUser: null }));
    setLoginForm({ email: '', phone: '' });
    setLoginError(null);
    setActiveTab('calendar');
    setIsRegistering(false);
    setIsEditingProfile(false);
    setIsAutoCheckInPending(false);
  };

  const handleLogin = () => {
    const { email, phone } = loginForm;
    setLoginError(null);

    if (!email || !phone) {
      setLoginError("Please enter both your email and phone number.");
      return;
    }

    const user = appState.volunteers.find(v => 
      v.email.toLowerCase() === email.trim().toLowerCase() && 
      v.phone.trim() === phone.trim()
    );

    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (!isAutoCheckInPending) {
        setActiveTab(user.role === UserRole.ADMIN ? 'admin' : 'calendar');
      }
    } else {
      setLoginError("Invalid credentials. Please verify your email and phone number.");
    }
  };

  const handleRegister = () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return alert("Please fill in all details.");
    if (regForm.volunteerType === VolunteerType.BASE && !regForm.area) return alert("Please specify your Area for BASE role.");
    if (regForm.selectedDays.length === 0) return alert("Select at least one day for your schedule.");

    const volunteerId = Math.random().toString(36).substring(2, 11);
    const newVol: VolunteerProfile = { 
      id: volunteerId, 
      name: regForm.name, 
      email: regForm.email, 
      phone: regForm.phone, 
      birthday: regForm.birthday, 
      photoUrl: regForm.photoUrl, 
      status: UserStatus.PENDING, 
      role: UserRole.VOLUNTEER, 
      volunteerType: regForm.volunteerType,
      area: regForm.volunteerType === VolunteerType.BASE ? regForm.area : undefined,
      joinedAt: new Date().toISOString() 
    };

    const newShift: Shift = { id: Math.random().toString(36).substring(2, 11), volunteerId: volunteerId, daysOfWeek: regForm.selectedDays, period: regForm.preferredPeriod };
    setAppState(prev => ({ ...prev, volunteers: [...prev.volunteers, newVol], shifts: [...prev.shifts, newShift], currentUser: newVol }));
    setActiveTab('profile');
    setIsRegistering(false);
  };

  const handleAttendanceCheckIn = (date: string) => {
    const userId = appState.currentUser?.id;
    if (!userId) return;
    if (appState.attendances.some(a => a.volunteerId === userId && a.date === date)) return;

    const newRecord: AttendanceRecord = {
      id: Math.random().toString(36).substring(2, 11),
      volunteerId: userId,
      date,
      timestamp: new Date().toISOString()
    };

    setAppState(prev => ({
      ...prev,
      attendances: [...prev.attendances, newRecord]
    }));
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, status } : prev.currentUser
    }));
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => {
      const newVols = prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v);
      return {
        ...prev,
        volunteers: newVols,
        currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, ...updates } : prev.currentUser,
      };
    });
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const handleSaveProfile = () => {
    if (!appState.currentUser) return;
    handleUpdateVolunteerProfile(appState.currentUser.id, profileEditForm);
    setIsEditingProfile(false);
  };

  const startEditingProfile = () => {
    if (!appState.currentUser) return;
    setProfileEditForm({ ...appState.currentUser });
    setIsEditingProfile(true);
  };

  const handleUpdateShift = (id: string, updated: Partial<Shift>) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updated } : s) }));
  };

  const handleAddShift = (shift: Omit<Shift, 'id'>) => {
    const newShift = { ...shift, id: Math.random().toString(36).substring(2, 11) };
    setAppState(prev => ({ ...prev, shifts: [...prev.shifts, newShift] }));
  };

  const handleRemoveShift = (id: string) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.filter(s => s.id !== id) }));
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(appState.volunteers.filter(v => v.status === UserStatus.APPROVED).map(v => v.id));
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  const filteredVolunteers = useMemo(() => {
    return appState.volunteers.filter(v => {
      const searchMatch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!searchMatch) return false;
      return showInactiveInCommunity || v.status === UserStatus.APPROVED;
    });
  }, [appState.volunteers, searchTerm, showInactiveInCommunity]);

  const getStatusLabel = (status: UserStatus) => {
    switch (status) {
      case UserStatus.APPROVED: return 'Active';
      case UserStatus.REJECTED: return 'Inactive';
      case UserStatus.PENDING: return 'Pending';
      default: return status;
    }
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 font-inter">
        <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-md'} bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-100 transition-all duration-500`}>
          <div className="bg-indigo-600 p-8 text-center relative overflow-hidden">
            {isAutoCheckInPending && (
              <div className="absolute top-0 right-0 bg-yellow-400 text-yellow-950 px-6 py-1 rotate-45 translate-x-4 translate-y-2 text-[8px] font-black uppercase tracking-widest flex items-center gap-1 shadow-lg">
                <QrCode size={10} /> QR Check-In Active
              </div>
            )}
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-white mx-auto mb-4 backdrop-blur-md"><Heart size={32} fill="currentColor" /></div>
            <h1 className="text-3xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 mt-2">Volunteer Portal</p>
          </div>
          {!isRegistering ? (
            <div className="p-8 space-y-6">
              {isAutoCheckInPending && (
                <div className="bg-yellow-50 border border-yellow-100 p-5 rounded-2xl flex items-start gap-4 animate-in fade-in slide-in-from-top-2">
                  <div className="p-2 bg-yellow-400 text-yellow-900 rounded-xl shadow-sm">
                    <QrCode size={20} />
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-yellow-900 leading-tight">Fast Attendance Log</h3>
                    <p className="text-xs font-bold text-yellow-700 mt-1 opacity-80 leading-relaxed">Login to automatically register your attendance for today.</p>
                  </div>
                </div>
              )}
              {loginError && (
                <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-start gap-3 animate-in fade-in slide-in-from-top-2">
                  <AlertCircle className="text-red-500 shrink-0 mt-0.5" size={18} />
                  <p className="text-sm font-semibold text-red-600 leading-tight">{loginError}</p>
                </div>
              )}
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Volunteer Email</label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                      type="email" 
                      placeholder="Enter your email" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" 
                      value={loginForm.email}
                      onChange={e => {
                        setLoginForm(prev => ({ ...prev, email: e.target.value }));
                        if (loginError) setLoginError(null);
                      }}
                      onKeyDown={e => e.key === 'Enter' && handleLogin()} 
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Phone Number</label>
                  <div className="relative">
                    <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                      type="tel" 
                      placeholder="Enter your phone" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" 
                      value={loginForm.phone}
                      onChange={e => {
                        setLoginForm(prev => ({ ...prev, phone: e.target.value }));
                        if (loginError) setLoginError(null);
                      }}
                      onKeyDown={e => e.key === 'Enter' && handleLogin()} 
                    />
                  </div>
                </div>
              </div>
              <button onClick={handleLogin} className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2">
                Sign In <ArrowRight size={20} />
              </button>
              <div className="relative py-2 text-center">
                <span className="bg-white px-2 text-slate-400 text-xs font-semibold uppercase tracking-widest">or join us</span>
                <div className="absolute inset-0 flex items-center -z-10"><div className="w-full border-t border-slate-100"></div></div>
              </div>
              <button onClick={() => setIsRegistering(true)} className="w-full bg-white border-2 border-slate-200 text-slate-600 py-3 rounded-xl font-bold hover:border-indigo-200 hover:text-indigo-600 transition-all">Apply to Volunteer</button>
            </div>
          ) : (
            <div className="p-8 space-y-10 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <div className="flex items-center justify-between">
                <div><h2 className="text-2xl font-black text-slate-800 tracking-tight">Application</h2><p className="text-slate-500 font-medium">Become a part of HandsOn.</p></div>
                <button onClick={() => setIsRegistering(false)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors"><X size={24} /></button>
              </div>
              <div className="space-y-8">
                <ImageCapture currentImage={regForm.photoUrl} onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} label="Profile Photo" />
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Personal Information</label>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input placeholder="Full Name" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                    <input placeholder="Email" type="email" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                    <input placeholder="Phone" type="tel" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    <input type="date" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                  </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Role Assignment</label>
                  <div className="grid grid-cols-3 gap-3">
                    {ROLE_ORDER.map(type => (
                      <button key={type} onClick={() => setRegForm({...regForm, volunteerType: type})} className={`p-3 rounded-xl border-2 font-bold text-xs transition-all ${regForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-500'}`}>{type}</button>
                    ))}
                  </div>
                  {regForm.volunteerType === VolunteerType.BASE && (
                    <input placeholder="Specify Area" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" value={regForm.area} onChange={e => setRegForm({...regForm, area: e.target.value})} />
                  )}
                </div>
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Recurring Availability</label>
                  <div className="grid grid-cols-7 gap-1.5">
                    {['S','M','T','W','T','F','S'].map((day, i) => (
                      <button key={i} onClick={() => setRegForm(prev => ({ ...prev, selectedDays: prev.selectedDays.includes(i) ? prev.selectedDays.filter(d => d !== i) : [...prev.selectedDays, i] }))} className={`h-10 rounded-xl font-bold text-xs transition-all border-2 ${regForm.selectedDays.includes(i) ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{day}</button>
                    ))}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'MORNING'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'MORNING' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}><Sun size={18} /> Morning</button>
                    <button onClick={() => setRegForm({...regForm, preferredPeriod: 'AFTERNOON'})} className={`p-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-2 ${regForm.preferredPeriod === 'AFTERNOON' ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 text-slate-400'}`}><Moon size={18} /> Afternoon</button>
                  </div>
                </div>
              </div>
              <div className="pt-4 sticky bottom-0 bg-white py-4 border-t border-slate-50 flex gap-4">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-bold uppercase tracking-widest text-xs hover:bg-slate-50 rounded-2xl transition-all">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all">Submit Application</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={appState.currentUser.role} userName={appState.currentUser.name}>
      {activeTab === 'calendar' && (
        <ShiftCalendar shifts={activeShifts} volunteers={appState.volunteers} currentUser={appState.currentUser} onAddShift={(data) => handleAddShift({ ...data, volunteerId: appState.currentUser!.id })} onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift} />
      )}
      {activeTab === 'attendance' && (
        <AttendanceView currentUser={appState.currentUser} volunteers={appState.volunteers} attendances={appState.attendances} onCheckIn={handleAttendanceCheckIn} />
      )}
      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6"><div><h2 className="text-3xl font-black text-slate-800 tracking-tight">Community</h2><p className="text-slate-500 font-medium">Meet the people making an impact</p></div>
            <div className="flex items-center gap-4">{(isAdmin) && (<button onClick={() => setShowInactiveInCommunity(!showInactiveInCommunity)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${showInactiveInCommunity ? 'bg-slate-800 border-slate-800 text-white shadow-lg' : 'bg-white border-slate-200 text-slate-500'}`}>{showInactiveInCommunity ? 'Showing Inactive' : 'Hide Inactive'}</button>)}<div className="relative group"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /><input type="text" placeholder="Search..." className="pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm w-48 md:w-64" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div></div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm relative group hover:shadow-lg transition-all flex flex-col gap-4">
                <div className="flex items-center gap-4">
                  <img src={volunteer.photoUrl} className={`w-16 h-16 rounded-2xl object-cover ring-4 ${volunteer.status === UserStatus.APPROVED ? 'ring-indigo-50' : 'ring-red-50 grayscale'}`} />
                  <div className="flex-1 min-w-0">
                    <h3 className="font-bold text-slate-800 truncate flex items-center gap-2">{volunteer.name}{volunteer.role === UserRole.ADMIN && <ShieldAlert size={14} className="text-indigo-600" title="Admin" />}</h3>
                    <div className="flex flex-wrap items-center gap-1.5 mt-1"><span className={`text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded ${volunteer.status === UserStatus.APPROVED ? 'bg-indigo-50 text-indigo-600' : 'bg-red-50 text-red-600'}`}>{getStatusLabel(volunteer.status)}</span><span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded bg-slate-100 text-slate-500">{volunteer.volunteerType}</span></div>
                  </div>
                  {isAdmin && (<button onClick={() => setEditingVolunteer(volunteer)} className="p-2 text-slate-400 hover:text-indigo-600 transition-all"><Edit2 size={16} /></button>)}
                </div>
                {volunteer.volunteerType === VolunteerType.BASE && volunteer.area && (
                  <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100"><MapPin size={12} className="text-slate-400" /><span className="text-[10px] font-bold text-slate-500 truncate">{volunteer.area}</span></div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-8 duration-500">
          <div className="bg-white p-8 md:p-16 rounded-[3rem] border border-slate-100 shadow-xl shadow-indigo-100/20 space-y-12">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 border-b border-slate-50 pb-12">
              <div className="flex items-center gap-8">
                <div className="relative">
                  {isEditingProfile ? (
                    <ImageCapture 
                      currentImage={profileEditForm.photoUrl || appState.currentUser.photoUrl} 
                      onImageChange={(url) => setProfileEditForm(prev => ({ ...prev, photoUrl: url }))}
                      label=""
                    />
                  ) : (
                    <img src={appState.currentUser.photoUrl} className="w-32 h-32 rounded-[2.5rem] object-cover ring-8 ring-indigo-50 shadow-xl" />
                  )}
                </div>
                <div>
                  <h2 className="text-4xl font-black text-slate-900 tracking-tight">{appState.currentUser.name}</h2>
                  <div className="flex flex-wrap items-center gap-3 mt-3">
                    <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-3 py-1 rounded-full">{appState.currentUser.role}</span>
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest bg-slate-100 px-3 py-1 rounded-full border border-slate-200">Member since {new Date(appState.currentUser.joinedAt).getFullYear()}</span>
                  </div>
                </div>
              </div>
              <button onClick={isEditingProfile ? handleSaveProfile : startEditingProfile} className={`flex items-center justify-center gap-3 px-8 py-5 rounded-[2rem] font-black uppercase tracking-widest text-xs shadow-xl transition-all active:scale-95 ${isEditingProfile ? 'bg-green-600 text-white hover:bg-green-700 shadow-green-100' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'}`}>{isEditingProfile ? <><Save size={20} /> Save Changes</> : <><Edit2 size={20} /> Edit My Profile</>}</button>
            </div>

            {/* Single Column Profile Information */}
            <div className="max-w-2xl space-y-12">
              <section className="space-y-8">
                <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Personal Details</p>
                <div className="space-y-8">
                  <div className="space-y-2">
                    <label className="text-sm font-black text-slate-500 flex items-center gap-2"><User size={16} /> Full Legal Name</label>
                    {isEditingProfile ? (
                      <input className="w-full p-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-100 transition-all" value={profileEditForm.name || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, name: e.target.value }))} />
                    ) : (
                      <div className="p-6 bg-slate-50/50 border border-slate-100 rounded-[1.5rem] font-bold text-xl text-slate-900">{appState.currentUser.name}</div>
                    )}
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-black text-slate-500 flex items-center gap-2"><Mail size={16} /> Email Address</label>
                    {isEditingProfile ? (
                      <input className="w-full p-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-100 transition-all" value={profileEditForm.email || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, email: e.target.value }))} />
                    ) : (
                      <div className="p-6 bg-slate-50/50 border border-slate-100 rounded-[1.5rem] font-bold text-xl text-slate-900 break-all">{appState.currentUser.email}</div>
                    )}
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-black text-slate-500 flex items-center gap-2"><Phone size={16} /> Mobile Number</label>
                    {isEditingProfile ? (
                      <input className="w-full p-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-100 transition-all" value={profileEditForm.phone || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, phone: e.target.value }))} />
                    ) : (
                      <div className="p-6 bg-slate-50/50 border border-slate-100 rounded-[1.5rem] font-bold text-xl text-slate-900">{appState.currentUser.phone}</div>
                    )}
                  </div>

                  <div className="space-y-2">
                    <label className="text-sm font-black text-slate-500 flex items-center gap-2"><Cake size={16} /> Date of Birth</label>
                    {isEditingProfile ? (
                      <input type="date" className="w-full p-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-100 transition-all" value={profileEditForm.birthday || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, birthday: e.target.value }))} />
                    ) : (
                      <div className="p-6 bg-slate-50/50 border border-slate-100 rounded-[1.5rem] font-bold text-xl text-slate-900">
                        {appState.currentUser.birthday ? format(parseISO(appState.currentUser.birthday), 'MMMM do, yyyy') : 'Not provided'}
                      </div>
                    )}
                  </div>
                </div>
              </section>

              <section className="space-y-8">
                <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Volunteer Assignment</p>
                <div className="space-y-8">
                  <div className="space-y-2">
                    <label className="text-sm font-black text-slate-500 flex items-center gap-2"><Tag size={16} /> Assigned Role Type</label>
                    {isEditingProfile ? (
                      <div className="flex flex-wrap gap-3">
                        {ROLE_ORDER.map(type => (
                          <button key={type} onClick={() => setProfileEditForm(prev => ({ ...prev, volunteerType: type }))} className={`px-6 py-4 rounded-2xl border-2 font-black text-sm transition-all ${profileEditForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-100'}`}>{type}</button>
                        ))}
                      </div>
                    ) : (
                      <div className="flex items-center gap-4 p-6 bg-indigo-50 border border-indigo-100 rounded-[1.5rem]">
                        <div className="p-3 bg-white rounded-xl shadow-sm"><Tag size={24} className="text-indigo-600" /></div>
                        <span className="font-black text-indigo-700 uppercase text-lg tracking-[0.1em]">{appState.currentUser.volunteerType}</span>
                      </div>
                    )}
                  </div>

                  {appState.currentUser.volunteerType === VolunteerType.BASE && (
                    <div className="space-y-2">
                      <label className="text-sm font-black text-slate-500 flex items-center gap-2"><MapPin size={16} /> Designated Service Area</label>
                      {isEditingProfile ? (
                        <input className="w-full p-5 bg-slate-50 border border-slate-200 rounded-[1.5rem] font-bold text-lg text-slate-800 outline-none focus:ring-4 focus:ring-indigo-100 transition-all" value={profileEditForm.area || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, area: e.target.value }))} />
                      ) : (
                        <div className="p-6 bg-slate-50/50 border border-slate-100 rounded-[1.5rem] font-bold text-xl text-slate-900">{appState.currentUser.area || 'All Areas'}</div>
                      )}
                    </div>
                  )}
                </div>
              </section>

              {isEditingProfile && (
                <div className="flex gap-4 pt-8 animate-in slide-in-from-bottom-2">
                  <button onClick={() => setIsEditingProfile(false)} className="flex-1 py-6 bg-slate-50 text-slate-400 rounded-[2rem] font-black uppercase tracking-widest text-xs hover:bg-slate-100 transition-all">Discard Changes</button>
                  <button onClick={handleSaveProfile} className="flex-1 py-6 bg-indigo-600 text-white rounded-[2rem] font-black uppercase tracking-widest text-xs hover:bg-indigo-700 shadow-2xl shadow-indigo-100 transition-all">Save Profile Changes</button>
                </div>
              )}
            </div>
          </div>

          <div className="space-y-8">
            <div className="flex items-center gap-4 px-6">
              <History className="text-indigo-600" size={32} />
              <h3 className="text-3xl font-black text-slate-900 tracking-tight">Personal Attendance Log</h3>
            </div>
            <AttendanceHistory volunteerId={appState.currentUser.id} attendances={appState.attendances} />
          </div>
        </div>
      )}
      {activeTab === 'admin' && isAdmin && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} onEditVolunteer={setEditingVolunteer} />
      )}
      {editingVolunteer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-8 bg-slate-900/60 backdrop-blur-xl overflow-y-auto">
          <div className="bg-white rounded-[4rem] w-full max-w-4xl my-8 p-10 md:p-16 shadow-2xl space-y-16 relative animate-in zoom-in duration-300">
            {/* Header */}
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-5xl font-black text-slate-900 tracking-tighter">Edit Profile</h3>
                <p className="text-slate-500 font-bold text-lg mt-2 italic">Updating records for {editingVolunteer.name}</p>
              </div>
              <button onClick={() => setEditingVolunteer(null)} className="p-4 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-2xl transition-all">
                <X size={32} />
              </button>
            </div>

            {/* Profile Content - True Single Column Flow */}
            <div className="max-w-3xl space-y-16">

              {/* Profile Image Group */}
              <div className="space-y-8">
                 <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Identification</p>
                 <ImageCapture currentImage={editingVolunteer.photoUrl} onImageChange={(url) => handleUpdateVolunteerProfile(editingVolunteer.id, { photoUrl: url })} label="Volunteer Identity Photo" />
              </div>

              {/* Essential Fields - Vertically Stacked, Full Width */}
              <div className="space-y-10">
                <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Personal Information</p>
