const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
  disabled?: boolean;
}> = ({ currentImage, onImageChange, label = "Profile Photo", disabled = false }) => {
  const libraryInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const resizeImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_SIZE = 400;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const resized = await resizeImage(reader.result as string);
        onImageChange(resized);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-2">
      {label && <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">{label}</label>}
      <div className="flex items-center gap-4">
        <div className="relative w-20 h-20 shrink-0">
          {isProcessing ? (
            <div className="w-full h-full rounded-2xl bg-slate-100 flex items-center justify-center border border-indigo-100">
               <Loader2 className="animate-spin text-indigo-500" size={20} />
            </div>
          ) : (
            <img 
              src={currentImage || 'https://via.placeholder.com/150?text=No+Photo'} 
              className="w-full h-full rounded-2xl object-cover ring-2 ring-indigo-50 shadow-sm"
              alt="Preview"
            />
          )}
        </div>
        {!disabled && (
          <div className="flex flex-col gap-1.5">
            <button 
              type="button" 
              onClick={() => cameraInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-bold text-[10px] uppercase tracking-wider hover:bg-indigo-700 transition-all shadow-sm active:scale-95"
            >
              <Camera size={14} /> Take
            </button>
            <button 
              type="button" 
              onClick={() => libraryInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold text-[10px] uppercase tracking-wider hover:border-indigo-200 hover:text-indigo-600 transition-all active:scale-95"
            >
              <ImageIcon size={14} /> Upload
            </button>
          </div>
        )}
      </div>
      <input type="file" ref={libraryInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
      <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
    </div>
  );
};

const AttendanceHistory: React.FC<{
  volunteerId: string;
  attendances: AttendanceRecord[];
}> = ({ volunteerId, attendances }) => {
  const [viewingMonth, setViewingMonth] = useState(new Date());

  const userAttendances = useMemo(() => 
    attendances.filter(a => a.volunteerId === volunteerId),
    [attendances, volunteerId]
  );

  const monthRecords = useMemo(() => 
    userAttendances.filter(a => {
      const d = parseISO(a.date);
      return isSameMonth(d, viewingMonth) && isSameYear(d, viewingMonth);
    }).sort((a, b) => b.date.localeCompare(a.date)),
    [userAttendances, viewingMonth]
  );

  const totalSum = userAttendances.length;
  const monthSum = monthRecords.length;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-indigo-600 p-4 rounded-2xl text-white shadow-md flex items-center justify-between">
          <div>
            <p className="text-2xl font-black">{totalSum}</p>
            <p className="text-[9px] font-black uppercase tracking-wider opacity-80">Lifetime</p>
          </div>
          <TrendingUp size={20} className="opacity-40" />
        </div>
        <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between">
          <div>
            <p className="text-2xl font-black text-slate-800">{monthSum}</p>
            <p className="text-[9px] font-black uppercase tracking-wider text-slate-400">Month</p>
          </div>
          <History size={20} className="text-indigo-600 opacity-40" />
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 space-y-4">
        <div className="flex items-center justify-between px-1">
          <button onClick={() => setViewingMonth(subMonths(viewingMonth, 1))} className="p-1.5 hover:bg-slate-50 rounded-lg transition-all text-slate-400">
            <ChevronLeft size={20} />
          </button>
          <p className="font-black text-slate-800 text-xs uppercase tracking-widest">{format(viewingMonth, 'MMM yyyy')}</p>
          <button onClick={() => setViewingMonth(addMonths(viewingMonth, 1))} className="p-1.5 hover:bg-slate-50 rounded-lg transition-all text-slate-400">
            <ChevronRight size={20} />
          </button>
        </div>

        <div className="space-y-2 max-h-48 overflow-y-auto custom-scrollbar pr-1">
          {monthRecords.length === 0 ? (
            <div className="py-6 text-center text-slate-300 font-bold text-[10px] italic">No logs</div>
          ) : (
            monthRecords.map(record => (
              <div key={record.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-indigo-600 shadow-sm">
                    <ClipboardCheck size={14} />
                  </div>
                  <div>
                    <p className="font-black text-slate-800 text-xs">{format(parseISO(record.date), 'EEE, do')}</p>
                    <p className="text-[9px] font-black uppercase tracking-tight text-slate-400">{format(parseISO(record.timestamp), 'hh:mm a')}</p>
                  </div>
                </div>
                <div className="px-2 py-0.5 bg-green-100 text-green-700 rounded-full text-[8px] font-black uppercase tracking-tight">Logged</div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

