      } catch (e) { console.error("Failed to load state", e); }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS, attendances: [] };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isAutoCheckInPending, setIsAutoCheckInPending] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', preferredPeriod: 'MORNING' as ShiftPeriod, selectedDays: [] as number[], volunteerType: VolunteerType.VTP, area: ''
  });

  const [profileEditForm, setProfileEditForm] = useState<Partial<VolunteerProfile>>({});

  useEffect(() => {
    const checkHash = () => {
      if (window.location.hash === '#check-in') {
        setIsAutoCheckInPending(true);
      }
    };
    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  useEffect(() => {
    if (appState.currentUser && isAutoCheckInPending && appState.currentUser.status === UserStatus.APPROVED) {
      const today = format(new Date(), 'yyyy-MM-dd');
      handleAttendanceCheckIn(today);
      setIsAutoCheckInPending(false);
      window.history.replaceState(null, '', window.location.pathname + window.location.search);
      setActiveTab('attendance');
    }
  }, [appState.currentUser, isAutoCheckInPending]);

  useEffect(() => {
    try { localStorage.setItem('handson_state', JSON.stringify(appState)); } catch (e) { console.warn("Storage error:", e); }
  }, [appState]);

  const handleLogout = () => {
    setAppState(prev => ({ ...prev, currentUser: null }));
    setLoginForm({ email: '', phone: '' });
    setLoginError(null);
    setActiveTab('calendar');
    setIsRegistering(false);
    setIsEditingProfile(false);
    setIsAutoCheckInPending(false);
  };

  const handleLogin = () => {
    const { email, phone } = loginForm;
    setLoginError(null);

    if (!email || !phone) {
      setLoginError("Missing details.");
      return;
    }

    const user = appState.volunteers.find(v => 
      v.email.toLowerCase() === email.trim().toLowerCase() && 
      v.phone.trim() === phone.trim()
    );

    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (!isAutoCheckInPending) {
        setActiveTab(user.role === UserRole.ADMIN ? 'admin' : 'calendar');
      }
    } else {
      setLoginError("Invalid credentials.");
    }
  };

  const handleRegister = () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return alert("Fill all details.");
    if (regForm.volunteerType === VolunteerType.BASE && !regForm.area) return alert("Specify Area.");
    if (regForm.selectedDays.length === 0) return alert("Select at least one day.");

    const volunteerId = Math.random().toString(36).substring(2, 11);
    const newVol: VolunteerProfile = { 
      id: volunteerId, 
      name: regForm.name, 
      email: regForm.email, 
      phone: regForm.phone, 
      birthday: regForm.birthday, 
      photoUrl: regForm.photoUrl, 
      status: UserStatus.PENDING, 
      role: UserRole.VOLUNTEER, 
      volunteerType: regForm.volunteerType,
      area: regForm.volunteerType === VolunteerType.BASE ? regForm.area : undefined,
      joinedAt: new Date().toISOString() 
    };

    const newShift: Shift = { id: Math.random().toString(36).substring(2, 11), volunteerId: volunteerId, daysOfWeek: regForm.selectedDays, period: regForm.preferredPeriod };
    setAppState(prev => ({ ...prev, volunteers: [...prev.volunteers, newVol], shifts: [...prev.shifts, newShift], currentUser: newVol }));
    setActiveTab('profile');
    setIsRegistering(false);
  };

  const handleAttendanceCheckIn = (date: string) => {
    const userId = appState.currentUser?.id;
    if (!userId) return;
    if (appState.attendances.some(a => a.volunteerId === userId && a.date === date)) return;

    const newRecord: AttendanceRecord = {
      id: Math.random().toString(36).substring(2, 11),
      volunteerId: userId,
      date,
      timestamp: new Date().toISOString()
    };

    setAppState(prev => ({
      ...prev,
      attendances: [...prev.attendances, newRecord]
    }));
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, status } : prev.currentUser
    }));
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => {
      const newVols = prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v);
      return {
        ...prev,
        volunteers: newVols,
        currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, ...updates } : prev.currentUser,
      };
    });
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const handleSaveProfile = () => {
    if (!appState.currentUser) return;
    handleUpdateVolunteerProfile(appState.currentUser.id, profileEditForm);
    setIsEditingProfile(false);
  };

  const startEditingProfile = () => {
    if (!appState.currentUser) return;
    setProfileEditForm({ ...appState.currentUser });
    setIsEditingProfile(true);
  };

  const handleUpdateShift = (id: string, updated: Partial<Shift>) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updated } : s) }));
  };

  const handleAddShift = (shift: Omit<Shift, 'id'>) => {
    const newShift = { ...shift, id: Math.random().toString(36).substring(2, 11) };
    setAppState(prev => ({ ...prev, shifts: [...prev.shifts, newShift] }));
  };

  const handleRemoveShift = (id: string) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.filter(s => s.id !== id) }));
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(appState.volunteers.filter(v => v.status === UserStatus.APPROVED).map(v => v.id));
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  const filteredVolunteers = useMemo(() => {
    return appState.volunteers.filter(v => {
      const searchMatch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!searchMatch) return false;
      return showInactiveInCommunity || v.status === UserStatus.APPROVED;
    });
  }, [appState.volunteers, searchTerm, showInactiveInCommunity]);

  const getStatusLabel = (status: UserStatus) => {
    switch (status) {
      case UserStatus.APPROVED: return 'Active';
      case UserStatus.REJECTED: return 'Inactive';
      case UserStatus.PENDING: return 'Pending';
      default: return status;
    }
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4 font-inter">
        <div className={`w-full ${isRegistering ? 'max-w-xl' : 'max-w-sm'} bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-100`}>
          <div className="bg-indigo-600 p-6 text-center relative overflow-hidden">
            <h1 className="text-xl font-bold text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 text-[10px] uppercase font-bold">Volunteer Portal</p>
          </div>
          {!isRegistering ? (
            <div className="p-6 space-y-4">
              {loginError && (
                <div className="bg-red-50 p-3 rounded-xl flex items-center gap-2">
                  <AlertCircle className="text-red-500" size={14} />
                  <p className="text-xs font-bold text-red-600">{loginError}</p>
                </div>
              )}
              <div className="space-y-3">
                <input placeholder="Email" type="email" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
                <input placeholder="Phone" type="tel" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" value={loginForm.phone} onChange={e => setLoginForm({...loginForm, phone: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
              </div>
              <button onClick={handleLogin} className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold text-sm shadow-md hover:bg-indigo-700 active:scale-95 transition-all">Sign In</button>
              <button onClick={() => setIsRegistering(true)} className="w-full py-2 text-indigo-600 font-bold text-xs hover:bg-indigo-50 rounded-lg transition-colors">Apply to Volunteer</button>
            </div>
          ) : (
            <div className="p-6 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <h2 className="text-lg font-black text-slate-800 tracking-tight">Application</h2>
              <div className="space-y-4">
                <ImageCapture currentImage={regForm.photoUrl} onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} label="Identity Photo" />
                <div className="grid grid-cols-2 gap-3">
                  <input placeholder="Full Name" className="p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs outline-none" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  <input placeholder="Email" type="email" className="p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs outline-none" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                  <input placeholder="Phone" type="tel" className="p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs outline-none" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                  <input type="date" className="p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs outline-none" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block">Volunteer Role</label>
                  <div className="grid grid-cols-3 gap-2">
                    {ROLE_ORDER.map(type => (
                      <button key={type} onClick={() => setRegForm({...regForm, volunteerType: type})} className={`p-2 rounded-lg border font-bold text-[9px] transition-all ${regForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{type}</button>
                    ))}
                  </div>
                  {regForm.volunteerType === VolunteerType.BASE && (
                    <input placeholder="Area" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs outline-none" value={regForm.area} onChange={e => setRegForm({...regForm, area: e.target.value})} />
                  )}
                </div>
              </div>
              <div className="flex gap-2 pt-2 sticky bottom-0 bg-white py-2 border-t">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-3 text-slate-400 font-bold text-xs">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold text-xs">Submit</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={appState.currentUser.role} userName={appState.currentUser.name}>
      {activeTab === 'calendar' && (
        <ShiftCalendar shifts={activeShifts} volunteers={appState.volunteers} currentUser={appState.currentUser} onAddShift={(data) => handleAddShift({ ...data, volunteerId: appState.currentUser!.id })} onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift} />
      )}
      {activeTab === 'attendance' && (
        <AttendanceView currentUser={appState.currentUser} volunteers={appState.volunteers} attendances={appState.attendances} onCheckIn={handleAttendanceCheckIn} />
      )}
      {activeTab === 'volunteers' && (
        <div className="space-y-6">
          <div className="flex items-center justify-between gap-4">
            <div><h2 className="text-xl font-black text-slate-800 tracking-tight">Community</h2></div>
            <div className="flex items-center gap-2">
              <div className="relative"><Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" size={14} /><input type="text" placeholder="Search..." className="pl-8 pr-3 py-1.5 bg-white border border-slate-200 rounded-xl outline-none text-xs w-32 md:w-48" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div>
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm relative hover:shadow-md transition-all flex items-center gap-4">
                <img src={volunteer.photoUrl} className="w-12 h-12 rounded-xl object-cover ring-2 ring-indigo-50" />
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-slate-800 text-sm truncate flex items-center gap-1.5">
                    {volunteer.name}
                    {volunteer.role === UserRole.ADMIN && <ShieldCheck size={12} className="text-indigo-600" />}
                  </h3>
                  <div className="flex items-center gap-1 mt-0.5"><span className="text-[8px] font-black uppercase tracking-tight px-1.5 py-0.5 rounded bg-indigo-50 text-indigo-600">{volunteer.volunteerType}</span><span className={`text-[8px] font-black uppercase tracking-tight px-1.5 py-0.5 rounded ${volunteer.status === UserStatus.APPROVED ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>{getStatusLabel(volunteer.status)}</span></div>
                </div>
                {isAdmin && (<button onClick={() => setEditingVolunteer(volunteer)} className="p-2 text-slate-400 hover:text-indigo-600 transition-all"><Edit2 size={14} /></button>)}
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white p-6 md:p-8 rounded-[2rem] border border-slate-100 shadow-lg space-y-6">
            <div className="flex items-center justify-between border-b pb-6">
              <div className="flex items-center gap-6">
                <div className="relative">
                  {isEditingProfile ? (
                    <ImageCapture currentImage={profileEditForm.photoUrl || appState.currentUser.photoUrl} onImageChange={(url) => setProfileEditForm(prev => ({ ...prev, photoUrl: url }))} label="" />
                  ) : (
                    <img src={appState.currentUser.photoUrl} className="w-20 h-20 rounded-2xl object-cover ring-4 ring-indigo-50" />
                  )}
                </div>
                <div>
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">{appState.currentUser.name}</h2>
                  <div className="flex items-center gap-2 mt-1"><span className="text-[9px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded-full">{appState.currentUser.role}</span></div>
                </div>
              </div>
              <button onClick={isEditingProfile ? handleSaveProfile : startEditingProfile} className={`flex items-center gap-2 px-6 py-3 rounded-xl font-bold uppercase tracking-widest text-[10px] shadow-sm transition-all ${isEditingProfile ? 'bg-green-600 text-white' : 'bg-indigo-600 text-white'}`}>{isEditingProfile ? <><Save size={14} /> Save</> : <><Edit2 size={14} /> Edit</>}</button>
            </div>

            <div className="space-y-6">
              <section className="space-y-4">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">General Information</p>
                <div className="space-y-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-slate-500">Name</label>
                    {isEditingProfile ? (
                      <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm" value={profileEditForm.name || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, name: e.target.value }))} />
                    ) : (
                      <p className="font-bold text-slate-900">{appState.currentUser.name}</p>
                    )}
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-slate-500">Email</label>
                    {isEditingProfile ? (
                      <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm" value={profileEditForm.email || ''} onChange={e => setProfileEditForm(prev => ({ ...prev, email: e.target.value }))} />
                    ) : (
                      <p className="font-bold text-slate-900 break-all">{appState.currentUser.email}</p>
                    )}
                  </div>
                </div>
              </section>
            </div>
          </div>
          <AttendanceHistory volunteerId={appState.currentUser.id} attendances={appState.attendances} />
        </div>
      )}
      {activeTab === 'admin' && isAdmin && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} onEditVolunteer={setEditingVolunteer} />
      )}
      {editingVolunteer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white rounded-3xl w-full max-w-lg my-4 p-6 md:p-8 shadow-2xl space-y-8 relative animate-in zoom-in duration-200">
            <div className="flex items-center justify-between">
              <div><h3 className="text-xl font-black text-slate-900 tracking-tight">Edit Volunteer</h3><p className="text-slate-500 text-[10px] uppercase font-bold">{editingVolunteer.name}</p></div>
              <button onClick={() => setEditingVolunteer(null)} className="p-2 text-slate-400 hover:text-slate-900 transition-all"><X size={24} /></button>
            </div>

            <div className="space-y-8 max-h-[70vh] overflow-y-auto custom-scrollbar pr-1">
              <section className="space-y-4">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Identification</p>
                 <ImageCapture currentImage={editingVolunteer.photoUrl} onImageChange={(url) => handleUpdateVolunteerProfile(editingVolunteer.id, { photoUrl: url })} label="Identity Photo" />
              </section>

              <section className="space-y-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Personal Details</p>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500">Full Name</label>
                    <input className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium" value={editingVolunteer.name} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { name: e.target.value })} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500">Email</label>
                    <input className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium" value={editingVolunteer.email} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { email: e.target.value })} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500">Phone</label>
                    <input className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium" value={editingVolunteer.phone} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { phone: e.target.value })} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500">Birthday</label>
                    <input type="date" className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium" value={editingVolunteer.birthday} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { birthday: e.target.value })} />
                  </div>
                </div>
              </section>

              <section className="space-y-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">System Role</p>
                <div className="grid grid-cols-2 gap-3">
                  <button onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { role: UserRole.VOLUNTEER })} className={`p-3 rounded-xl border-2 font-black text-[10px] uppercase tracking-widest transition-all ${editingVolunteer.role === UserRole.VOLUNTEER ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-100 text-slate-400'}`}>Standard</button>
                  <button onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { role: UserRole.ADMIN })} className={`p-3 rounded-xl border-2 font-black text-[10px] uppercase tracking-widest transition-all ${editingVolunteer.role === UserRole.ADMIN ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>Admin</button>
                </div>
              </section>

              <section className="space-y-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Classification</p>
                <div className="flex flex-wrap gap-2">
                  {ROLE_ORDER.map(type => (
                    <button key={type} onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { volunteerType: type })} className={`px-4 py-2 rounded-xl border-2 font-black text-[9px] uppercase tracking-widest transition-all ${editingVolunteer.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{type}</button>
                  ))}
                </div>
                {editingVolunteer.volunteerType === VolunteerType.BASE && (
                  <input placeholder="Area" className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium" value={editingVolunteer.area || ''} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { area: e.target.value })} />
                )}
              </section>

              <section className="space-y-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</p>
                <div className="grid grid-cols-2 gap-3">
                  <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.APPROVED)} className={`p-3 rounded-xl border-2 font-black text-[10px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.APPROVED ? 'border-green-600 bg-green-50 text-green-700' : 'border-slate-100 text-slate-400'}`}><CheckCircle2 size={14} /> Active</button>
                  <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.REJECTED)} className={`p-3 rounded-xl border-2 font-black text-[10px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${editingVolunteer.status === UserStatus.REJECTED ? 'border-red-600 bg-red-50 text-red-700' : 'border-slate-100 text-slate-400'}`}><Power size={14} /> Inactive</button>
                </div>
              </section>
            </div>

            <div className="pt-4 border-t flex flex-col gap-2">
              <button onClick={() => setEditingVolunteer(null)} className="w-full py-3 bg-slate-900 text-white rounded-xl font-bold uppercase text-xs tracking-widest hover:bg-black transition-all">Save Changes</button>
              <button onClick={() => setEditingVolunteer(null)} className="w-full py-2 text-slate-400 font-bold uppercase text-[9px] tracking-widest">Dismiss</button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  format, 
  parseISO, 
