interface AttendanceViewProps {
  currentUser: VolunteerProfile;
  volunteers: VolunteerProfile[];
  attendances: AttendanceRecord[];
  onCheckIn: (date: string) => void;
}

const AttendanceView: React.FC<AttendanceViewProps> = ({ 
  currentUser, 
  volunteers, 
  attendances, 
  onCheckIn 
}) => {
  const [selectedDate, setSelectedDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [searchTerm, setSearchTerm] = useState('');
  const [viewingMonth, setViewingMonth] = useState(new Date());
  const [copied, setCopied] = useState(false);

  const isAdmin = currentUser.role === UserRole.ADMIN;

  const userAttendances = attendances.filter(a => a.volunteerId === currentUser.id);
  const alreadyCheckedIn = userAttendances.some(a => a.date === selectedDate);

  const displayAttendances = (isAdmin ? attendances : userAttendances)
    .filter(a => {
      if (isAdmin && searchTerm) {
        const vol = volunteers.find(v => v.id === a.volunteerId);
        if (!vol?.name.toLowerCase().includes(searchTerm.toLowerCase())) return false;
      }
      const recordDate = parseISO(a.date);
      return isSameMonth(recordDate, viewingMonth) && isSameYear(recordDate, viewingMonth);
    })
    .sort((a, b) => b.timestamp.localeCompare(a.timestamp));

  const getVolunteer = (id: string) => volunteers.find(v => v.id === id);
  const qrCheckInUrl = `${window.location.origin}${window.location.pathname}#check-in`;

  const handleCopyLink = () => {
    navigator.clipboard.writeText(qrCheckInUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2">
      <h2 className="text-2xl font-black text-slate-900 tracking-tight">Attendance</h2>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-6">
            <div className="space-y-1.5">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block">Date</label>
              <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-xl font-bold text-xs" />
            </div>

            <button 
              onClick={() => !alreadyCheckedIn && onCheckIn(selectedDate)}
              disabled={alreadyCheckedIn}
              className={`w-full py-6 rounded-2xl shadow-md flex flex-col items-center justify-center gap-2 transition-all active:scale-95 ${alreadyCheckedIn ? 'bg-green-50 text-green-600' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}
            >
              <ClipboardCheck size={28} />
              <span className="text-lg font-black">{alreadyCheckedIn ? 'Logged' : 'Check In'}</span>
            </button>
          </div>

          <div className="bg-indigo-50/50 p-6 rounded-2xl border border-indigo-100 space-y-3">
            <h4 className="font-black text-slate-800 text-xs">QR Check-In</h4>
            <div className="flex gap-2">
              <input readOnly value={qrCheckInUrl} className="flex-1 bg-white border border-slate-200 rounded-lg px-2 py-1.5 text-[8px] font-bold text-slate-400" />
              <button onClick={handleCopyLink} className={`p-2 rounded-lg text-white ${copied ? 'bg-green-600' : 'bg-indigo-600'}`}>
                {copied ? <Check size={14} /> : <Copy size={14} />}
              </button>
            </div>
          </div>
        </div>

        <div className="md:col-span-2 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-black text-slate-800">History</h3>
            {isAdmin && <input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="px-3 py-1.5 bg-white border border-slate-200 rounded-xl text-xs w-32" />}
          </div>

          <div className="flex items-center justify-between bg-white px-4 py-2 rounded-2xl border border-slate-100 shadow-sm">
            <button onClick={() => setViewingMonth(subMonths(viewingMonth, 1))} className="p-1 text-slate-400 hover:text-indigo-600"><ChevronLeft size={20} /></button>
            <span className="text-sm font-black text-slate-800 tracking-tight">{format(viewingMonth, 'MMMM yyyy')}</span>
            <button onClick={() => setViewingMonth(addMonths(viewingMonth, 1))} className="p-1 text-slate-400 hover:text-indigo-600"><ChevronRight size={20} /></button>
          </div>

          <div className="space-y-3">
            {displayAttendances.length === 0 ? (
              <div className="bg-white p-12 rounded-3xl border border-dashed border-slate-200 text-center text-xs font-bold text-slate-400">No logs</div>
            ) : (
              displayAttendances.map(record => {
                const vol = getVolunteer(record.volunteerId);
                return (
                  <div key={record.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <img src={vol?.photoUrl} className="w-10 h-10 rounded-xl object-cover ring-2 ring-slate-50" alt={vol?.name} />
                      <div>
                        <p className="text-xs font-black text-slate-800">{isAdmin ? vol?.name : format(parseISO(record.date), 'MMMM do')}</p>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tight">{format(parseISO(record.timestamp), 'hh:mm a')}{isAdmin && ` • ${format(parseISO(record.date), 'MMM d')}`}</p>
                      </div>
                    </div>
                    <span className="px-3 py-1 bg-green-50 text-green-600 rounded-full text-[8px] font-black uppercase">Present</span>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

