const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
  disabled?: boolean;
}> = ({ currentImage, onImageChange, label = "Profile Photo", disabled = false }) => {
  const libraryInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const resizeImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_SIZE = 400;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const resized = await resizeImage(reader.result as string);
        onImageChange(resized);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-3">
      {label && <label className="text-xs font-black text-slate-400 uppercase tracking-widest block">{label}</label>}
      <div className="flex items-center gap-4">
        <div className="relative w-20 h-20 shrink-0">
          {isProcessing ? (
            <div className="w-full h-full rounded-xl bg-slate-100 flex items-center justify-center border border-indigo-100">
               <Loader2 className="animate-spin text-indigo-500" size={20} />
            </div>
          ) : (
            <img 
              src={currentImage || 'https://via.placeholder.com/150?text=No+Photo'} 
              className="w-full h-full rounded-xl object-cover ring-2 ring-indigo-50 shadow-sm"
              alt="Preview"
            />
          )}
        </div>
        {!disabled && (
          <div className="flex flex-col gap-2">
            <button 
              type="button" 
              onClick={() => cameraInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl font-bold text-[11px] uppercase tracking-wider hover:bg-indigo-700 transition-all active:scale-95"
            >
              <Camera size={14} /> Take Photo
            </button>
            <button 
              type="button" 
              onClick={() => libraryInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold text-[11px] uppercase tracking-wider hover:border-indigo-200 transition-all active:scale-95"
            >
              <ImageIcon size={14} /> Upload
            </button>
          </div>
        )}
      </div>
      <input type="file" ref={libraryInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
      <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
    </div>
  );
};

const AttendanceHistory: React.FC<{
