  attendances: AttendanceRecord[];
}> = ({ volunteerId, attendances }) => {
  const [viewingMonth, setViewingMonth] = useState(new Date());

  const userAttendances = useMemo(() => 
    attendances.filter(a => a.volunteerId === volunteerId),
    [attendances, volunteerId]
  );

  const monthRecords = useMemo(() => 
    userAttendances.filter(a => {
      const d = parseISO(a.date);
      return isSameMonth(d, viewingMonth) && isSameYear(d, viewingMonth);
    }).sort((a, b) => b.date.localeCompare(a.date)),
    [userAttendances, viewingMonth]
  );

  const totalSum = userAttendances.length;
  const monthSum = monthRecords.length;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-indigo-600 p-4 rounded-xl text-white shadow-sm flex items-center justify-between">
          <div>
            <p className="text-2xl font-black">{totalSum}</p>
            <p className="text-[10px] font-black uppercase tracking-wider opacity-80">Lifetime</p>
          </div>
          <TrendingUp size={20} className="opacity-40" />
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm flex items-center justify-between">
          <div>
            <p className="text-2xl font-black text-slate-800">{monthSum}</p>
            <p className="text-[10px] font-black uppercase tracking-wider text-slate-400">Month</p>
          </div>
          <History size={20} className="text-indigo-600 opacity-40" />
        </div>
      </div>

      <div className="bg-white p-4 rounded-xl border border-slate-100 space-y-3">
        <div className="flex items-center justify-between px-1">
          <button onClick={() => setViewingMonth(subMonths(viewingMonth, 1))} className="p-1.5 text-slate-400 hover:text-indigo-600">
            <ChevronLeft size={20} />
          </button>
          <p className="font-black text-slate-800 text-xs uppercase tracking-widest">{format(viewingMonth, 'MMMM yyyy')}</p>
          <button onClick={() => setViewingMonth(addMonths(viewingMonth, 1))} className="p-1.5 text-slate-400 hover:text-indigo-600">
            <ChevronRight size={20} />
          </button>
        </div>

        <div className="space-y-2 max-h-48 overflow-y-auto custom-scrollbar pr-1">
          {monthRecords.length === 0 ? (
            <div className="py-6 text-center text-slate-300 font-bold text-xs italic">No activity recorded</div>
          ) : (
            monthRecords.map(record => (
              <div key={record.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 bg-white rounded flex items-center justify-center text-indigo-600 shadow-sm">
                    <ClipboardCheck size={14} />
                  </div>
                  <div>
                    <p className="font-black text-slate-800 text-sm">{format(parseISO(record.date), 'EEE, do')}</p>
                    <p className="text-[10px] font-black uppercase tracking-tight text-slate-400">{format(parseISO(record.timestamp), 'hh:mm a')}</p>
                  </div>
                </div>
                <div className="px-2 py-0.5 bg-green-100 text-green-700 rounded-full text-[9px] font-black uppercase tracking-tight">Logged</div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('handson_state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return {
          currentUser: parsed.currentUser || null,
          volunteers: parsed.volunteers || INITIAL_VOLUNTEERS,
          shifts: parsed.shifts || INITIAL_SHIFTS,
          attendances: parsed.attendances || []
        };
      } catch (e) { console.error("Failed to load state", e); }
    }
    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS, attendances: [] };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isAutoCheckInPending, setIsAutoCheckInPending] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', preferredPeriod: 'MORNING' as ShiftPeriod, selectedDays: [] as number[], volunteerType: VolunteerType.VTP, area: ''
  });

  const [profileEditForm, setProfileEditForm] = useState<Partial<VolunteerProfile>>({});

  useEffect(() => {
    const checkHash = () => {
      if (window.location.hash === '#check-in') {
        setIsAutoCheckInPending(true);
      }
    };
    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  useEffect(() => {
    if (appState.currentUser && isAutoCheckInPending && appState.currentUser.status === UserStatus.APPROVED) {
      const today = format(new Date(), 'yyyy-MM-dd');
      handleAttendanceCheckIn(today);
      setIsAutoCheckInPending(false);
      window.history.replaceState(null, '', window.location.pathname + window.location.search);
      setActiveTab('attendance');
    }
  }, [appState.currentUser, isAutoCheckInPending]);

  useEffect(() => {
    try { localStorage.setItem('handson_state', JSON.stringify(appState)); } catch (e) { console.warn("Storage error:", e); }
  }, [appState]);

  const handleLogout = () => {
    setAppState(prev => ({ ...prev, currentUser: null }));
    setLoginForm({ email: '', phone: '' });
    setLoginError(null);
    setActiveTab('calendar');
    setIsRegistering(false);
    setIsEditingProfile(false);
    setIsAutoCheckInPending(false);
  };

  const handleLogin = () => {
    const { email, phone } = loginForm;
    setLoginError(null);

    if (!email || !phone) {
      setLoginError("Please enter your credentials.");
      return;
    }

    const user = appState.volunteers.find(v => 
      v.email.toLowerCase() === email.trim().toLowerCase() && 
      v.phone.trim() === phone.trim()
    );

    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (!isAutoCheckInPending) {
        setActiveTab(user.role === UserRole.ADMIN ? 'admin' : 'calendar');
      }
    } else {
      setLoginError("Invalid email or phone number.");
    }
  };

  const handleRegister = () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return alert("Please fill in all required fields.");
    if (regForm.volunteerType === VolunteerType.BASE && !regForm.area) return alert("Please specify your Area.");
    if (regForm.selectedDays.length === 0) return alert("Select at least one day for your availability.");

    const volunteerId = Math.random().toString(36).substring(2, 11);
    const newVol: VolunteerProfile = { 
      id: volunteerId, 
      name: regForm.name, 
      email: regForm.email, 
      phone: regForm.phone, 
      birthday: regForm.birthday, 
      photoUrl: regForm.photoUrl, 
      status: UserStatus.PENDING, 
      role: UserRole.VOLUNTEER, 
      volunteerType: regForm.volunteerType,
      area: regForm.volunteerType === VolunteerType.BASE ? regForm.area : undefined,
      joinedAt: new Date().toISOString() 
    };

    const newShift: Shift = { id: Math.random().toString(36).substring(2, 11), volunteerId: volunteerId, daysOfWeek: regForm.selectedDays, period: regForm.preferredPeriod };
    setAppState(prev => ({ ...prev, volunteers: [...prev.volunteers, newVol], shifts: [...prev.shifts, newShift], currentUser: newVol }));
    setActiveTab('profile');
    setIsRegistering(false);
  };

  const handleAttendanceCheckIn = (date: string) => {
    const userId = appState.currentUser?.id;
    if (!userId) return;
    if (appState.attendances.some(a => a.volunteerId === userId && a.date === date)) return;

    const newRecord: AttendanceRecord = {
      id: Math.random().toString(36).substring(2, 11),
      volunteerId: userId,
      date,
      timestamp: new Date().toISOString()
    };

    setAppState(prev => ({
      ...prev,
      attendances: [...prev.attendances, newRecord]
    }));
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, status } : prev.currentUser
    }));
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => {
      const newVols = prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v);
      return {
        ...prev,
        volunteers: newVols,
        currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, ...updates } : prev.currentUser,
      };
    });
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, ...updates }) : null);
    }
    if (isEditingProfile && appState.currentUser?.id === id) {
       setProfileEditForm(prev => ({ ...prev, ...updates }));
    }
  };

  const handleSaveProfile = () => {
    if (!appState.currentUser) return;
    handleUpdateVolunteerProfile(appState.currentUser.id, profileEditForm);
    setIsEditingProfile(false);
  };

  const startEditingProfile = () => {
    if (!appState.currentUser) return;
    setProfileEditForm({ ...appState.currentUser });
    setIsEditingProfile(true);
  };

  const handleUpdateShift = (id: string, updated: Partial<Shift>) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updated } : s) }));
  };

  const handleAddShift = (shift: Omit<Shift, 'id'>) => {
    const newShift = { ...shift, id: Math.random().toString(36).substring(2, 11) };
    setAppState(prev => ({ ...prev, shifts: [...prev.shifts, newShift] }));
  };

  const handleRemoveShift = (id: string) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.filter(s => s.id !== id) }));
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(appState.volunteers.filter(v => v.status === UserStatus.APPROVED).map(v => v.id));
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  const filteredVolunteers = useMemo(() => {
    return appState.volunteers.filter(v => {
      const searchMatch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!searchMatch) return false;
      return showInactiveInCommunity || v.status === UserStatus.APPROVED;
    });
  }, [appState.volunteers, searchTerm, showInactiveInCommunity]);

  const getStatusLabel = (status: UserStatus) => {
    switch (status) {
      case UserStatus.APPROVED: return 'Active';
      case UserStatus.REJECTED: return 'Inactive';
      case UserStatus.PENDING: return 'Pending';
      default: return status;
    }
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4 font-inter">
        <div className={`w-full ${isRegistering ? 'max-w-xl' : 'max-w-sm'} bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-100`}>
          <div className="bg-indigo-600 p-8 text-center relative overflow-hidden">
            <h1 className="text-2xl font-black text-white tracking-tight">HandsOn</h1>
            <p className="text-indigo-100 text-[11px] uppercase font-bold tracking-widest">Volunteer Portal</p>
          </div>
          {!isRegistering ? (
            <div className="p-8 space-y-6">
              {loginError && (
                <div className="bg-red-50 p-4 rounded-xl flex items-center gap-3">
                  <AlertCircle className="text-red-500" size={18} />
                  <p className="text-sm font-bold text-red-600">{loginError}</p>
                </div>
              )}
              <div className="space-y-4">
                <input placeholder="Email Address" type="email" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-medium focus:ring-2 focus:ring-indigo-500 transition-all" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
                <input placeholder="Phone Number" type="tel" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-medium focus:ring-2 focus:ring-indigo-500 transition-all" value={loginForm.phone} onChange={e => setLoginForm({...loginForm, phone: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
              </div>
              <button onClick={handleLogin} className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold text-base shadow-lg hover:bg-indigo-700 active:scale-95 transition-all">Sign In</button>
              <button onClick={() => setIsRegistering(true)} className="w-full py-2 text-indigo-600 font-bold text-sm hover:bg-indigo-50 rounded-lg transition-colors">Join our community</button>
            </div>
          ) : (
            <div className="p-8 space-y-8 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <h2 className="text-2xl font-black text-slate-800 tracking-tight">Volunteer Application</h2>
              <div className="space-y-6">
                <ImageCapture currentImage={regForm.photoUrl} onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} label="Identity Photo" />
                <div className="grid grid-cols-1 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500">Full Name</label>
                    <input placeholder="Enter full name" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500">Email Address</label>
                    <input placeholder="email@example.com" type="email" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-500">Phone</label>
                      <input placeholder="555-0101" type="tel" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-500">Birthday</label>
                      <input type="date" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                    </div>
                  </div>
                </div>
                <div className="space-y-3">
                  <label className="text-xs font-black text-slate-400 uppercase tracking-widest block">Volunteer Classification</label>
                  <div className="grid grid-cols-3 gap-3">
                    {ROLE_ORDER.map(type => (
                      <button key={type} onClick={() => setRegForm({...regForm, volunteerType: type})} className={`p-3 rounded-xl border-2 font-black text-[11px] transition-all ${regForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>{type}</button>
                    ))}
                  </div>
                  {regForm.volunteerType === VolunteerType.BASE && (
                    <div className="animate-in slide-in-from-top-2">
                       <label className="text-[10px] font-bold text-slate-500 mb-1 block">Assigned Area</label>
                       <input placeholder="Specify service territory" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none" value={regForm.area} onChange={e => setRegForm({...regForm, area: e.target.value})} />
                    </div>
                  )}
                </div>
              </div>
              <div className="flex gap-4 pt-4 sticky bottom-0 bg-white py-4 border-t">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-4 text-slate-400 font-bold text-sm">Cancel</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-xl font-bold text-sm shadow-xl hover:bg-indigo-700 transition-all">Apply Now</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={appState.currentUser.role} userName={appState.currentUser.name}>
      {activeTab === 'calendar' && (
        <ShiftCalendar shifts={activeShifts} volunteers={appState.volunteers} currentUser={appState.currentUser} onAddShift={(data) => handleAddShift({ ...data, volunteerId: appState.currentUser!.id })} onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift} />
      )}
      {activeTab === 'attendance' && (
        <AttendanceView currentUser={appState.currentUser} volunteers={appState.volunteers} attendances={appState.attendances} onCheckIn={handleAttendanceCheckIn} />
      )}
      {activeTab === 'volunteers' && (
        <div className="space-y-8">
          <div className="flex items-center justify-between gap-6">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight">Our Community</h2>
            <div className="relative">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input type="text" placeholder="Search team members..." className="pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none text-sm w-48 md:w-64 focus:ring-2 focus:ring-indigo-500 transition-all" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm relative hover:shadow-lg transition-all flex items-center gap-4">
                <img src={volunteer.photoUrl} className="w-14 h-14 rounded-2xl object-cover ring-4 ring-indigo-50/50 shadow-sm" />
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-slate-800 text-base truncate flex items-center gap-2">
                    {volunteer.name}
                    {volunteer.role === UserRole.ADMIN && <ShieldCheck size={14} className="text-indigo-600" />}
                  </h3>
                  <div className="flex items-center gap-1.5 mt-1">
                    <span className="text-[10px] font-black uppercase tracking-tight px-2 py-0.5 rounded bg-indigo-50 text-indigo-600">{volunteer.volunteerType}</span>
                    <span className={`text-[10px] font-black uppercase tracking-tight px-2 py-0.5 rounded ${volunteer.status === UserStatus.APPROVED ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
                      {getStatusLabel(volunteer.status)}
                    </span>
                  </div>
                  {volunteer.volunteerType === VolunteerType.BASE && volunteer.area && (
                    <div className="flex items-center gap-1.5 mt-1.5 text-slate-400">
                      <MapPin size={10} className="shrink-0" />
                      <span className="text-[10px] font-bold truncate uppercase tracking-tight">{volunteer.area}</span>
                    </div>
                  )}
                </div>
                {isAdmin && (<button onClick={() => setEditingVolunteer(volunteer)} className="p-2 text-slate-300 hover:text-indigo-600 transition-all hover:bg-slate-50 rounded-xl"><Edit2 size={16} /></button>)}
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-xl space-y-8">
            <div className="flex flex-col md:flex-row items-center md:items-end justify-between gap-6 border-b pb-8">
              <div className="flex flex-col md:flex-row items-center gap-6">
                <div className="relative">
                  {isEditingProfile ? (
                    <ImageCapture currentImage={profileEditForm.photoUrl || appState.currentUser.photoUrl} onImageChange={(url) => setProfileEditForm(prev => ({ ...prev, photoUrl: url }))} label="" />
                  ) : (
                    <img src={appState.currentUser.photoUrl} className="w-24 h-24 rounded-2xl object-cover ring-8 ring-indigo-50 shadow-lg" />
                  )}
                </div>
                <div className="text-center md:text-left">
                  <h2 className="text-3xl font-black text-slate-900 tracking-tight">{appState.currentUser.name}</h2>
                  <div className="flex items-center justify-center md:justify-start gap-2 mt-2">
                    <span className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.2em] bg-indigo-50 px-3 py-1 rounded-full">{appState.currentUser.role}</span>
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] bg-slate-100 px-3 py-1 rounded-full">{appState.currentUser.volunteerType}</span>
                  </div>
                </div>
              </div>
              <button onClick={isEditingProfile ? handleSaveProfile : startEditingProfile} className={`flex items-center gap-2 px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-lg transition-all active:scale-95 ${isEditingProfile ? 'bg-green-600 text-white' : 'bg-indigo-600 text-white'}`}>
                {isEditingProfile ? <><Save size={16} /> Save Changes</> : <><Edit2 size={16} /> Edit Profile</>}
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><User size={12} /> Full Name</label>
                {isEditingProfile ? <input className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={profileEditForm.name || ''} onChange={e => setProfileEditForm({...profileEditForm, name: e.target.value})} /> : <p className="font-bold text-slate-900 text-lg">{appState.currentUser.name}</p>}
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><Mail size={12} /> Email Address</label>
                {isEditingProfile ? <input className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={profileEditForm.email || ''} onChange={e => setProfileEditForm({...profileEditForm, email: e.target.value})} /> : <p className="font-bold text-slate-900 text-lg break-all">{appState.currentUser.email}</p>}
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><Phone size={12} /> Mobile Phone</label>
                {isEditingProfile ? <input className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={profileEditForm.phone || ''} onChange={e => setProfileEditForm({...profileEditForm, phone: e.target.value})} /> : <p className="font-bold text-slate-900 text-lg">{appState.currentUser.phone}</p>}
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><Cake size={12} /> Date of Birth</label>
                {isEditingProfile ? <input type="date" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={profileEditForm.birthday || ''} onChange={e => setProfileEditForm({...profileEditForm, birthday: e.target.value})} /> : <p className="font-bold text-slate-900 text-lg">{appState.currentUser.birthday}</p>}
              </div>

              <div className="space-y-4 md:col-span-2 pt-4 border-t border-slate-50">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2"><Tag size={12} /> Volunteer Classification</label>
                {isEditingProfile ? (
