                  <button onClick={() => handleAddShift({ volunteerId: editingVolunteer.id, daysOfWeek: [1], period: 'MORNING' })} className="w-full py-3 border-2 border-dashed border-indigo-100 text-indigo-500 text-[11px] font-black uppercase rounded-xl hover:bg-indigo-50 transition-colors flex items-center justify-center gap-2">
