                  </button>
                </div>
              </section>

              <section className="space-y-4 pt-4 border-t border-slate-50">
                <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Classification & Territory</p>
                <div className="space-y-4">
                  <div className="flex flex-wrap gap-2">
                    {ROLE_ORDER.map(t => (
                      <button key={t} onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { volunteerType: t })} className={`px-4 py-2 rounded-xl border-2 font-black text-[11px] uppercase tracking-widest transition-all ${editingVolunteer.volunteerType === t ? 'bg-slate-800 border-slate-800 text-white shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>{t}</button>
                    ))}
                  </div>
                  {editingVolunteer.volunteerType === VolunteerType.BASE && (
                    <div className="animate-in slide-in-from-top-2">
                      <label className="text-[10px] font-bold text-slate-500 mb-1.5 block">Service Area</label>
                      <input placeholder="Territory name" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" value={editingVolunteer.area || ''} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { area: e.target.value })} />
                    </div>
                  )}
                </div>
              </section>

              <section className="space-y-6 pt-6 border-t-2 border-indigo-50 bg-indigo-50/20 -mx-8 px-8 py-8">
                <p className="text-xs font-black text-indigo-400 uppercase tracking-widest">System Access & Status</p>

                <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Access Level</label>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { role: UserRole.VOLUNTEER })} className={`flex items-center justify-center gap-2 p-4 rounded-2xl border-2 font-black text-xs uppercase transition-all ${editingVolunteer.role === UserRole.VOLUNTEER ? 'bg-white border-indigo-600 text-indigo-700 shadow-lg' : 'bg-slate-100 border-transparent text-slate-400'}`}>
                      <User size={16} /> Volunteer
                    </button>
                    <button onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { role: UserRole.ADMIN })} className={`flex items-center justify-center gap-2 p-4 rounded-2xl border-2 font-black text-xs uppercase transition-all ${editingVolunteer.role === UserRole.ADMIN ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-slate-100 border-transparent text-slate-400'}`}>
                      <ShieldCheck size={16} /> Admin
                    </button>
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Account Lifecycle</label>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.APPROVED)} className={`flex items-center justify-center gap-2 p-4 rounded-2xl border-2 font-black text-xs uppercase transition-all ${editingVolunteer.status === UserStatus.APPROVED ? 'border-green-600 bg-green-50 text-green-700 shadow-lg' : 'bg-slate-100 border-transparent text-slate-400'}`}>
                      <CheckCircle2 size={18} /> Active
                    </button>
                    <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.REJECTED)} className={`flex items-center justify-center gap-2 p-4 rounded-2xl border-2 font-black text-xs uppercase transition-all ${editingVolunteer.status === UserStatus.REJECTED ? 'border-red-600 bg-red-50 text-red-700 shadow-lg' : 'bg-slate-100 border-transparent text-slate-400'}`}>
                      <Power size={18} /> Inactive
                    </button>
                  </div>
                </div>
              </section>
            </div>

            <button onClick={() => setEditingVolunteer(null)} className="w-full py-4.5 bg-slate-900 text-white rounded-2xl font-black uppercase text-sm tracking-widest shadow-2xl hover:bg-black transition-all active:scale-95">
              Confirm Management Update
            </button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

