    return { currentUser: null, volunteers: INITIAL_VOLUNTEERS, shifts: INITIAL_SHIFTS, attendances: [] };
  });

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isAutoCheckInPending, setIsAutoCheckInPending] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', preferredPeriod: 'MORNING' as ShiftPeriod, selectedDays: [] as number[], volunteerType: VolunteerType.VTP, area: ''
  });

  const [profileEditForm, setProfileEditForm] = useState<Partial<VolunteerProfile>>({});

  useEffect(() => {
    const checkHash = () => {
      if (window.location.hash === '#check-in') {
        setIsAutoCheckInPending(true);
      }
    };
    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  useEffect(() => {
    if (appState.currentUser && isAutoCheckInPending && appState.currentUser.status === UserStatus.APPROVED) {
      const today = format(new Date(), 'yyyy-MM-dd');
      handleAttendanceCheckIn(today);
      setIsAutoCheckInPending(false);
      window.history.replaceState(null, '', window.location.pathname + window.location.search);
      setActiveTab('attendance');
    }
  }, [appState.currentUser, isAutoCheckInPending]);

  useEffect(() => {
    try { localStorage.setItem('voluapp_state', JSON.stringify(appState)); } catch (e) { console.warn("Error de almacenamiento:", e); }
  }, [appState]);

  const handleLogout = () => {
    setAppState(prev => ({ ...prev, currentUser: null }));
    setLoginForm({ email: '', phone: '' });
    setLoginError(null);
    setActiveTab('calendar');
    setIsRegistering(false);
    setIsEditingProfile(false);
    setIsAutoCheckInPending(false);
  };

  const handleLogin = () => {
    const { email, phone } = loginForm;
    setLoginError(null);

    if (!email || !phone) {
      setLoginError("Por favor, ingresa tus credenciales.");
      return;
    }

    const user = appState.volunteers.find(v => 
      v.email.toLowerCase() === email.trim().toLowerCase() && 
      v.phone.trim() === phone.trim()
    );

    if (user) {
      setAppState(prev => ({ ...prev, currentUser: user }));
      if (!isAutoCheckInPending) {
        setActiveTab(user.role === UserRole.ADMIN ? 'admin' : 'calendar');
      }
    } else {
      setLoginError("Correo o teléfono inválidos.");
    }
  };

  const handleRegister = () => {
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return alert("Por favor, completa todos los campos requeridos.");
    if (regForm.volunteerType === VolunteerType.BASE && !regForm.area) return alert("Por favor, especifica tu Área.");
    if (regForm.selectedDays.length === 0) return alert("Selecciona al menos un día de disponibilidad.");

    const volunteerId = Math.random().toString(36).substring(2, 11);
    const newVol: VolunteerProfile = { 
      id: volunteerId, 
      name: regForm.name, 
      email: regForm.email, 
      phone: regForm.phone, 
      birthday: regForm.birthday, 
      photoUrl: regForm.photoUrl, 
      status: UserStatus.PENDING, 
      role: UserRole.VOLUNTEER, 
      volunteerType: regForm.volunteerType,
      area: regForm.volunteerType === VolunteerType.BASE ? regForm.area : undefined,
      joinedAt: new Date().toISOString() 
    };

    const newShift: Shift = { id: Math.random().toString(36).substring(2, 11), volunteerId: volunteerId, daysOfWeek: regForm.selectedDays, period: regForm.preferredPeriod };
    setAppState(prev => ({ ...prev, volunteers: [...prev.volunteers, newVol], shifts: [...prev.shifts, newShift], currentUser: newVol }));
    setActiveTab('profile');
    setIsRegistering(false);
  };

  const handleAttendanceCheckIn = (date: string) => {
    const userId = appState.currentUser?.id;
    if (!userId) return;
    if (appState.attendances.some(a => a.volunteerId === userId && a.date === date)) return;

    const newRecord: AttendanceRecord = {
      id: Math.random().toString(36).substring(2, 11),
      volunteerId: userId,
      date,
      timestamp: new Date().toISOString()
    };

    setAppState(prev => ({
      ...prev,
      attendances: [...prev.attendances, newRecord]
    }));
  };

  const updateVolunteerStatus = (id: string, status: UserStatus) => {
    setAppState(prev => ({
      ...prev,
      volunteers: prev.volunteers.map(v => v.id === id ? { ...v, status } : v),
      currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, status } : prev.currentUser
    }));
  };

  const handleUpdateVolunteerProfile = (id: string, updates: Partial<VolunteerProfile>) => {
    setAppState(prev => {
      const newVols = prev.volunteers.map(v => v.id === id ? { ...v, ...updates } : v);
      return {
        ...prev,
        volunteers: newVols,
        currentUser: prev.currentUser?.id === id ? { ...prev.currentUser!, ...updates } : prev.currentUser,
      };
    });
    if (editingVolunteer?.id === id) {
      setEditingVolunteer(prev => prev ? ({ ...prev, ...updates }) : null);
    }
    if (isEditingProfile && appState.currentUser?.id === id) {
       setProfileEditForm(prev => ({ ...prev, ...updates }));
    }
  };

  const handleSaveProfile = () => {
    if (!appState.currentUser) return;
    handleUpdateVolunteerProfile(appState.currentUser.id, profileEditForm);
    setIsEditingProfile(false);
  };

  const startEditingProfile = () => {
    if (!appState.currentUser) return;
    setProfileEditForm({ ...appState.currentUser });
    setIsEditingProfile(true);
  };

  const handleUpdateShift = (id: string, updated: Partial<Shift>) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.map(s => s.id === id ? { ...s, ...updated } : s) }));
  };

  const handleAddShift = (shift: Omit<Shift, 'id'>) => {
    const newShift = { ...shift, id: Math.random().toString(36).substring(2, 11) };
    setAppState(prev => ({ ...prev, shifts: [...prev.shifts, newShift] }));
  };

  const handleRemoveShift = (id: string) => {
    setAppState(prev => ({ ...prev, shifts: prev.shifts.filter(s => s.id !== id) }));
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(appState.volunteers.filter(v => v.status === UserStatus.APPROVED).map(v => v.id));
    return appState.shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [appState.volunteers, appState.shifts]);

  const filteredVolunteers = useMemo(() => {
    return appState.volunteers.filter(v => {
      const searchMatch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!searchMatch) return false;
      return showInactiveInCommunity || v.status === UserStatus.APPROVED;
    });
  }, [appState.volunteers, searchTerm, showInactiveInCommunity]);

  const getStatusLabel = (status: UserStatus) => {
    switch (status) {
      case UserStatus.APPROVED: return 'Activo';
      case UserStatus.REJECTED: return 'Inactivo';
      case UserStatus.PENDING: return 'Pendiente';
      default: return status;
    }
  };

  if (!appState.currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4 font-inter">
        <div className={`w-full ${isRegistering ? 'max-w-xl' : 'max-w-sm'} bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-100`}>
          <div className="bg-indigo-600 p-10 text-center relative overflow-hidden">
            <h1 className="text-3xl font-black text-white tracking-tight">VoluApp</h1>
            <p className="text-indigo-100 text-xs uppercase font-bold tracking-[0.2em] mt-1">Portal de Voluntarios</p>
          </div>
          {!isRegistering ? (
            <div className="p-10 space-y-8">
              {loginError && (
                <div className="bg-red-50 p-4 rounded-xl flex items-center gap-3">
                  <AlertCircle className="text-red-500" size={20} />
                  <p className="text-sm font-bold text-red-600">{loginError}</p>
                </div>
              )}
              <div className="space-y-4">
                <input placeholder="Correo Electrónico" type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none text-base font-medium focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
                <input placeholder="Teléfono Móvil" type="tel" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none text-base font-medium focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" value={loginForm.phone} onChange={e => setLoginForm({...loginForm, phone: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
              </div>
              <button onClick={handleLogin} className="w-full bg-indigo-600 text-white py-5 rounded-xl font-bold text-lg shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Iniciar Sesión</button>
              <button onClick={() => setIsRegistering(true)} className="w-full py-2 text-indigo-600 font-bold text-base hover:bg-indigo-50 rounded-lg transition-colors">Únete a nuestra comunidad</button>
            </div>
          ) : (
            <div className="p-10 space-y-10 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <h2 className="text-3xl font-black text-slate-800 tracking-tight">Solicitud de Registro</h2>
              <div className="space-y-8">
                <ImageCapture currentImage={regForm.photoUrl} onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} label="Foto de Identificación" />
                <div className="grid grid-cols-1 gap-5">
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-500">Nombre Completo</label>
                    <input placeholder="Escribe tu nombre y apellidos" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-500">Correo Electrónico</label>
                    <input placeholder="ejemplo@correo.com" type="email" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                  </div>
                  <div className="grid grid-cols-2 gap-5">
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-slate-500">Teléfono</label>
                      <input placeholder="555-0101" type="tel" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-slate-500">Fecha Nacimiento</label>
                      <input type="date" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                    </div>
                  </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block">Clasificación de Voluntario</label>
                  <div className="grid grid-cols-3 gap-3">
                    {ROLE_ORDER.map(type => (
                      <button key={type} onClick={() => setRegForm({...regForm, volunteerType: type})} className={`p-4 rounded-xl border-2 font-black text-xs transition-all ${regForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'}`}>{type}</button>
                    ))}
                  </div>
                  {regForm.volunteerType === VolunteerType.BASE && (
                    <div className="animate-in slide-in-from-top-3">
                       <label className="text-xs font-bold text-slate-500 mb-2 block">Área Asignada</label>
                       <input placeholder="Especifica tu territorio de servicio" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.area} onChange={e => setRegForm({...regForm, area: e.target.value})} />
                    </div>
                  )}
                </div>
              </div>
              <div className="flex gap-4 pt-6 sticky bottom-0 bg-white py-6 border-t">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-5 text-slate-400 font-bold text-base hover:text-slate-600 transition-colors">Cancelar</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-5 rounded-xl font-bold text-base shadow-2xl hover:bg-indigo-700 transition-all">Enviar Solicitud</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = appState.currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={appState.currentUser.role} userName={appState.currentUser.name}>
      {activeTab === 'calendar' && (
        <ShiftCalendar shifts={activeShifts} volunteers={appState.volunteers} currentUser={appState.currentUser} onAddShift={(data) => handleAddShift({ ...data, volunteerId: appState.currentUser!.id })} onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift} />
      )}
      {activeTab === 'attendance' && (
        <AttendanceView currentUser={appState.currentUser} volunteers={appState.volunteers} attendances={appState.attendances} onCheckIn={handleAttendanceCheckIn} />
      )}
      {activeTab === 'volunteers' && (
        <div className="space-y-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
            <h2 className="text-3xl font-black text-slate-800 tracking-tight">Nuestra Comunidad</h2>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" placeholder="Buscar equipo..." className="pl-12 pr-5 py-3.5 bg-white border-2 border-slate-200 rounded-2xl outline-none text-base w-full md:w-80 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm relative hover:shadow-xl transition-all flex items-center gap-5">
                <img src={volunteer.photoUrl} className="w-16 h-16 rounded-2xl object-cover ring-4 ring-indigo-50/50 shadow-md" />
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-slate-800 text-lg truncate flex items-center gap-2">
                    {volunteer.name}
                    {volunteer.role === UserRole.ADMIN && <ShieldCheck size={16} className="text-indigo-600" />}
                  </h3>
                  <div className="flex items-center gap-2 mt-1.5">
                    <span className="text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded bg-indigo-50 text-indigo-600">{volunteer.volunteerType}</span>
                    <span className={`text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded ${volunteer.status === UserStatus.APPROVED ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
                      {getStatusLabel(volunteer.status)}
                    </span>
                  </div>
                  {volunteer.volunteerType === VolunteerType.BASE && volunteer.area && (
                    <div className="flex items-center gap-2 mt-2 text-slate-400">
                      <MapPin size={12} className="shrink-0" />
                      <span className="text-[11px] font-bold truncate uppercase tracking-tight">{volunteer.area}</span>
                    </div>
                  )}
                </div>
                {isAdmin && (<button onClick={() => setEditingVolunteer(volunteer)} className="p-2.5 text-slate-300 hover:text-indigo-600 transition-all hover:bg-indigo-50 rounded-2xl"><Edit2 size={18} /></button>)}
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-3xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-2xl space-y-10">
            <div className="flex flex-col md:flex-row items-center md:items-end justify-between gap-8 border-b pb-10">
              <div className="flex flex-col md:flex-row items-center gap-8">
                <div className="relative">
                  {isEditingProfile ? (
                    <ImageCapture currentImage={profileEditForm.photoUrl || appState.currentUser.photoUrl} onImageChange={(url) => setProfileEditForm(prev => ({ ...prev, photoUrl: url }))} label="" />
                  ) : (
                    <img src={appState.currentUser.photoUrl} className="w-28 h-28 rounded-3xl object-cover ring-8 ring-indigo-50 shadow-xl" />
                  )}
                </div>
                <div className="text-center md:text-left">
                  <h2 className="text-4xl font-black text-slate-900 tracking-tight">{appState.currentUser.name}</h2>
                  <div className="flex items-center justify-center md:justify-start gap-3 mt-3">
                    <span className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.25em] bg-indigo-50 px-4 py-1.5 rounded-full">{isAdmin ? 'Administrador' : 'Voluntario'}</span>
                    {!isEditingProfile && <span className="text-[11px] font-black text-slate-500 uppercase tracking-[0.25em] bg-slate-100 px-4 py-1.5 rounded-full">{appState.currentUser.volunteerType}</span>}
                  </div>
                </div>
              </div>
              <button onClick={isEditingProfile ? handleSaveProfile : startEditingProfile} className={`flex items-center gap-3 px-8 py-5 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl transition-all active:scale-95 ${isEditingProfile ? 'bg-green-600 text-white shadow-green-100' : 'bg-indigo-600 text-white shadow-indigo-100'}`}>
                {isEditingProfile ? <><Save size={20} /> Guardar Cambios</> : <><Edit2 size={20} /> Editar Perfil</>}
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-14 gap-y-10">
              <div className="space-y-3">
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em] flex items-center gap-2"><User size={14} /> Nombre Completo</label>
                {isEditingProfile ? <input className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={profileEditForm.name || ''} onChange={e => setProfileEditForm({...profileEditForm, name: e.target.value})} /> : <p className="font-bold text-slate-900 text-xl">{appState.currentUser.name}</p>}
              </div>
              <div className="space-y-3">
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em] flex items-center gap-2"><Mail size={14} /> Correo Electrónico</label>
                {isEditingProfile ? <input className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={profileEditForm.email || ''} onChange={e => setProfileEditForm({...profileEditForm, email: e.target.value})} /> : <p className="font-bold text-slate-900 text-xl break-all">{appState.currentUser.email}</p>}
              </div>
              <div className="space-y-3">
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em] flex items-center gap-2"><Phone size={14} /> Teléfono Móvil</label>
                {isEditingProfile ? <input className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={profileEditForm.phone || ''} onChange={e => setProfileEditForm({...profileEditForm, phone: e.target.value})} /> : <p className="font-bold text-slate-900 text-xl">{appState.currentUser.phone}</p>}
              </div>
              <div className="space-y-3">
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em] flex items-center gap-2"><Cake size={14} /> Fecha de Nacimiento</label>
                {isEditingProfile ? <input type="date" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={profileEditForm.birthday || ''} onChange={e => setProfileEditForm({...profileEditForm, birthday: e.target.value})} /> : <p className="font-bold text-slate-900 text-xl">{appState.currentUser.birthday}</p>}
              </div>

              <div className="space-y-6 md:col-span-2 pt-6 border-t border-slate-50">
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em] flex items-center gap-2"><Tag size={14} /> Clasificación de Voluntario</label>
                {isEditingProfile ? (
                  <div className="space-y-6">
                    <div className="grid grid-cols-3 gap-4">
                      {ROLE_ORDER.map(type => (
                        <button key={type} onClick={() => setProfileEditForm({...profileEditForm, volunteerType: type})} className={`p-4 rounded-xl border-2 font-black text-sm transition-all ${profileEditForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white shadow-xl' : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'}`}>{type}</button>
                      ))}
                    </div>
                    {(profileEditForm.volunteerType === VolunteerType.BASE) && (
                      <div className="animate-in slide-in-from-top-3 space-y-2">
                        <label className="text-sm font-bold text-slate-500">Área de Servicio</label>
                        <input className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={profileEditForm.area || ''} onChange={e => setProfileEditForm({...profileEditForm, area: e.target.value})} placeholder="Especifica tu área" />
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="flex flex-wrap items-center gap-6">
                    <p className="font-bold text-slate-900 text-xl">{appState.currentUser.volunteerType}</p>
                    {appState.currentUser.volunteerType === VolunteerType.BASE && appState.currentUser.area && (
                      <div className="flex items-center gap-3 bg-slate-50 px-5 py-3 rounded-2xl border border-slate-100 shadow-sm">
                        <MapPin size={20} className="text-indigo-400" />
                        <span className="font-bold text-slate-700 text-lg uppercase tracking-tight">{appState.currentUser.area}</span>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
          <AttendanceHistory volunteerId={appState.currentUser.id} attendances={appState.attendances} />
        </div>
      )}
      {activeTab === 'admin' && isAdmin && (
        <AdminDashboard volunteers={appState.volunteers} onUpdateStatus={updateVolunteerStatus} onEditVolunteer={setEditingVolunteer} />
      )}
      {editingVolunteer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg my-10 p-10 shadow-2xl space-y-10 relative animate-in zoom-in duration-300">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">Gestionar Miembro</h3>
                <p className="text-indigo-600 text-[11px] font-black tracking-widest mt-1.5 uppercase">ID de Perfil: #{editingVolunteer.id.toUpperCase()}</p>
              </div>
              <button onClick={() => setEditingVolunteer(null)} className="p-3 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-2xl transition-all active:scale-90"><X size={24} /></button>
            </div>

            <div className="space-y-12 max-h-[65vh] overflow-y-auto custom-scrollbar pr-4">
              <section className="space-y-6">
                 <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em]">Datos Personales</p>
                 <ImageCapture currentImage={editingVolunteer.photoUrl} onImageChange={(url) => handleUpdateVolunteerProfile(editingVolunteer.id, { photoUrl: url })} label="Imagen de Identidad" />
                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500">Nombre</label>
                      <input className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={editingVolunteer.name} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { name: e.target.value })} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500">Correo</label>
                      <input className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={editingVolunteer.email} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { email: e.target.value })} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500">Teléfono</label>
                      <input className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={editingVolunteer.phone} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { phone: e.target.value })} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500">Cumpleaños</label>
                      <input type="date" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={editingVolunteer.birthday} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { birthday: e.target.value })} />
                    </div>
                 </div>
              </section>

              <section className="space-y-6 pt-6 border-t border-slate-100">
                <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em]">Horario de Servicio</p>
                <div className="space-y-4">
                  {appState.shifts.filter(s => s.volunteerId === editingVolunteer.id).map(shift => (
                    <div key={shift.id} className="bg-slate-50 p-5 rounded-2xl border border-slate-200 space-y-4 shadow-sm">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          {shift.period === 'MORNING' ? <Sun size={18} className="text-blue-500" /> : <Moon size={18} className="text-amber-500" />}
                          <span className="text-xs font-black text-slate-700 uppercase tracking-widest">Bloque de {shift.period === 'MORNING' ? 'Mañana' : 'Tarde'}</span>
                        </div>
                        <button onClick={() => handleRemoveShift(shift.id)} className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={18} /></button>
                      </div>
                      <div className="grid grid-cols-7 gap-2">
                        {['D','L','M','X','J','V','S'].map((n, i) => (
                          <button key={i} onClick={() => handleUpdateShift(shift.id, { daysOfWeek: shift.daysOfWeek.includes(i) ? shift.daysOfWeek.filter(d => d !== i) : [...shift.daysOfWeek, i] })} className={`h-10 rounded-xl font-black text-xs shadow-sm transition-all border-2 ${shift.daysOfWeek.includes(i) ? 'bg-indigo-600 border-indigo-600 text-white shadow-indigo-100' : 'bg-white text-slate-300 border-slate-100 hover:border-indigo-200'}`}>{n}</button>
                        ))}
                      </div>
                    </div>
                  ))}
                  <button onClick={() => handleAddShift({ volunteerId: editingVolunteer.id, daysOfWeek: [1], period: 'MORNING' })} className="w-full py-4 border-2 border-dashed border-indigo-100 text-indigo-500 text-[11px] font-black uppercase rounded-2xl hover:bg-indigo-50 transition-colors flex items-center justify-center gap-2">
                    <Plus size={18} /> Nuevo Bloque de Disponibilidad
                  </button>
                </div>
              </section>

              <section className="space-y-6 pt-6 border-t border-slate-100">
                <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.25em]">Clasificación y Territorio</p>
                <div className="space-y-6">
                  <div className="flex flex-wrap gap-3">
                    {ROLE_ORDER.map(t => (
                      <button key={t} onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { volunteerType: t })} className={`px-5 py-2.5 rounded-xl border-2 font-black text-xs uppercase tracking-widest transition-all ${editingVolunteer.volunteerType === t ? 'bg-slate-800 border-slate-800 text-white shadow-xl' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-800 hover:text-slate-800'}`}>{t}</button>
                    ))}
                  </div>
                  {editingVolunteer.volunteerType === VolunteerType.BASE && (
                    <div className="animate-in slide-in-from-top-3">
                      <label className="text-xs font-bold text-slate-500 mb-2 block">Territorio Asignado</label>
                      <input placeholder="Nombre de la zona o barrio" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus:border-indigo-500 transition-all" value={editingVolunteer.area || ''} onChange={e => handleUpdateVolunteerProfile(editingVolunteer.id, { area: e.target.value })} />
                    </div>
                  )}
                </div>
              </section>

              <section className="space-y-8 pt-8 border-t-4 border-indigo-50 bg-indigo-50/20 -mx-10 px-10 pb-10">
                <div>
                  <p className="text-[11px] font-black text-indigo-400 uppercase tracking-[0.25em] mb-6">Nivel de Acceso y Estado</p>

                  <div className="space-y-4">
                    <label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest block">Rol en el Sistema</label>
                    <div className="grid grid-cols-2 gap-4">
                      <button onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { role: UserRole.VOLUNTEER })} className={`flex items-center justify-center gap-3 p-5 rounded-2xl border-2 font-black text-sm uppercase transition-all shadow-sm ${editingVolunteer.role === UserRole.VOLUNTEER ? 'bg-white border-indigo-600 text-indigo-700 shadow-indigo-100 ring-4 ring-indigo-500/5' : 'bg-slate-50 border-transparent text-slate-400'}`}>
                        <User size={20} /> Voluntario
                      </button>
                      <button onClick={() => handleUpdateVolunteerProfile(editingVolunteer.id, { role: UserRole.ADMIN })} className={`flex items-center justify-center gap-3 p-5 rounded-2xl border-2 font-black text-sm uppercase transition-all shadow-sm ${editingVolunteer.role === UserRole.ADMIN ? 'bg-indigo-600 border-indigo-600 text-white shadow-indigo-100' : 'bg-slate-50 border-transparent text-slate-400'}`}>
                        <ShieldCheck size={20} /> Administrador
                      </button>
                    </div>
                  </div>
                </div>

                <div className="space-y-4 pt-4">
                  <label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest block">Ciclo de Vida de Cuenta</label>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.APPROVED)} className={`flex items-center justify-center gap-3 p-5 rounded-2xl border-2 font-black text-sm uppercase transition-all shadow-sm ${editingVolunteer.status === UserStatus.APPROVED ? 'border-green-600 bg-green-50 text-green-700 shadow-green-100 ring-4 ring-green-500/5' : 'bg-slate-50 border-transparent text-slate-400'}`}>
                      <CheckCircle2 size={22} /> Activo
                    </button>
                    <button onClick={() => updateVolunteerStatus(editingVolunteer.id, UserStatus.REJECTED)} className={`flex items-center justify-center gap-3 p-5 rounded-2xl border-2 font-black text-sm uppercase transition-all shadow-sm ${editingVolunteer.status === UserStatus.REJECTED ? 'border-red-600 bg-red-50 text-red-700 shadow-red-100 ring-4 ring-red-500/5' : 'bg-slate-50 border-transparent text-slate-400'}`}>
                      <Power size={22} /> Inactivo
                    </button>
                  </div>
                </div>
              </section>
            </div>

            <button onClick={() => setEditingVolunteer(null)} className="w-full py-6 bg-slate-900 text-white rounded-2xl font-black uppercase text-base tracking-widest shadow-2xl hover:bg-black transition-all active:scale-95 focus:ring-4 focus:ring-slate-900/20">
              Confirmar Cambios de Gestión
            </button>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  format, 
  addWeeks, 
  // subWeeks replaced by addWeeks(d, -n)
  // startOfWeek replaced by manual calculation
  endOfWeek, 
  eachDayOfInterval, 
  isSameDay, 
  getDay,
  isToday
} from 'date-fns';
// Fix for missing locale member in some environments
import { es } from 'date-fns/locale/es';
import { ChevronLeft, ChevronRight, Plus, Clock, Calendar, Trash2, Edit2, CalendarDays, Sun, Moon } from 'lucide-react';
import { Shift, VolunteerProfile, ShiftPeriod } from '../types';

interface ShiftCalendarProps {
  shifts: Shift[];
  volunteers: VolunteerProfile[];
  currentUser: VolunteerProfile;
  onAddShift: (shift: Omit<Shift, 'id' | 'volunteerId'>) => void;
  onUpdateShift: (id: string, updated: Partial<Shift>) => void;
  onRemoveShift: (shiftId: string) => void;
}

const ShiftCalendar: React.FC<ShiftCalendarProps> = ({ 
  shifts, 
  volunteers,
  currentUser, 
  onAddShift, 
  onUpdateShift,
  onRemoveShift 
}) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [editingShiftId, setEditingShiftId] = useState<string | null>(null);

  const [selectedPeriod, setSelectedPeriod] = useState<ShiftPeriod>('MORNING');
  const [selectedDays, setSelectedDays] = useState<number[]>([]);

  // Fixed missing startOfWeek member: Manual implementation of startOfWeek(currentDate, { weekStartsOn: 1 })
  const weekStart = (() => {
    const d = new Date(currentDate);
    const day = d.getDay();
    const diff = (day === 0 ? -6 : 1 - day);
    d.setDate(d.getDate() + diff);
    d.setHours(0, 0, 0, 0);
    return d;
  })();

  const weekEnd = endOfWeek(weekStart, { weekStartsOn: 1 });
  const weekDays = eachDayOfInterval({ start: weekStart, end: weekEnd });

  const getShiftsForDay = (day: Date, period?: ShiftPeriod) => {
    const dayOfWeek = getDay(day);
    return shifts.filter(s => 
      s.daysOfWeek.includes(dayOfWeek) && 
      (!period || s.period === period)
    );
  };

  const handleOpenAdd = () => {
    setEditingShiftId(null);
    setSelectedPeriod('MORNING');
    setSelectedDays([getDay(new Date())]);
    setShowModal(true);
  };

  const handleOpenEdit = (shift: Shift) => {
    setEditingShiftId(shift.id);
    setSelectedPeriod(shift.period);
    setSelectedDays([...shift.daysOfWeek]);
    setShowModal(true);
  };

  const handleSave = () => {
    if (selectedDays.length === 0) {
      alert("Por favor, selecciona al menos un día.");
      return;
    }
    if (editingShiftId) {
      onUpdateShift(editingShiftId, { period: selectedPeriod, daysOfWeek: selectedDays });
    } else {
      onAddShift({ period: selectedPeriod, daysOfWeek: selectedDays });
    }
    setShowModal(false);
  };

  const toggleDay = (day: number) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const dayNamesShort = ['D', 'L', 'M', 'X', 'J', 'V', 'S'];
  const dayNamesMid = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Horario Semanal</h2>
          <p className="text-slate-500 font-medium text-base">Asignaciones de voluntarios para esta semana</p>
        </div>
        <div className="flex items-center gap-1 bg-white p-1 rounded-2xl shadow-sm border border-slate-200">
          {/* Fixed missing subWeeks member: using addWeeks(d, -1) */}
          <button 
            onClick={() => setCurrentDate(addWeeks(currentDate, -1))} 
            className="p-2.5 hover:bg-slate-50 rounded-xl transition-colors text-slate-600"
          >
            <ChevronLeft size={22} />
          </button>
          <span className="px-6 font-bold min-w-[220px] text-center text-slate-800 text-sm">
            {format(weekStart, 'd MMM', { locale: es })} – {format(weekEnd, 'd MMM, yyyy', { locale: es })}
          </span>
          <button 
            onClick={() => setCurrentDate(addWeeks(currentDate, 1))} 
            className="p-2.5 hover:bg-slate-50 rounded-xl transition-colors text-slate-600"
          >
            <ChevronRight size={22} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
        {weekDays.map((day, idx) => {
          const morningShifts = getShiftsForDay(day, 'MORNING');
          const afternoonShifts = getShiftsForDay(day, 'AFTERNOON');
          const isTodayDate = isToday(day);

          return (
            <div 
              key={idx} 
              className={`flex flex-col rounded-[2rem] border transition-all ${
                isTodayDate 
                  ? 'bg-indigo-50/30 border-indigo-200 shadow-lg shadow-indigo-100/50 ring-2 ring-indigo-500/20' 
                  : 'bg-white border-slate-200 shadow-sm'
              }`}
            >
              <div className={`p-4 text-center border-b ${isTodayDate ? 'border-indigo-100' : 'border-slate-100'}`}>
                <p className={`text-[11px] font-black uppercase tracking-[0.2em] mb-1 ${isTodayDate ? 'text-indigo-600' : 'text-slate-400'}`}>
                  {format(day, 'EEE', { locale: es })}
                </p>
                <p className={`text-2xl font-black ${isTodayDate ? 'text-indigo-700' : 'text-slate-800'}`}>
                  {format(day, 'd')}
                </p>
              </div>

              <div className="flex-1 p-3 space-y-4 min-h-[220px]">
                <div className="space-y-2">
                  <div className="flex items-center gap-1.5 px-1">
                    <Sun size={14} className="text-blue-500" />
                    <span className="text-[10px] font-black uppercase tracking-wider text-blue-600/60">Mañana</span>
                  </div>
                  <div className="space-y-1.5">
                    {morningShifts.length === 0 ? (
                      <div className="py-2 text-center text-[9px] font-bold text-slate-300 italic">Vacío</div>
                    ) : (
                      morningShifts.map(s => {
                        const vol = volunteers.find(v => v.id === s.volunteerId);
                        return (
                          <div key={s.id} className="bg-blue-50/50 border border-blue-100 p-2.5 rounded-xl flex items-center gap-2">
                            <img src={vol?.photoUrl} className="w-6 h-6 rounded-full object-cover" alt="" />
                            <span className="text-[11px] font-bold text-blue-700 truncate">{vol?.name}</span>
                          </div>
                        );
                      })
                    )}
                  </div>
                </div>

                <div className="space-y-2">
                  <div className="flex items-center gap-1.5 px-1">
                    <Moon size={14} className="text-amber-500" />
                    <span className="text-[10px] font-black uppercase tracking-wider text-amber-600/60">Tarde</span>
                  </div>
                  <div className="space-y-1.5">
                    {afternoonShifts.length === 0 ? (
                      <div className="py-2 text-center text-[9px] font-bold text-slate-300 italic">Vacío</div>
                    ) : (
                      afternoonShifts.map(s => {
                        const vol = volunteers.find(v => v.id === s.volunteerId);
                        return (
                          <div key={s.id} className="bg-amber-50/50 border border-amber-100 p-2.5 rounded-xl flex items-center gap-2">
                            <img src={vol?.photoUrl} className="w-6 h-6 rounded-full object-cover" alt="" />
                            <span className="text-[11px] font-bold text-amber-700 truncate">{vol?.name}</span>
                          </div>
                        );
                      })
                    )}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-2xl font-bold text-slate-900">Mis Compromisos Recurrentes</h3>
              <p className="text-base text-slate-500 font-medium">Gestiona tu disponibilidad semanal</p>
            </div>
            <button 
              onClick={handleOpenAdd} 
              className="group flex items-center gap-2 px-6 py-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-200 transition-all active:scale-95 font-bold text-sm"
            >
              <Plus size={22} className="group-hover:rotate-90 transition-transform" /> 
              Actualizar Mi Horario
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 gap-4">
            {shifts.filter(s => s.volunteerId === currentUser.id).length === 0 ? (
              <div className="col-span-full p-16 text-center border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white">
                <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 mx-auto mb-4">
                  <CalendarDays size={36} />
                </div>
                <h4 className="font-bold text-slate-800 mb-1 text-lg">Sin horario definido</h4>
                <p className="text-slate-400 text-sm max-w-xs mx-auto font-medium">Añade un bloque recurrente por la mañana o tarde para ayudar a la comunidad.</p>
              </div>
            ) : (
              shifts.filter(s => s.volunteerId === currentUser.id).map(shift => (
                <div key={shift.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between hover:shadow-md transition-shadow">
                  <div className="flex items-center gap-5">
                    <div className={`p-4 rounded-2xl ${
                      shift.period === 'MORNING' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'
                    }`}>
                      <Clock size={28} />
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-xl">
                        {shift.period === 'MORNING' ? 'Turno de Mañana' : 'Turno de Tarde'}
                      </h4>
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {shift.daysOfWeek.sort().map(d => (
                          <span key={d} className="text-[10px] font-black uppercase tracking-wider text-slate-400 bg-slate-50 px-2.5 py-1 rounded-md">
                            {dayNamesMid[d]}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <button onClick={() => handleOpenEdit(shift)} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"><Edit2 size={20} /></button>
                    <button onClick={() => onRemoveShift(shift.id)} className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={20} /></button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white relative overflow-hidden group shadow-2xl shadow-slate-900/20">
            <div className="absolute top-0 right-0 p-8 text-white/5 group-hover:text-white/10 transition-colors">
              <Calendar size={140} />
            </div>
            <div className="relative z-10">
              <h3 className="text-2xl font-bold mb-1">Resumen Semanal</h3>
              <p className="text-slate-400 text-base font-medium mb-8">Capacidad para esta semana</p>
              <div className="flex items-baseline gap-4">
                <span className="text-7xl font-black text-indigo-400 tracking-tighter">
                  {shifts.reduce((acc, s) => acc + s.daysOfWeek.length, 0)}
                </span>
                <div className="space-y-0.5">
                  <p className="text-[11px] font-black uppercase tracking-widest text-slate-500">Total</p>
                  <p className="text-[11px] font-black uppercase tracking-widest text-slate-500">Turnos</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl animate-in zoom-in slide-in-from-bottom-8 duration-500">
            <h3 className="text-3xl font-black text-slate-900 mb-2">{editingShiftId ? 'Editar Horario' : 'Nuevo Horario'}</h3>
            <p className="text-slate-500 font-medium mb-10 text-base">Elige tus bloques recurrentes de disponibilidad.</p>

            <div className="space-y-8">
              <div>
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 block">Días de la Semana</label>
                <div className="grid grid-cols-7 gap-2">
                  {[0,1,2,3,4,5,6].map(d => (
                    <button
                      key={d}
                      onClick={() => toggleDay(d)}
                      className={`h-11 rounded-2xl font-black text-xs transition-all border-2 ${
                        selectedDays.includes(d) 
                          ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100' 
                          : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'
                      }`}
                    >
                      {dayNamesShort[d]}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 block">Período Preferido</label>
                <div className="grid grid-cols-2 gap-4">
                  <button 
                    onClick={() => setSelectedPeriod('MORNING')} 
                    className={`flex flex-col items-center gap-4 p-6 rounded-3xl border-2 transition-all group ${
                      selectedPeriod === 'MORNING' 
                        ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700 shadow-lg shadow-indigo-50' 
                        : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                    }`}
                  >
                    <div className={`p-3 rounded-2xl transition-colors ${selectedPeriod === 'MORNING' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-white'}`}>
                      <Sun size={24} />
                    </div>
                    <span className="font-black text-sm uppercase tracking-widest">Mañana</span>
                  </button>
                  <button 
                    onClick={() => setSelectedPeriod('AFTERNOON')} 
                    className={`flex flex-col items-center gap-4 p-6 rounded-3xl border-2 transition-all group ${
                      selectedPeriod === 'AFTERNOON' 
                        ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700 shadow-lg shadow-indigo-50' 
                        : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                    }`}
                  >
