            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" placeholder="Buscar equipo..." className="pl-12 pr-5 py-3.5 bg-white border-2 border-slate-200 rounded-2xl outline-none text-base w-full md:w-80 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
