const ImageCapture: React.FC<{
  currentImage: string;
  onImageChange: (dataUrl: string) => void;
  label?: string;
  disabled?: boolean;
}> = ({ currentImage, onImageChange, label = "Foto de Perfil", disabled = false }) => {
  const libraryInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const resizeImage = (base64Str: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_SIZE = 400;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const resized = await resizeImage(reader.result as string);
        onImageChange(resized);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-4">
      {label && <label className="text-xs font-black text-slate-400 uppercase tracking-widest block">{label}</label>}
      <div className="flex items-center gap-5">
        <div className="relative w-24 h-24 shrink-0">
          {isProcessing ? (
            <div className="w-full h-full rounded-2xl bg-slate-100 flex items-center justify-center border border-indigo-100">
               <Loader2 className="animate-spin text-indigo-500" size={24} />
            </div>
          ) : (
            <img 
              src={currentImage || 'https://via.placeholder.com/150?text=Sin+Foto'} 
              className="w-full h-full rounded-2xl object-cover ring-4 ring-indigo-50 shadow-md"
              alt="Previsualización"
            />
          )}
        </div>
        {!disabled && (
          <div className="flex flex-col gap-2.5">
            <button 
              type="button" 
              onClick={() => cameraInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-xs uppercase tracking-wider hover:bg-indigo-700 transition-all active:scale-95 shadow-md"
            >
              <Camera size={16} /> Tomar Foto
            </button>
            <button 
              type="button" 
              onClick={() => libraryInputRef.current?.click()} 
              className="flex items-center justify-center gap-2 px-5 py-2.5 bg-white border-2 border-slate-200 text-slate-600 rounded-xl font-bold text-xs uppercase tracking-wider hover:border-indigo-200 hover:text-indigo-600 transition-all active:scale-95"
            >
              <ImageIcon size={16} /> Galería
            </button>
          </div>
        )}
      </div>
      <input type="file" ref={libraryInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
      <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="user" onChange={handleFileChange} />
    </div>
  );
};

const AttendanceHistory: React.FC<{
  volunteerId: string;
  attendances: AttendanceRecord[];
}> = ({ volunteerId, attendances }) => {
  const [viewingMonth, setViewingMonth] = useState(new Date());

  const userAttendances = useMemo(() => 
    attendances.filter(a => a.volunteerId === volunteerId),
    [attendances, volunteerId]
  );

  const monthRecords = useMemo(() => 
    userAttendances.filter(a => {
      const d = new Date(a.date);
      return isSameMonth(d, viewingMonth) && isSameYear(d, viewingMonth);
    }).sort((a, b) => b.date.localeCompare(a.date)),
    [userAttendances, viewingMonth]
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-indigo-600 p-5 rounded-2xl text-white shadow-lg flex items-center justify-between">
          <div>
            <p className="text-3xl font-black">{userAttendances.length}</p>
            <p className="text-[11px] font-black uppercase tracking-wider opacity-80">Total Histórico</p>
          </div>
          <TrendingUp size={24} className="opacity-40" />
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between">
          <div>
            <p className="text-3xl font-black text-slate-800">{monthRecords.length}</p>
            <p className="text-[11px] font-black uppercase tracking-wider text-slate-400">Este Mes</p>
          </div>
          <History size={24} className="text-indigo-600 opacity-40" />
        </div>
      </div>

      <div className="bg-white p-6 rounded-3xl border border-slate-100 space-y-4">
        <div className="flex items-center justify-between px-1">
          <button onClick={() => setViewingMonth(addMonths(viewingMonth, -1))} className="p-2 text-slate-400 hover:text-indigo-600">
            <ChevronLeft size={24} />
          </button>
          <p className="font-black text-slate-800 text-sm uppercase tracking-widest">{format(viewingMonth, 'MMMM yyyy', { locale: es })}</p>
          <button onClick={() => setViewingMonth(addMonths(viewingMonth, 1))} className="p-2 text-slate-400 hover:text-indigo-600">
            <ChevronRight size={24} />
          </button>
        </div>

        <div className="space-y-3 max-h-56 overflow-y-auto custom-scrollbar pr-2">
          {monthRecords.length === 0 ? (
            <div className="py-8 text-center text-slate-300 font-bold text-sm italic">Sin registros este mes</div>
          ) : (
            monthRecords.map(record => (
              <div key={record.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-indigo-600 shadow-sm">
                    <ClipboardCheck size={18} />
                  </div>
                  <div>
                    <p className="font-black text-slate-800 text-base">{format(new Date(record.date), 'EEEE, d', { locale: es })}</p>
                    <p className="text-xs font-black uppercase tracking-tight text-slate-400">{format(new Date(record.timestamp), 'hh:mm a')}</p>
                  </div>
                </div>
                <div className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-[10px] font-black uppercase tracking-tight">Presente</div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [volunteers, setVolunteers] = useState<VolunteerProfile[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [attendances, setAttendances] = useState<AttendanceRecord[]>([]);
  const [currentUser, setCurrentUser] = useState<VolunteerProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [dbError, setDbError] = useState(false);
  const [isAuthError, setIsAuthError] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");

  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [showInactiveInCommunity, setShowInactiveInCommunity] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isAutoCheckInPending, setIsAutoCheckInPending] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', preferredPeriod: 'MORNING' as ShiftPeriod, selectedDays: [] as number[], volunteerType: VolunteerType.VTP, area: ''
  });

  const [profileEditForm, setProfileEditForm] = useState<Partial<VolunteerProfile>>({});

  useEffect(() => {
    if (!db) {
      setDbError(true);
      setIsLoading(false);
      setErrorMessage("El servicio de base de datos no se cargó correctamente. Revisa la consola para más detalles.");
      return;
    }

    const timeout = setTimeout(() => {
      if (isLoading) {
        setDbError(true);
        setIsLoading(false);
        setErrorMessage("Tiempo de espera agotado al conectar con Firestore. Verifica tu conexión y las reglas de seguridad.");
      }
    }, 6000);

    try {
      const unsubVolunteers = onSnapshot(collection(db, "volunteers"), (snapshot) => {
        const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as VolunteerProfile));
        setVolunteers(data);
        if (currentUser) {
          const updatedSelf = data.find(v => v.id === currentUser.id);
          if (updatedSelf) setCurrentUser(updatedSelf);
        }
        setIsLoading(false);
        setDbError(false);
        setIsAuthError(false);
        clearTimeout(timeout);
      }, (error) => {
        console.error("Firestore Auth/Config Error:", error);
        setDbError(true);
        setIsLoading(false);
        if (error.code === 'permission-denied') {
          setIsAuthError(true);
          setErrorMessage("Permiso denegado. Debes configurar las Reglas de Firestore en la consola de Firebase.");
        } else {
          setErrorMessage(`Error de Firestore: ${error.message}`);
        }
        clearTimeout(timeout);
      });

      const unsubShifts = onSnapshot(collection(db, "shifts"), (snapshot) => {
        setShifts(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Shift)));
      });

      const unsubAttendances = onSnapshot(collection(db, "attendances"), (snapshot) => {
        setAttendances(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as AttendanceRecord)));
      });

      return () => {
        unsubVolunteers();
        unsubShifts();
        unsubAttendances();
        clearTimeout(timeout);
      };
    } catch (e: any) {
      setDbError(true);
      setIsLoading(false);
      setErrorMessage(e.message);
      clearTimeout(timeout);
    }
  }, [currentUser?.id]);

  useEffect(() => {
    const checkHash = () => {
      if (window.location.hash === '#check-in') setIsAutoCheckInPending(true);
    };
    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  useEffect(() => {
    if (currentUser && isAutoCheckInPending && currentUser.status === UserStatus.APPROVED) {
      const today = format(new Date(), 'yyyy-MM-dd');
      handleAttendanceCheckIn(today);
      setIsAutoCheckInPending(false);
      window.history.replaceState(null, '', window.location.pathname + window.location.search);
      setActiveTab('attendance');
    }
  }, [currentUser, isAutoCheckInPending]);

  const handleLogout = () => {
    setCurrentUser(null);
    setLoginForm({ email: '', phone: '' });
    setLoginError(null);
    setActiveTab('calendar');
    setIsRegistering(false);
    setIsAutoCheckInPending(false);
  };

  const handleLogin = () => {
    const { email, phone } = loginForm;
    setLoginError(null);

    if (!email || !phone) {
      setLoginError("Por favor, ingresa tus credenciales.");
      return;
    }

    const user = volunteers.find(v => 
      v.email.toLowerCase() === email.trim().toLowerCase() && 
      v.phone.trim() === phone.trim()
    );

    if (user) {
      setCurrentUser(user);
      if (!isAutoCheckInPending) {
        setActiveTab(user.role === UserRole.ADMIN ? 'admin' : 'calendar');
      }
    } else {
      setLoginError("Correo o teléfono inválidos.");
    }
  };

  const handleRegister = async () => {
    if (!db) return;
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return alert("Por favor, completa todos los campos requeridos.");

    const volunteerId = Math.random().toString(36).substring(2, 11);
    const newVol: VolunteerProfile = { 
      id: volunteerId, 
      name: regForm.name, 
      email: regForm.email, 
      phone: regForm.phone, 
      birthday: regForm.birthday, 
      photoUrl: regForm.photoUrl, 
      status: UserStatus.PENDING, 
      role: UserRole.VOLUNTEER, 
      volunteerType: regForm.volunteerType,
      area: regForm.volunteerType === VolunteerType.BASE ? regForm.area : undefined,
      joinedAt: new Date().toISOString() 
    };

    try {
      await setDoc(doc(db, "volunteers", volunteerId), newVol);
      const shiftId = Math.random().toString(36).substring(2, 11);
      await setDoc(doc(db, "shifts", shiftId), { 
        volunteerId: volunteerId, 
        daysOfWeek: regForm.selectedDays, 
        period: regForm.preferredPeriod 
      });
      setCurrentUser(newVol);
      setActiveTab('profile');
      setIsRegistering(false);
    } catch (e: any) {
      alert("No se pudo completar el registro. Verifica que Firestore tenga las reglas de escritura habilitadas.");
    }
  };

  const handleAttendanceCheckIn = async (date: string) => {
    if (!currentUser || !db) return;
    if (attendances.some(a => a.volunteerId === currentUser.id && a.date === date)) return;

    const newRecord = {
      volunteerId: currentUser.id,
      date,
      timestamp: new Date().toISOString()
    };

    try {
      await addDoc(collection(db, "attendances"), newRecord);
    } catch (e: any) {
      console.error("Error check-in", e);
    }
  };

  const updateVolunteerStatus = async (id: string, status: UserStatus) => {
    if (!db) return;
    try {
      await updateDoc(doc(db, "volunteers", id), { status });
    } catch (e: any) {
      console.error(e);
    }
  };

  const handleUpdateVolunteerProfile = async (id: string, updates: Partial<VolunteerProfile>) => {
    if (!db) return;
    try {
      await updateDoc(doc(db, "volunteers", id), updates);
    } catch (e: any) {
      console.error(e);
    }
  };

  const handleSaveProfile = async () => {
    if (!currentUser) return;
    await handleUpdateVolunteerProfile(currentUser.id, profileEditForm);
    setIsEditingProfile(false);
  };

  const startEditingProfile = () => {
    if (!currentUser) return;
    setProfileEditForm({ ...currentUser });
    setIsEditingProfile(true);
  };

  const handleUpdateShift = async (id: string, updated: Partial<Shift>) => {
    if (!db) return;
    try {
      await updateDoc(doc(db, "shifts", id), updated);
    } catch (e: any) {
      console.error(e);
    }
  };

  const handleAddShift = async (shift: Omit<Shift, 'id'>) => {
    if (!db) return;
    try {
      await addDoc(collection(db, "shifts"), shift);
    } catch (e: any) {
      console.error(e);
    }
  };

  const handleRemoveShift = async (id: string) => {
    if (!db) return;
    try {
      await deleteDoc(doc(db, "shifts", id));
    } catch (e: any) {
      console.error(e);
    }
  };

  const activeShifts = useMemo(() => {
    const activeVolunteerIds = new Set(volunteers.filter(v => v.status === UserStatus.APPROVED).map(v => v.id));
    return shifts.filter(s => activeVolunteerIds.has(s.volunteerId));
  }, [volunteers, shifts]);

  const filteredVolunteers = useMemo(() => {
    return volunteers.filter(v => {
      const searchMatch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!searchMatch) return false;
      return showInactiveInCommunity || v.status === UserStatus.APPROVED;
    });
  }, [volunteers, searchTerm, showInactiveInCommunity]);

  const getStatusLabel = (status: UserStatus) => {
    switch (status) {
      case UserStatus.APPROVED: return 'Activo';
      case UserStatus.REJECTED: return 'Inactivo';
      case UserStatus.PENDING: return 'Pendiente';
      default: return status;
    }
  };

  if (dbError) return <FirebaseConfigError message={errorMessage} isAuthError={isAuthError} />;

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="animate-spin text-indigo-600" size={48} />
          <p className="font-black text-slate-400 uppercase tracking-widest text-xs">Conectando con la comunidad...</p>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4 font-inter">
        <div className={`w-full ${isRegistering ? 'max-w-xl' : 'max-w-sm'} bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-100`}>
          <div className="bg-indigo-600 p-10 text-center relative overflow-hidden">
            <h1 className="text-3xl font-black text-white tracking-tight">VoluApp</h1>
            <p className="text-indigo-100 text-xs uppercase font-bold tracking-[0.2em] mt-1">Gestión de Voluntarios</p>
          </div>
          {!isRegistering ? (
            <div className="p-10 space-y-8">
              {loginError && (
                <div className="bg-red-50 p-4 rounded-xl flex items-center gap-3">
                  <AlertCircle className="text-red-500" size={20} />
                  <p className="text-sm font-bold text-red-600">{loginError}</p>
                </div>
              )}
              <div className="space-y-4">
                <input placeholder="Correo Electrónico" type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none text-base font-medium focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
                <input placeholder="Teléfono Móvil" type="tel" className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-200 rounded-xl outline-none text-base font-medium focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" value={loginForm.phone} onChange={e => setLoginForm({...loginForm, phone: e.target.value})} onKeyDown={e => e.key === 'Enter' && handleLogin()} />
              </div>
              <button onClick={handleLogin} className="w-full bg-indigo-600 text-white py-5 rounded-xl font-bold text-lg shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Entrar</button>
              <button onClick={() => setIsRegistering(true)} className="w-full py-2 text-indigo-600 font-bold text-base hover:bg-indigo-50 rounded-lg transition-colors">Solicitar Registro</button>
            </div>
          ) : (
            <div className="p-10 space-y-10 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <h2 className="text-3xl font-black text-slate-800 tracking-tight">Registro</h2>
              <div className="space-y-8">
                <ImageCapture currentImage={regForm.photoUrl} onImageChange={(url) => setRegForm({...regForm, photoUrl: url})} label="Foto de Perfil" />
                <div className="grid grid-cols-1 gap-5">
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-500">Nombre Completo</label>
                    <input placeholder="Nombre y apellidos" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.name} onChange={e => setRegForm({...regForm, name: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-slate-500">Correo Electrónico</label>
                    <input placeholder="ejemplo@correo.com" type="email" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.email} onChange={e => setRegForm({...regForm, email: e.target.value})} />
                  </div>
                  <div className="grid grid-cols-2 gap-5">
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-slate-500">Teléfono</label>
                      <input placeholder="555-0101" type="tel" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.phone} onChange={e => setRegForm({...regForm, phone: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-sm font-bold text-slate-500">Cumpleaños</label>
                      <input type="date" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.birthday} onChange={e => setRegForm({...regForm, birthday: e.target.value})} />
                    </div>
                  </div>
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block">Tipo de Voluntario</label>
                  <div className="grid grid-cols-3 gap-3">
                    {ROLE_ORDER.map(type => (
                      <button key={type} onClick={() => setRegForm({...regForm, volunteerType: type})} className={`p-4 rounded-xl border-2 font-black text-xs transition-all ${regForm.volunteerType === type ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'}`}>{type}</button>
                    ))}
                  </div>
                  {regForm.volunteerType === VolunteerType.BASE && (
                    <div className="animate-in slide-in-from-top-3">
                       <label className="text-xs font-bold text-slate-500 mb-2 block">Zona / Área</label>
                       <input placeholder="Especifica tu territorio" className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base outline-none focus:border-indigo-500 transition-all" value={regForm.area} onChange={e => setRegForm({...regForm, area: e.target.value})} />
                    </div>
                  )}
                </div>
              </div>
              <div className="flex gap-4 pt-6 sticky bottom-0 bg-white py-6 border-t">
                <button onClick={() => setIsRegistering(false)} className="flex-1 py-5 text-slate-400 font-bold text-base hover:text-slate-600 transition-colors">Cancelar</button>
                <button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-5 rounded-xl font-bold text-base shadow-2xl hover:bg-indigo-700 transition-all">Enviar</button>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={currentUser.role} userName={currentUser.name}>
      {activeTab === 'calendar' && (
        <ShiftCalendar shifts={activeShifts} volunteers={volunteers} currentUser={currentUser} onAddShift={(data) => handleAddShift({ ...data, volunteerId: currentUser.id })} onUpdateShift={handleUpdateShift} onRemoveShift={handleRemoveShift} />
      )}
      {activeTab === 'attendance' && (
        <AttendanceView currentUser={currentUser} volunteers={volunteers} attendances={attendances} onCheckIn={handleAttendanceCheckIn} />
      )}
      {activeTab === 'volunteers' && (
        <div className="space-y-10">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
            <h2 className="text-3xl font-black text-slate-800 tracking-tight">Comunidad</h2>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" placeholder="Buscar..." className="pl-12 pr-5 py-3.5 bg-white border-2 border-slate-200 rounded-2xl outline-none text-base w-full md:w-80 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(volunteer => (
              <div key={volunteer.id} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm relative hover:shadow-xl transition-all flex items-center gap-5">
                <img src={volunteer.photoUrl} className="w-16 h-16 rounded-2xl object-cover ring-4 ring-indigo-50/50 shadow-md" />
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-slate-800 text-lg truncate flex items-center gap-2">
                    {volunteer.name}
                    {volunteer.role === UserRole.ADMIN && <ShieldCheck size={16} className="text-indigo-600" />}
                  </h3>
                  <div className="flex items-center gap-2 mt-1.5">
                    <span className="text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded bg-indigo-50 text-indigo-600">{volunteer.volunteerType}</span>
                    <span className={`text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded ${volunteer.status === UserStatus.APPROVED ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>
                      {getStatusLabel(volunteer.status)}
                    </span>
                  </div>
                </div>
                {isAdmin && (<button onClick={() => setEditingVolunteer(volunteer)} className="p-2.5 text-slate-300 hover:text-indigo-600 transition-all hover:bg-indigo-50 rounded-2xl"><Edit2 size={18} /></button>)}
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-3xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-2xl space-y-10">
            <div className="flex flex-col md:flex-row items-center md:items-end justify-between gap-8 border-b pb-10">
              <div className="flex flex-col md:flex-row items-center gap-8">
                <div className="relative">
                  {isEditingProfile ? (
                    <ImageCapture currentImage={profileEditForm.photoUrl || currentUser.photoUrl} onImageChange={(url) => setProfileEditForm(prev => ({ ...prev, photoUrl: url }))} label="" />
                  ) : (
                    <img src={currentUser.photoUrl} className="w-28 h-28 rounded-3xl object-cover ring-8 ring-indigo-50 shadow-xl" />
                  )}
                </div>
                <div className="text-center md:text-left">
                  <h2 className="text-4xl font-black text-slate-900 tracking-tight">{currentUser.name}</h2>
                  <div className="flex items-center justify-center md:justify-start gap-3 mt-3">
                    <span className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.25em] bg-indigo-50 px-4 py-1.5 rounded-full">{isAdmin ? 'Administrador' : 'Voluntario'}</span>
                  </div>
                </div>
              </div>
              <button onClick={isEditingProfile ? handleSaveProfile : startEditingProfile} className={`flex items-center gap-3 px-8 py-5 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl transition-all active:scale-95 ${isEditingProfile ? 'bg-green-600 text-white shadow-green-100' : 'bg-indigo-600 text-white shadow-indigo-100'}`}>
                {isEditingProfile ? <><Save size={20} /> Guardar</> : <><Edit2 size={20} /> Perfil</>}
