const ROLE_ORDER = [VolunteerType.VTP, VolunteerType.VTC, VolunteerType.BASE];

// Manual implementation of missing date-fns helpers
const startOfMonthManual = (date: Date) => {
  const d = new Date(date);
  d.setDate(1);
  d.setHours(0, 0, 0, 0);
  return d;
};

const startOfWeekManual = (date: Date, options?: { weekStartsOn?: number }) => {
  const d = new Date(date);
  const day = d.getDay();
  const weekStartsOn = options?.weekStartsOn ?? 0;
  const diff = (day < weekStartsOn ? 7 : 0) + day - weekStartsOn;
  d.setDate(d.getDate() - diff);
  d.setHours(0, 0, 0, 0);
  return d;
};

const setMonthManual = (date: Date, month: number) => {
  const d = new Date(date);
  d.setMonth(month);
  return d;
};

const setYearManual = (date: Date, year: number) => {
  const d = new Date(date);
  d.setFullYear(year);
  return d;
};

// Helper to format stored date string (YYYY-MM-DD) to Display format (dd/mm/yyyy)
const formatBirthday = (dateStr: string) => {
  if (!dateStr) return 'No especificado';
  const date = new Date(dateStr);
  return isValid(date) ? format(date, 'dd/MM/yyyy') : dateStr;
};

/**
 * Custom Date Picker Component to ensure dd/mm/yyyy format and provide a clean UI
 */
const CustomDatePicker: React.FC<{
  value: string;
  onChange: (value: string) => void;
  label?: string;
}> = ({ value, onChange, label }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [viewDate, setViewDate] = useState(value ? new Date(value) : new Date());
  const containerRef = useRef<HTMLDivElement>(null);

  // Close on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const selectedDate = value ? new Date(value) : null;

  const days = useMemo(() => {
    // Using manual helper startOfWeekManual and startOfMonthManual
    const start = startOfWeekManual(startOfMonthManual(viewDate), { weekStartsOn: 1 });
    const end = endOfWeek(endOfMonth(viewDate), { weekStartsOn: 1 });
    return eachDayOfInterval({ start, end });
  }, [viewDate]);

  const handleSelect = (date: Date) => {
    // We store as YYYY-MM-DD for consistency
    onChange(format(date, 'yyyy-MM-dd'));
    setIsOpen(false);
  };

  const years = Array.from({ length: 100 }, (_, i) => getYear(new Date()) - i);
  const months = [
    "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
    "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
  ];

  return (
    <div className="relative w-full" ref={containerRef}>
      {label && <label className="text-sm font-bold text-slate-500 mb-2 block">{label}</label>}
      <div 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full p-4 bg-slate-50 border-2 border-slate-200 rounded-xl text-base font-bold outline-none focus-within:border-indigo-500 transition-all cursor-pointer flex items-center justify-between"
      >
        <span className={value ? 'text-slate-900' : 'text-slate-400 font-medium'}>
          {value ? formatBirthday(value) : 'dd/mm/yyyy'}
        </span>
        <CalendarIcon size={18} className="text-slate-400" />
      </div>

      {isOpen && (
        <div className="absolute top-full left-0 mt-2 z-[110] w-72 bg-white rounded-3xl shadow-2xl border border-slate-100 p-5 animate-in fade-in zoom-in duration-200 origin-top">
          <div className="flex flex-col gap-4">
            <div className="flex items-center justify-between">
              <select 
                value={getMonth(viewDate)} 
                // Using manual helper setMonthManual
                onChange={(e) => setViewDate(setMonthManual(viewDate, parseInt(e.target.value)))}
                className="bg-transparent font-black text-xs uppercase tracking-wider outline-none text-indigo-600"
              >
                {months.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
              <select 
                value={getYear(viewDate)} 
                // Using manual helper setYearManual
                onChange={(e) => setViewDate(setYearManual(viewDate, parseInt(e.target.value)))}
                className="bg-transparent font-black text-xs uppercase tracking-wider outline-none text-indigo-600"
              >
                {years.map(y => <option key={y} value={y}>{y}</option>)}
              </select>
            </div>

            <div className="grid grid-cols-7 gap-1">
              {['L', 'M', 'X', 'J', 'V', 'S', 'D'].map(d => (
                <div key={d} className="text-center text-[10px] font-black text-slate-300 py-1">{d}</div>
              ))}
              {days.map((day, i) => {
                const isSelected = selectedDate && isSameDay(day, selectedDate);
                const isCurrentMonth = isSameMonth(day, viewDate);
                return (
                  <button
                    key={i}
                    onClick={() => handleSelect(day)}
                    className={`h-8 w-8 rounded-lg text-[11px] font-bold transition-all flex items-center justify-center ${
                      isSelected 
                        ? 'bg-indigo-600 text-white shadow-md' 
                        : isCurrentMonth 
                          ? 'text-slate-700 hover:bg-slate-50' 
                          : 'text-slate-200'
                    }`}
                  >
                    {format(day, 'd')}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

