      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-6">
          <ImageCapture currentImage={formData.photoUrl || ''} onImageChange={(url) => onChange({ photoUrl: url })} label="Foto de Perfil" />
          <div className="space-y-2">
            <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block">Nombre Completo</label>
            <input className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-indigo-500 transition-all" value={formData.name || ''} onChange={e => onChange({ name: e.target.value })} />
          </div>
          <div className="space-y-2">
            <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block">Correo Electrónico</label>
            <input className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-indigo-500 transition-all" value={formData.email || ''} onChange={e => onChange({ email: e.target.value })} />
          </div>
          <div className="space-y-2">
            <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block flex items-center gap-2"><Instagram size={14} /> Usuario Instagram</label>
            <input placeholder="@usuario" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-indigo-500 transition-all" value={formData.instagram || ''} onChange={e => onChange({ instagram: e.target.value })} />
          </div>
        </div>
        <div className="space-y-6">
          <div className="space-y-2">
            <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block">Teléfono</label>
            <input className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-indigo-500 transition-all" value={formData.phone || ''} onChange={e => onChange({ phone: e.target.value })} />
          </div>
          <CustomDatePicker label="Cumpleaños" value={formData.birthday || ''} onChange={val => onChange({ birthday: val })} />

          <div className="space-y-2">
            <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block flex items-center gap-2"><Send size={14} /> Usuario Telegram</label>
            <input placeholder="@usuario" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-indigo-500 transition-all" value={formData.telegram || ''} onChange={e => onChange({ telegram: e.target.value })} />
          </div>

          {isAdminEditing && (
            <div className="grid grid-cols-1 gap-6 pt-4">
              <div className="space-y-2">
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block flex items-center gap-2"><ShieldCheck size={14} /> Rol del Sistema</label>
                <div className="grid grid-cols-2 gap-3">
                  {[UserRole.VOLUNTEER, UserRole.ADMIN].map(r => (
                    <button key={r} onClick={() => onChange({ role: r })} className={`p-4 rounded-xl border-2 font-black text-[10px] uppercase tracking-widest transition-all ${formData.role === r ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{r}</button>
                  ))}
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block flex items-center gap-2"><Activity size={14} /> Estado de Cuenta</label>
                <div className="grid grid-cols-3 gap-2">
                  {[UserStatus.APPROVED, UserStatus.PENDING, UserStatus.REJECTED].map(s => (
                    <button key={s} onClick={() => onChange({ status: s })} className={`p-4 rounded-xl border-2 font-black text-[10px] uppercase transition-all ${formData.status === s ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>
                      {s === UserStatus.APPROVED ? 'Activo' : s === UserStatus.PENDING ? 'Pend.' : 'Inact.'}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="pt-8 border-t border-slate-100 space-y-6">
        <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest flex items-center gap-2"><Briefcase size={18} className="text-indigo-600" /> Clasificación y Disponibilidad</h4>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-4">
            <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block">Tipo de Voluntario</label>
            <div className="grid grid-cols-3 gap-2">
              {ROLE_ORDER.map(t => (
                <button key={t} onClick={() => onChange({ volunteerType: t })} className={`p-4 rounded-xl border-2 font-black text-[10px] uppercase transition-all ${formData.volunteerType === t ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{t}</button>
              ))}
            </div>
            <input placeholder="Área" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-indigo-500 transition-all mt-4" value={formData.area || ''} onChange={e => onChange({ area: e.target.value })} />
          </div>
          <div className="space-y-8">
            <div className="space-y-4">
               <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Sun size={14} className="text-blue-500" /> Turno de Mañana</label>
               <div className="grid grid-cols-7 gap-1.5">
                 {dayOrder.map(d => (
                   <button key={d} onClick={() => {
                     const days = formData.morningDays?.includes(d) ? formData.morningDays.filter(x => x !== d) : [...(formData.morningDays || []), d];
                     onChange({ morningDays: days });
                   }} className={`h-9 rounded-xl font-black text-[10px] transition-all border-2 ${formData.morningDays?.includes(d) ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{dayLabels[d]}</button>
                 ))}
               </div>
            </div>
            <div className="space-y-4">
               <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Moon size={14} className="text-amber-500" /> Turno de Tarde</label>
               <div className="grid grid-cols-7 gap-1.5">
                 {dayOrder.map(d => (
                   <button key={d} onClick={() => {
                     const days = formData.afternoonDays?.includes(d) ? formData.afternoonDays.filter(x => x !== d) : [...(formData.afternoonDays || []), d];
                     onChange({ afternoonDays: days });
                   }} className={`h-9 rounded-xl font-black text-[10px] transition-all border-2 ${formData.afternoonDays?.includes(d) ? 'bg-amber-600 border-amber-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{dayLabels[d]}</button>
                 ))}
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [volunteers, setVolunteers] = useState<VolunteerProfile[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [attendances, setAttendances] = useState<AttendanceRecord[]>([]);
  const [currentUser, setCurrentUser] = useState<VolunteerProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [dbError, setDbError] = useState(false);
  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [viewingVolunteer, setViewingVolunteer] = useState<VolunteerProfile | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [registrationError, setRegistrationError] = useState<string | null>(null);

  const [communityFilter, setCommunityFilter] = useState<'ACTIVE' | 'INACTIVE' | 'ALL'>('ACTIVE');

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', morningDays: [] as number[], afternoonDays: [] as number[], volunteerType: VolunteerType.VTP, area: '', instagram: '', telegram: ''
  });

  const [editForm, setEditForm] = useState<Partial<VolunteerProfile & { morningDays: number[], afternoonDays: number[] }>>({});

  useEffect(() => {
    if (!db) { setDbError(true); setIsLoading(false); return; }
    const unsubVolunteers = onSnapshot(collection(db, "volunteers"), (snapshot) => {
      const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as VolunteerProfile));
      setVolunteers(data);
      if (currentUser) { const self = data.find(v => v.id === currentUser.id); if (self) setCurrentUser(self); }
      setIsLoading(false);
    });
    const unsubShifts = onSnapshot(collection(db, "shifts"), (snapshot) => setShifts(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Shift))));
    const unsubAttendances = onSnapshot(collection(db, "attendances"), (snapshot) => setAttendances(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as AttendanceRecord))));
    return () => { unsubVolunteers(); unsubShifts(); unsubAttendances(); };
  }, [currentUser?.id]);

  const handleLogout = () => { setCurrentUser(null); setIsRegistering(false); setLoginError(null); setActiveTab('calendar'); };

  const handleLogin = () => {
    setLoginError(null);
    const user = volunteers.find(v => v.email.toLowerCase() === loginForm.email.trim().toLowerCase() && v.phone.trim() === loginForm.phone.trim());
    if (user) { setCurrentUser(user); setActiveTab(user.role === UserRole.ADMIN ? 'admin' : (user.status === UserStatus.APPROVED ? 'calendar' : 'profile')); }
    else setLoginError("Credenciales inválidas.");
  };

  const handleRegister = async () => {
    setRegistrationError(null);
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return setRegistrationError("Completa todos los campos obligatorios.");
    if (volunteers.some(v => v.email.toLowerCase().trim() === regForm.email.toLowerCase().trim())) return setRegistrationError("Este correo ya está en uso.");
    setIsSubmitting(true);
    try {
      const id = Math.random().toString(36).substring(2, 11);
      const newVol = { id, name: regForm.name, email: regForm.email, phone: regForm.phone, birthday: regForm.birthday, photoUrl: regForm.photoUrl, status: UserStatus.PENDING, role: UserRole.VOLUNTEER, volunteerType: regForm.volunteerType, area: regForm.area, instagram: regForm.instagram, telegram: regForm.telegram, joinedAt: new Date().toISOString() };
      await setDoc(doc(db, "volunteers", id), newVol);
      if (regForm.morningDays.length > 0) await addDoc(collection(db, "shifts"), { volunteerId: id, daysOfWeek: regForm.morningDays, period: 'MORNING' });
      if (regForm.afternoonDays.length > 0) await addDoc(collection(db, "shifts"), { volunteerId: id, daysOfWeek: regForm.afternoonDays, period: 'AFTERNOON' });
      setCurrentUser(newVol as VolunteerProfile); setActiveTab('profile'); setIsRegistering(false);
    } catch (e: any) { setRegistrationError(e.message); } finally { setIsSubmitting(false); }
  };

  const startEditing = (volunteer: VolunteerProfile) => {
    const userShifts = shifts.filter(s => s.volunteerId === volunteer.id);
    const morningShift = userShifts.find(s => s.period === 'MORNING');
    const afternoonShift = userShifts.find(s => s.period === 'AFTERNOON');

    setEditForm({ 
      ...volunteer, 
      morningDays: morningShift?.daysOfWeek || [], 
      afternoonDays: afternoonShift?.daysOfWeek || [] 
    });

    if (volunteer.id === currentUser?.id) {
      setIsEditingProfile(true);
    } else {
      setEditingVolunteer(volunteer);
    }
  };

  const saveMemberChanges = async (targetId: string) => {
    if (!db || !targetId) return;
    try {
      const { morningDays, afternoonDays, ...profileData } = editForm;
      const cleanProfile: any = {};

      Object.keys(profileData).forEach(key => {
        if (profileData[key as keyof typeof profileData] !== undefined) {
          cleanProfile[key] = profileData[key as keyof typeof profileData];
        }
      });

      delete cleanProfile.id; 
      delete cleanProfile.joinedAt;

      await updateDoc(doc(db, "volunteers", targetId), cleanProfile);

      const shiftsRef = collection(db, "shifts");
      const q = query(shiftsRef, where("volunteerId", "==", targetId));
      const querySnap = await getDocs(q);

      const existingMorning = querySnap.docs.find(d => d.data().period === 'MORNING');
      const existingAfternoon = querySnap.docs.find(d => d.data().period === 'AFTERNOON');

      if (morningDays && morningDays.length > 0) {
        if (existingMorning) await updateDoc(doc(db, "shifts", existingMorning.id), { daysOfWeek: morningDays });
        else await addDoc(shiftsRef, { volunteerId: targetId, daysOfWeek: morningDays, period: 'MORNING' });
      } else if (existingMorning) {
        await deleteDoc(doc(db, "shifts", existingMorning.id));
      }

      if (afternoonDays && afternoonDays.length > 0) {
        if (existingAfternoon) await updateDoc(doc(db, "shifts", existingAfternoon.id), { daysOfWeek: afternoonDays });
        else await addDoc(shiftsRef, { volunteerId: targetId, daysOfWeek: afternoonDays, period: 'AFTERNOON' });
      } else if (existingAfternoon) {
        await deleteDoc(doc(db, "shifts", existingAfternoon.id));
      }

      setIsEditingProfile(false); 
      setEditingVolunteer(null);
    } catch (e) { 
      console.error("Error al guardar cambios:", e); 
    }
  };

  const handleAttendanceCheckIn = async (date: string) => {
    if (!currentUser || attendances.some(a => a.volunteerId === currentUser.id && a.date === date)) return;
    await addDoc(collection(db, "attendances"), { volunteerId: currentUser.id, date, timestamp: new Date().toISOString() });
  };

  const filteredVolunteers = useMemo(() => {
    return volunteers.filter(v => {
      const matchesSearch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!matchesSearch) return false;
      if (communityFilter === 'ACTIVE') return v.status === UserStatus.APPROVED;
      if (communityFilter === 'INACTIVE') return v.status === UserStatus.REJECTED;
      return true;
    });
  }, [volunteers, searchTerm, communityFilter]);

  if (isLoading) return <div className="min-h-screen bg-slate-50 flex items-center justify-center"><Loader2 className="animate-spin text-indigo-600" size={48} /></div>;

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
        <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-sm'} bg-white rounded-3xl shadow-2xl border border-slate-100 overflow-hidden`}>
          <div className="bg-indigo-600 p-10 text-center"><h1 className="text-3xl font-black text-white tracking-tight">VoluApp</h1><p className="text-indigo-100 text-[10px] uppercase font-bold tracking-widest mt-1">Comunidad Activa</p></div>
          {!isRegistering ? (
            <div className="p-10 space-y-6">
              {loginError && <div className="bg-red-50 p-4 rounded-xl flex items-center gap-3"><AlertCircle className="text-red-500" size={18} /><p className="text-xs font-bold text-red-600">{loginError}</p></div>}
              <input placeholder="Email" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-xl font-bold" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} />
              <input placeholder="Teléfono" type="tel" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-xl font-bold" value={loginForm.phone} onChange={e => setLoginForm({...loginForm, phone: e.target.value})} />
              <button onClick={handleLogin} className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">ENTRAR</button>
              <button onClick={() => setIsRegistering(true)} className="w-full text-indigo-600 font-bold text-sm">Crear una cuenta</button>
            </div>
          ) : (
            <div className="p-10 space-y-8 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <h2 className="text-3xl font-black text-slate-900">Registro</h2>
              {registrationError && <div className="bg-red-50 p-4 rounded-xl flex items-center gap-3"><AlertCircle className="text-red-500" size={18} /><p className="text-xs font-bold text-red-600">{registrationError}</p></div>}
              <ProfileForm formData={regForm} onChange={(upd) => setRegForm({...regForm, ...upd})} />
              <div className="flex gap-4 pt-6"><button onClick={() => setIsRegistering(false)} className="flex-1 font-bold text-slate-400">Cancelar</button><button onClick={handleRegister} className="flex-1 bg-indigo-600 text-white py-4 rounded-xl font-black shadow-lg">Registrarme</button></div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={currentUser.role} status={currentUser.status} userName={currentUser.name}>
      {activeTab === 'calendar' && <ShiftCalendar shifts={shifts.filter(s => volunteers.find(v => v.id === s.volunteerId)?.status === UserStatus.APPROVED)} volunteers={volunteers} currentUser={currentUser} onAddShift={(d) => addDoc(collection(db, "shifts"), {...d, volunteerId: currentUser.id})} onUpdateShift={(id, upd) => updateDoc(doc(db, "shifts", id), upd)} onRemoveShift={(id) => deleteDoc(doc(db, "shifts", id))} onViewVolunteer={setViewingVolunteer} />}
      {activeTab === 'attendance' && <AttendanceView currentUser={currentUser} volunteers={volunteers} attendances={attendances} onCheckIn={handleAttendanceCheckIn} />}
      {activeTab === 'volunteers' && (
        <div className="space-y-10">
          <div className="flex flex-col md:flex-row justify-between gap-6">
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">Comunidad</h2>
            <div className="flex flex-col sm:flex-row gap-4">
              <div className="flex bg-white p-1 rounded-2xl border-2 border-slate-100 shadow-sm">
                <button onClick={() => setCommunityFilter('ACTIVE')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${communityFilter === 'ACTIVE' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}>Activos</button>
                <button onClick={() => setCommunityFilter('INACTIVE')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${communityFilter === 'INACTIVE' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}>Inactivos</button>
                <button onClick={() => setCommunityFilter('ALL')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${communityFilter === 'ALL' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}>Todos</button>
              </div>
              <div className="relative"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input placeholder="Buscar..." className="pl-12 pr-6 py-4 bg-white border-2 border-slate-100 rounded-2xl w-full sm:w-64 font-bold outline-none focus:border-indigo-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div>
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(v => (
              <div 
                key={v.id} 
                onClick={() => currentUser.role === UserRole.ADMIN ? startEditing(v) : setViewingVolunteer(v)}
                className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center gap-5 hover:shadow-xl transition-all relative overflow-hidden group cursor-pointer"
              >
                <div className={`absolute left-0 top-0 bottom-0 w-1 ${v.status === UserStatus.APPROVED ? 'bg-green-500' : v.status === UserStatus.PENDING ? 'bg-amber-500' : 'bg-red-500'}`}></div>
                <img src={v.photoUrl} className="w-16 h-16 rounded-2xl object-cover ring-4 ring-indigo-50" alt="" />
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-slate-900 text-lg truncate flex items-center gap-2">{v.name}{v.role === UserRole.ADMIN && <ShieldCheck size={16} className="text-indigo-600" />}</h3>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[10px] font-black uppercase tracking-wider bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded">{v.volunteerType}</span>
                    {v.area && (
                      <span className="text-[9px] font-bold text-slate-400 uppercase flex items-center gap-1"><MapPin size={10} /> {v.area}</span>
                    )}
                  </div>
                </div>
                {currentUser.role === UserRole.ADMIN && (
                   <div className="p-3 text-slate-300 hover:text-indigo-600 bg-slate-50 rounded-xl">
                      <Edit2 size={18} />
                   </div>
                )}
              </div>
            ))}
            {filteredVolunteers.length === 0 && (
              <div className="col-span-full py-20 text-center space-y-4">
                <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-300"><Users size={32} /></div>
                <p className="font-bold text-slate-400">No se encontraron miembros con este criterio.</p>
              </div>
            )}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-2xl space-y-10">
            <div className="flex flex-col md:flex-row items-center md:items-end justify-between gap-8 border-b pb-10">
              <div className="flex flex-col md:flex-row items-center gap-8">
                <img src={currentUser.photoUrl} className="w-32 h-32 rounded-[2rem] object-cover ring-8 ring-indigo-50 shadow-2xl" alt="" />
                <div className="text-center md:text-left"><h2 className="text-4xl font-black text-slate-900 tracking-tight">{currentUser.name}</h2><span className="text-[11px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-5 py-2 rounded-full mt-3 inline-block">{currentUser.role}</span></div>
              </div>
              <button onClick={() => isEditingProfile ? saveMemberChanges(currentUser.id) : startEditing(currentUser)} className={`flex items-center gap-3 px-8 py-5 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl transition-all ${isEditingProfile ? 'bg-green-600 text-white' : 'bg-indigo-600 text-white'}`}>
                {isEditingProfile ? <><Save size={20} /> Guardar Cambios</> : <><Edit2 size={20} /> Editar Perfil</>}
              </button>
            </div>
            {isEditingProfile ? <ProfileForm formData={editForm} onChange={upd => setEditForm({...editForm, ...upd})} isAdminEditing={currentUser.role === UserRole.ADMIN} /> : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-6">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Email</label>
                     <p className="font-bold text-slate-900 text-xl break-all">{currentUser.email}</p>
                   </div>
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Teléfono</label>
                     <div className="flex items-center gap-3">
                        <a href={`tel:${sanitizePhone(currentUser.phone)}`} className="font-bold text-slate-900 text-xl hover:text-indigo-600 transition-colors">{currentUser.phone}</a>
                        <a href={`https://wa.me/${sanitizePhone(currentUser.phone)}`} target="_blank" rel="noopener noreferrer" className="p-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-all shadow-md">
                          <MessageCircle size={18} fill="currentColor" />
                        </a>
                     </div>
                   </div>
