            <div className="grid grid-cols-3 gap-2">
              {ROLE_ORDER.map(t => (
                <button key={t} type="button" onClick={() => onChange({ volunteerType: t })} className={`p-4 rounded-xl border-2 font-black text-[10px] uppercase transition-all ${formData.volunteerType === t ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{t}</button>
              ))}
            </div>
            <input placeholder="Área" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-indigo-500 transition-all mt-4" value={formData.area || ''} onChange={e => onChange({ area: e.target.value })} />
          </div>
          <div className="space-y-8">
            <div className="space-y-4">
               <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Sun size={14} className="text-blue-500" /> Turno de Mañana</label>
               <div className="grid grid-cols-7 gap-1.5">
                 {dayOrder.map(d => (
                   <button key={d} type="button" onClick={() => {
                     const days = formData.morningDays?.includes(d) ? formData.morningDays.filter(x => x !== d) : [...(formData.morningDays || []), d];
                     onChange({ morningDays: days });
                   }} className={`h-9 rounded-xl font-black text-[10px] transition-all border-2 ${formData.morningDays?.includes(d) ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{dayLabels[d]}</button>
                 ))}
               </div>
            </div>
            <div className="space-y-4">
               <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Moon size={14} className="text-amber-500" /> Turno de Tarde</label>
               <div className="grid grid-cols-7 gap-1.5">
                 {dayOrder.map(d => (
                   <button key={d} type="button" onClick={() => {
                     const days = formData.afternoonDays?.includes(d) ? formData.afternoonDays.filter(x => x !== d) : [...(formData.afternoonDays || []), d];
                     onChange({ afternoonDays: days });
                   }} className={`h-9 rounded-xl font-black text-[10px] transition-all border-2 ${formData.afternoonDays?.includes(d) ? 'bg-amber-600 border-amber-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>{dayLabels[d]}</button>
                 ))}
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [volunteers, setVolunteers] = useState<VolunteerProfile[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [attendances, setAttendances] = useState<AttendanceRecord[]>([]);
  const [currentUser, setCurrentUser] = useState<VolunteerProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [dbError, setDbError] = useState(false);
  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('calendar');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [viewingVolunteer, setViewingVolunteer] = useState<VolunteerProfile | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [registrationError, setRegistrationError] = useState<string | null>(null);

  const [communityFilter, setCommunityFilter] = useState<'ACTIVE' | 'INACTIVE' | 'ALL'>('ACTIVE');

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', morningDays: [] as number[], afternoonDays: [] as number[], volunteerType: VolunteerType.VTP, area: '', instagram: '', telegram: ''
  });

  const [editForm, setEditForm] = useState<Partial<VolunteerProfile & { morningDays: number[], afternoonDays: number[] }>>({});

  useEffect(() => {
    if (!db) { setDbError(true); setIsLoading(false); return; }
    const unsubVolunteers = onSnapshot(collection(db, "volunteers"), (snapshot) => {
      const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as VolunteerProfile));
      setVolunteers(data);
      if (currentUser) { const self = data.find(v => v.id === currentUser.id); if (self) setCurrentUser(self); }
      setIsLoading(false);
    });
    const unsubShifts = onSnapshot(collection(db, "shifts"), (snapshot) => setShifts(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Shift))));
    const unsubAttendances = onSnapshot(collection(db, "attendances"), (snapshot) => setAttendances(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as AttendanceRecord))));
    return () => { unsubVolunteers(); unsubShifts(); unsubAttendances(); };
  }, [currentUser?.id]);

  const handleLogout = () => { setCurrentUser(null); setIsRegistering(false); setLoginError(null); setActiveTab('calendar'); };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setLoginError(null);
    const user = volunteers.find(v => v.email.toLowerCase() === loginForm.email.trim().toLowerCase() && v.phone.trim() === loginForm.phone.trim());
    if (user) { setCurrentUser(user); setActiveTab(user.role === UserRole.ADMIN ? 'admin' : (user.status === UserStatus.APPROVED ? 'calendar' : 'profile')); }
    else setLoginError("Credenciales inválidas.");
  };

  const handleRegister = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setRegistrationError(null);
    if (!regForm.name || !regForm.email || !regForm.phone || !regForm.birthday) return setRegistrationError("Completa todos los campos obligatorios.");
    if (volunteers.some(v => v.email.toLowerCase().trim() === regForm.email.toLowerCase().trim())) return setRegistrationError("Este correo ya está en uso.");
    setIsSubmitting(true);
    try {
      const id = Math.random().toString(36).substring(2, 11);
      const newVol = { id, name: regForm.name, email: regForm.email, phone: regForm.phone, birthday: regForm.birthday, photoUrl: regForm.photoUrl, status: UserStatus.PENDING, role: UserRole.VOLUNTEER, volunteerType: regForm.volunteerType, area: regForm.area, instagram: regForm.instagram, telegram: regForm.telegram, joinedAt: new Date().toISOString() };
      await setDoc(doc(db, "volunteers", id), newVol);
      if (regForm.morningDays.length > 0) await addDoc(collection(db, "shifts"), { volunteerId: id, daysOfWeek: regForm.morningDays, period: 'MORNING' });
      if (regForm.afternoonDays.length > 0) await addDoc(collection(db, "shifts"), { volunteerId: id, daysOfWeek: regForm.afternoonDays, period: 'AFTERNOON' });
      setCurrentUser(newVol as VolunteerProfile); setActiveTab('profile'); setIsRegistering(false);
    } catch (e: any) { setRegistrationError(e.message); } finally { setIsSubmitting(false); }
  };

  const startEditing = (volunteer: VolunteerProfile) => {
    const userShifts = shifts.filter(s => s.volunteerId === volunteer.id);
    const morningShift = userShifts.find(s => s.period === 'MORNING');
    const afternoonShift = userShifts.find(s => s.period === 'AFTERNOON');

    setEditForm({ 
      ...volunteer, 
      morningDays: morningShift?.daysOfWeek || [], 
      afternoonDays: afternoonShift?.daysOfWeek || [] 
    });

    if (volunteer.id === currentUser?.id) {
      setIsEditingProfile(true);
    } else {
      setEditingVolunteer(volunteer);
    }
  };

  const saveMemberChanges = async (targetId: string) => {
    if (!db || !targetId) return;
    try {
      const { morningDays, afternoonDays, ...profileData } = editForm;
      const cleanProfile: any = {};
      const original = volunteers.find(v => v.id === targetId);

      Object.keys(profileData).forEach(key => {
        if (profileData[key as keyof typeof profileData] !== undefined) {
          cleanProfile[key] = profileData[key as keyof typeof profileData];
        }
      });

      // Lógica de marcas de tiempo al editar el perfil (ej. si el admin cambia el estado manualmente en el modal)
      if (original && cleanProfile.status && cleanProfile.status !== original.status) {
        const now = new Date().toISOString();
        if (cleanProfile.status === UserStatus.APPROVED) cleanProfile.activatedAt = now;
        if (cleanProfile.status === UserStatus.REJECTED) cleanProfile.deactivatedAt = now;
      }

      delete cleanProfile.id; 
      delete cleanProfile.joinedAt;

      await updateDoc(doc(db, "volunteers", targetId), cleanProfile);

      const shiftsRef = collection(db, "shifts");
      const q = query(shiftsRef, where("volunteerId", "==", targetId));
      const querySnap = await getDocs(q);

      const existingMorning = querySnap.docs.find(d => d.data().period === 'MORNING');
      const existingAfternoon = querySnap.docs.find(d => d.data().period === 'AFTERNOON');

      if (morningDays && morningDays.length > 0) {
        if (existingMorning) await updateDoc(doc(db, "shifts", existingMorning.id), { daysOfWeek: morningDays });
        else await addDoc(shiftsRef, { volunteerId: targetId, daysOfWeek: morningDays, period: 'MORNING' });
      } else if (existingMorning) {
        await deleteDoc(doc(db, "shifts", existingMorning.id));
      }

      if (afternoonDays && afternoonDays.length > 0) {
        if (existingAfternoon) await updateDoc(doc(db, "shifts", existingAfternoon.id), { daysOfWeek: afternoonDays });
        else await addDoc(shiftsRef, { volunteerId: targetId, daysOfWeek: afternoonDays, period: 'AFTERNOON' });
      } else if (existingAfternoon) {
        await deleteDoc(doc(db, "shifts", existingAfternoon.id));
      }

      setIsEditingProfile(false); 
      setEditingVolunteer(null);
    } catch (e) { 
      console.error("Error al guardar cambios:", e); 
    }
  };

  const handleAttendanceCheckIn = async (date: string) => {
    if (!currentUser || attendances.some(a => a.volunteerId === currentUser.id && a.date === date)) return;
    await addDoc(collection(db, "attendances"), { volunteerId: currentUser.id, date, timestamp: new Date().toISOString() });
  };

  const filteredVolunteers = useMemo(() => {
    return volunteers.filter(v => {
      const matchesSearch = v.name.toLowerCase().includes(searchTerm.toLowerCase()) || v.email.toLowerCase().includes(searchTerm.toLowerCase());
      if (!matchesSearch) return false;
      if (communityFilter === 'ACTIVE') return v.status === UserStatus.APPROVED;
      if (communityFilter === 'INACTIVE') return v.status === UserStatus.REJECTED;
      return true;
    });
  }, [volunteers, searchTerm, communityFilter]);

  if (isLoading) return <div className="min-h-screen bg-slate-50 flex items-center justify-center"><Loader2 className="animate-spin text-indigo-600" size={48} /></div>;

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
        <div className={`w-full ${isRegistering ? 'max-w-2xl' : 'max-w-sm'} bg-white rounded-3xl shadow-2xl border border-slate-100 overflow-hidden`}>
          <div className="bg-indigo-600 p-10 text-center"><h1 className="text-3xl font-black text-white tracking-tight">VoluApp</h1><p className="text-indigo-100 text-[10px] uppercase font-bold tracking-widest mt-1">Comunidad Activa</p></div>
          {!isRegistering ? (
            <form onSubmit={handleLogin} className="p-10 space-y-6">
              {loginError && <div className="bg-red-50 p-4 rounded-xl flex items-center gap-3"><AlertCircle className="text-red-500" size={18} /><p className="text-xs font-bold text-red-600">{loginError}</p></div>}
              <input placeholder="Email" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-xl font-bold" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} />
              <input placeholder="Teléfono" type="tel" className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-xl font-bold" value={loginForm.phone} onChange={e => setLoginForm({...loginForm, phone: e.target.value})} />
              <button type="submit" className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">ENTRAR</button>
              <button type="button" onClick={() => setIsRegistering(true)} className="w-full text-indigo-600 font-bold text-sm">Crear una cuenta</button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="p-10 space-y-8 max-h-[85vh] overflow-y-auto custom-scrollbar">
              <h2 className="text-3xl font-black text-slate-900">Registro</h2>
              {registrationError && <div className="bg-red-50 p-4 rounded-xl flex items-center gap-3"><AlertCircle className="text-red-500" size={18} /><p className="text-xs font-bold text-red-600">{registrationError}</p></div>}
              <ProfileForm formData={regForm} onChange={(upd) => setRegForm({...regForm, ...upd})} />
              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => setIsRegistering(false)} className="flex-1 font-bold text-slate-400">Cancelar</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white py-4 rounded-xl font-black shadow-lg">Registrarme</button>
              </div>
            </form>
          )}
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} onTabChange={(t: any) => setActiveTab(t)} onLogout={handleLogout} role={currentUser.role} status={currentUser.status} userName={currentUser.name}>
      {activeTab === 'calendar' && <ShiftCalendar shifts={shifts.filter(s => volunteers.find(v => v.id === s.volunteerId)?.status === UserStatus.APPROVED)} volunteers={volunteers} currentUser={currentUser} onAddShift={(d) => addDoc(collection(db, "shifts"), {...d, volunteerId: currentUser.id})} onUpdateShift={(id, upd) => updateDoc(doc(db, "shifts", id), upd)} onRemoveShift={(id) => deleteDoc(doc(db, "shifts", id))} onViewVolunteer={setViewingVolunteer} />}
      {activeTab === 'attendance' && <AttendanceView currentUser={currentUser} volunteers={volunteers} attendances={attendances} onCheckIn={handleAttendanceCheckIn} />}
      {activeTab === 'volunteers' && (
        <div className="space-y-10">
          <div className="flex flex-col md:flex-row justify-between gap-6">
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">Comunidad</h2>
            <div className="flex flex-col sm:flex-row gap-4">
              <div className="flex bg-white p-1 rounded-2xl border-2 border-slate-100 shadow-sm">
                <button onClick={() => setCommunityFilter('ACTIVE')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${communityFilter === 'ACTIVE' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}>Activos</button>
                <button onClick={() => setCommunityFilter('INACTIVE')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${communityFilter === 'INACTIVE' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}>Inactivos</button>
                <button onClick={() => setCommunityFilter('ALL')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${communityFilter === 'ALL' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:bg-slate-50'}`}>Todos</button>
              </div>
              <div className="relative"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input placeholder="Buscar..." className="pl-12 pr-6 py-4 bg-white border-2 border-slate-100 rounded-2xl w-full sm:w-64 font-bold outline-none focus:border-indigo-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div>
            </div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredVolunteers.map(v => (
              <div 
                key={v.id} 
                onClick={() => currentUser.role === UserRole.ADMIN ? startEditing(v) : setViewingVolunteer(v)}
                className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center gap-5 hover:shadow-xl transition-all relative overflow-hidden group cursor-pointer"
              >
                <div className={`absolute left-0 top-0 bottom-0 w-1 ${v.status === UserStatus.APPROVED ? 'bg-green-500' : v.status === UserStatus.PENDING ? 'bg-amber-500' : 'bg-red-500'}`}></div>
                <img src={v.photoUrl} className="w-16 h-16 rounded-2xl object-cover ring-4 ring-indigo-50" alt="" />
                <div className="flex-1 min-w-0">
                  <h3 title={v.name} className="font-bold text-slate-900 text-lg truncate flex items-center gap-2">{v.name}{v.role === UserRole.ADMIN && <ShieldCheck size={16} className="text-indigo-600" />}</h3>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[10px] font-black uppercase tracking-wider bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded">{v.volunteerType}</span>
                    {v.area && (
                      <span className="text-[9px] font-bold text-slate-400 uppercase flex items-center gap-1"><MapPin size={10} /> {v.area}</span>
                    )}
                  </div>
                </div>
                {currentUser.role === UserRole.ADMIN && (
                   <div className="p-3 text-slate-300 hover:text-indigo-600 bg-slate-50 rounded-xl">
                      <Edit2 size={18} />
                   </div>
                )}
              </div>
            ))}
            {filteredVolunteers.length === 0 && (
              <div className="col-span-full py-20 text-center space-y-4">
                <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-300"><Users size={32} /></div>
                <p className="font-bold text-slate-400">No se encontraron miembros con este criterio.</p>
              </div>
            )}
          </div>
        </div>
      )}
      {activeTab === 'profile' && (
        <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-2xl space-y-10">
            <div className="flex flex-col md:flex-row items-center md:items-end justify-between gap-8 border-b pb-10">
              <div className="flex flex-col md:flex-row items-center gap-8">
                <img src={currentUser.photoUrl} className="w-32 h-32 rounded-[2rem] object-cover ring-8 ring-indigo-50 shadow-2xl" alt="" />
                <div className="text-center md:text-left"><h2 className="text-4xl font-black text-slate-900 tracking-tight">{currentUser.name}</h2><span className="text-[11px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-5 py-2 rounded-full mt-3 inline-block">{currentUser.role}</span></div>
              </div>
              <button onClick={() => isEditingProfile ? saveMemberChanges(currentUser.id) : startEditing(currentUser)} className={`flex items-center gap-3 px-8 py-5 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl transition-all ${isEditingProfile ? 'bg-green-600 text-white' : 'bg-indigo-600 text-white'}`}>
                {isEditingProfile ? <><Save size={20} /> Guardar Cambios</> : <><Edit2 size={20} /> Editar Perfil</>}
              </button>
            </div>
            {isEditingProfile ? <ProfileForm formData={editForm} onChange={upd => setEditForm({...editForm, ...upd})} isAdminEditing={currentUser.role === UserRole.ADMIN} /> : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-6">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Email</label>
                     <p className="font-bold text-slate-900 text-xl break-all">{currentUser.email}</p>
                   </div>
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Teléfono</label>
                     <div className="flex items-center gap-3">
                        <a href={`tel:${sanitizePhone(currentUser.phone)}`} className="font-bold text-slate-900 text-xl hover:text-indigo-600 transition-colors">{currentUser.phone}</a>
                        <a href={`https://wa.me/${sanitizePhone(currentUser.phone)}`} target="_blank" rel="noopener noreferrer" className="p-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-all shadow-md">
                          <MessageCircle size={18} fill="currentColor" />
                        </a>
                     </div>
                   </div>
                   {currentUser.instagram && (
                     <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Instagram</label>
                       <a href={`https://instagram.com/${currentUser.instagram.replace('@','')}`} target="_blank" rel="noopener noreferrer" className="font-bold text-indigo-600 text-xl flex items-center gap-2 hover:underline">
                         <Instagram size={20} /> {currentUser.instagram.startsWith('@') ? currentUser.instagram : `@${currentUser.instagram}`}
                       </a>
                     </div>
                   )}
                   {currentUser.telegram && (
                     <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Telegram</label>
                       <a href={`https://t.me/${currentUser.telegram.replace('@','')}`} target="_blank" rel="noopener noreferrer" className="font-bold text-blue-500 text-xl flex items-center gap-2 hover:underline">
                         <Send size={20} /> {currentUser.telegram.startsWith('@') ? currentUser.telegram : `@${currentUser.telegram}`}
                       </a>
                     </div>
                   )}
                   <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Cumpleaños</label><p className="font-bold text-slate-900 text-xl">{formatBirthday(currentUser.birthday)}</p></div>
                </div>
                <div className="space-y-6">
                   <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Tipo de Voluntario</label><p className="font-bold text-slate-900 text-xl">{currentUser.volunteerType}</p></div>
                   {currentUser.area && <div><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Área</label><p className="font-bold text-slate-900 text-xl">{currentUser.area}</p></div>}
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Horarios</label>
                     <div className="space-y-4">
                        <div className="space-y-2">
                           <p className="text-[9px] font-black uppercase tracking-wider text-blue-500 flex items-center gap-1"><Sun size={12} /> Mañana</p>
                           <div className="flex flex-wrap gap-1.5">{shifts.find(s => s.volunteerId === currentUser.id && s.period === 'MORNING')?.daysOfWeek.map(d => <span key={d} className="bg-blue-50 px-2 py-0.5 rounded font-black text-[9px] text-blue-600 uppercase">{['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][d]}</span>) || <span className="text-[9px] text-slate-300 font-bold">Sin asignar</span>}</div>
                        </div>
                        <div className="space-y-2">
                           <p className="text-[9px] font-black uppercase tracking-wider text-amber-500 flex items-center gap-1"><Moon size={12} /> Tarde</p>
                           <div className="flex flex-wrap gap-1.5">{shifts.find(s => s.volunteerId === currentUser.id && s.period === 'AFTERNOON')?.daysOfWeek.map(d => <span key={d} className="bg-amber-50 px-2 py-0.5 rounded font-black text-[9px] text-amber-600 uppercase">{['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][d]}</span>) || <span className="text-[9px] text-slate-300 font-bold">Sin asignar</span>}</div>
                        </div>
                     </div>
                   </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
      {activeTab === 'admin' && (
        <AdminDashboard 
          volunteers={volunteers} 
          onUpdateStatus={(id, s) => {
            const now = new Date().toISOString();
            const updates: any = { status: s };
            if (s === UserStatus.APPROVED) updates.activatedAt = now;
            if (s === UserStatus.REJECTED) updates.deactivatedAt = now;
            updateDoc(doc(db, "volunteers", id), updates);
          }} 
          onEditVolunteer={startEditing} 
        />
      )}

      {editingVolunteer && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl my-10 p-12 shadow-2xl relative animate-in zoom-in duration-300">
            <div className="flex items-center justify-between mb-10">
              <div>
                <h3 className="text-3xl font-black text-slate-900">Editar Miembro</h3>
                <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mt-1">Gestión administrativa completa</p>
              </div>
              <button onClick={() => setEditingVolunteer(null)} className="p-3 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-2xl transition-all"><X size={24} /></button>
            </div>

            <div className="max-h-[65vh] overflow-y-auto custom-scrollbar pr-4">
              <ProfileForm 
                formData={editForm} 
                onChange={upd => setEditForm(prev => ({...prev, ...upd}))} 
                isAdminEditing={true} 
              />
            </div>

            <button 
              onClick={() => saveMemberChanges(editingVolunteer.id)} 
              className="w-full mt-10 py-6 bg-slate-900 text-white rounded-2xl font-black uppercase text-base tracking-widest shadow-2xl hover:bg-black transition-all active:scale-95"
            >
              Guardar Todos los Cambios
            </button>
          </div>
        </div>
      )}

      {viewingVolunteer && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl p-12 shadow-2xl relative animate-in zoom-in duration-300">
            <button onClick={() => setViewingVolunteer(null)} className="absolute top-8 right-8 p-3 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-2xl transition-all"><X size={24} /></button>

            <div className="flex flex-col items-center text-center space-y-6">
              <img src={viewingVolunteer.photoUrl} className="w-32 h-32 rounded-[2.5rem] object-cover ring-8 ring-indigo-50 shadow-2xl" alt="" />
              <div>
                <h3 className="text-3xl font-black text-slate-900 flex items-center justify-center gap-2">
                  {viewingVolunteer.name}
                  {viewingVolunteer.role === UserRole.ADMIN && <ShieldCheck size={24} className="text-indigo-600" />}
                </h3>
                <p className="text-xs font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-4 py-1.5 rounded-full mt-2 inline-block">
                  {viewingVolunteer.volunteerType}
                </p>
              </div>

              <div className="w-full grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-slate-100 text-left">
                <div className="space-y-4">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Contacto</label>
                     <p className="font-bold text-slate-800 flex items-center gap-2">
                       <Mail size={14} className="text-indigo-400" /> {viewingVolunteer.email}
                     </p>
                     <div className="flex items-center gap-2 mt-1">
                        <Phone size={14} className="text-indigo-400" />
                        <a href={`tel:${sanitizePhone(viewingVolunteer.phone)}`} className="font-bold text-slate-800 hover:text-indigo-600 transition-colors underline-offset-4 hover:underline">{viewingVolunteer.phone}</a>
                        <a href={`https://wa.me/${sanitizePhone(viewingVolunteer.phone)}`} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-all shadow-sm ml-1">
                          <MessageCircle size={14} fill="currentColor" />
                        </a>
                     </div>
                   </div>
                   {(viewingVolunteer.instagram || viewingVolunteer.telegram) && (
                     <div className="flex items-center gap-4">
                       {viewingVolunteer.instagram && (
                         <a href={`https://instagram.com/${viewingVolunteer.instagram.replace('@','')}`} target="_blank" rel="noopener noreferrer" className="p-2 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all">
                           <Instagram size={20} />
                         </a>
                       )}
                       {viewingVolunteer.telegram && (
                         <a href={`https://t.me/${viewingVolunteer.telegram.replace('@','')}`} target="_blank" rel="noopener noreferrer" className="p-2 bg-blue-50 text-blue-500 rounded-xl hover:bg-blue-500 hover:text-white transition-all">
                           <Send size={20} />
                         </a>
                       )}
                     </div>
                   )}
                   {viewingVolunteer.area && (
                     <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Área</label>
                       <p className="font-bold text-slate-800 flex items-center gap-2"><MapPin size={14} className="text-indigo-400" /> {viewingVolunteer.area}</p>
                     </div>
                   )}
                </div>

                <div className="space-y-4">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Horario Semanal</label>
                     <div className="space-y-3">
                        <div className="flex flex-wrap gap-1.5">
                           <span className="text-[9px] font-black uppercase text-blue-500 flex items-center gap-1 w-full"><Sun size={10} /> Mañana:</span>
                           {shifts.find(s => s.volunteerId === viewingVolunteer.id && s.period === 'MORNING')?.daysOfWeek.map(d => (
                             <span key={d} className="bg-blue-50 px-2 py-0.5 rounded font-black text-[9px] text-blue-600 uppercase">
                               {['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][d]}
                             </span>
                           )) || <span className="text-[9px] text-slate-300 font-bold">Sin turnos</span>}
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                           <span className="text-[9px] font-black uppercase text-amber-500 flex items-center gap-1 w-full"><Moon size={10} /> Tarde:</span>
                           {shifts.find(s => s.volunteerId === viewingVolunteer.id && s.period === 'AFTERNOON')?.daysOfWeek.map(d => (
                             <span key={d} className="bg-amber-50 px-2 py-0.5 rounded font-black text-[9px] text-amber-600 uppercase">
                               {['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][d]}
                             </span>
                           )) || <span className="text-[9px] text-slate-300 font-bold">Sin turnos</span>}
                        </div>
                     </div>
                   </div>
                </div>
              </div>

              <button 
                onClick={() => setViewingVolunteer(null)}
                className="w-full mt-6 py-4 bg-slate-900 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl"
              >
                Cerrar Perfil
              </button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  format, 
  addWeeks, 
  endOfWeek, 
  eachDayOfInterval, 
  isSameDay, 
  getDay,
  isToday
} from 'date-fns';
import { es } from 'date-fns/locale/es';
import { ChevronLeft, ChevronRight, Plus, Clock, Calendar, Trash2, Edit2, CalendarDays, Sun, Moon, MapPin } from 'lucide-react';
import { Shift, VolunteerProfile, ShiftPeriod } from '../types';

interface ShiftCalendarProps {
  shifts: Shift[];
  volunteers: VolunteerProfile[];
  currentUser: VolunteerProfile;
  onAddShift: (shift: Omit<Shift, 'id' | 'volunteerId'>) => void;
  onUpdateShift: (id: string, updated: Partial<Shift>) => void;
  onRemoveShift: (shiftId: string) => void;
  onViewVolunteer?: (v: VolunteerProfile) => void;
}

const ShiftCalendar: React.FC<ShiftCalendarProps> = ({ 
  shifts, 
  volunteers,
  currentUser, 
  onAddShift, 
  onUpdateShift,
  onRemoveShift,
  onViewVolunteer
}) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [editingShiftId, setEditingShiftId] = useState<string | null>(null);

  const [selectedPeriod, setSelectedPeriod] = useState<ShiftPeriod>('MORNING');
  const [selectedDays, setSelectedDays] = useState<number[]>([]);

  const weekStart = (() => {
    const d = new Date(currentDate);
    const day = d.getDay();
    const diff = (day === 0 ? -6 : 1 - day);
    d.setDate(d.getDate() + diff);
    d.setHours(0, 0, 0, 0);
    return d;
  })();

  const weekEnd = endOfWeek(weekStart, { weekStartsOn: 1 });
  const weekDays = eachDayOfInterval({ start: weekStart, end: weekEnd });

  const getShiftsForDay = (day: Date, period?: ShiftPeriod) => {
    const dayOfWeek = getDay(day);
    return shifts.filter(s => 
      s.daysOfWeek.includes(dayOfWeek) && 
      (!period || s.period === period)
    );
  };

  const handleOpenAdd = () => {
    setEditingShiftId(null);
    setSelectedPeriod('MORNING');
    setSelectedDays([getDay(new Date())]);
    setShowModal(true);
  };

  const handleOpenEdit = (shift: Shift) => {
    setEditingShiftId(shift.id);
    setSelectedPeriod(shift.period);
    setSelectedDays([...shift.daysOfWeek]);
    setShowModal(true);
  };

  const handleSave = () => {
    if (selectedDays.length === 0) {
      alert("Por favor, selecciona al menos un día.");
      return;
    }
    if (editingShiftId) {
      onUpdateShift(editingShiftId, { period: selectedPeriod, daysOfWeek: selectedDays });
    } else {
      onAddShift({ period: selectedPeriod, daysOfWeek: selectedDays });
    }
    setShowModal(false);
  };

  const toggleDay = (day: number) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const dayNamesShort = ['D', 'L', 'M', 'X', 'J', 'V', 'S'];
  const dayNamesMid = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Horario Semanal</h2>
          <p className="text-slate-500 font-medium text-base">Asignaciones de voluntarios para esta semana</p>
        </div>
        <div className="flex items-center gap-1 bg-white p-1 rounded-2xl shadow-sm border border-slate-200">
          <button 
            onClick={() => setCurrentDate(addWeeks(currentDate, -1))} 
            className="p-2.5 hover:bg-slate-50 rounded-xl transition-colors text-slate-600"
          >
            <ChevronLeft size={22} />
          </button>
          <span className="px-6 font-bold min-w-[220px] text-center text-slate-800 text-sm">
            {format(weekStart, 'd MMM', { locale: es })} – {format(weekEnd, 'd MMM, yyyy', { locale: es })}
          </span>
          <button 
            onClick={() => setCurrentDate(addWeeks(currentDate, 1))} 
            className="p-2.5 hover:bg-slate-50 rounded-xl transition-colors text-slate-600"
          >
            <ChevronRight size={22} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
        {weekDays.map((day, idx) => {
          const morningShifts = getShiftsForDay(day, 'MORNING');
          const afternoonShifts = getShiftsForDay(day, 'AFTERNOON');
          const isTodayDate = isToday(day);

          return (
            <div 
              key={idx} 
              className={`flex flex-col rounded-[2rem] border transition-all ${
                isTodayDate 
                  ? 'bg-indigo-50/30 border-indigo-200 shadow-lg shadow-indigo-100/50 ring-2 ring-indigo-500/20' 
                  : 'bg-white border-slate-200 shadow-sm'
              }`}
            >
              <div className={`p-4 text-center border-b ${isTodayDate ? 'border-indigo-100' : 'border-slate-100'}`}>
                <p className={`text-[11px] font-black uppercase tracking-[0.2em] mb-1 ${isTodayDate ? 'text-indigo-600' : 'text-slate-400'}`}>
                  {format(day, 'EEE', { locale: es })}
                </p>
                <p className={`text-2xl font-black ${isTodayDate ? 'text-indigo-700' : 'text-slate-800'}`}>
                  {format(day, 'd')}
                </p>
              </div>

              <div className="flex-1 p-3 space-y-4 min-h-[220px]">
                <div className="space-y-2">
                  <div className="flex items-center gap-1.5 px-1">
                    <Sun size={14} className="text-blue-500" />
                    <span className="text-[10px] font-black uppercase tracking-wider text-blue-600/60">Mañana</span>
                  </div>
                  <div className="space-y-1.5">
                    {morningShifts.length === 0 ? (
                      <div className="py-2 text-center text-[9px] font-bold text-slate-300 italic">Vacío</div>
                    ) : (
                      morningShifts.map(s => {
                        const vol = volunteers.find(v => v.id === s.volunteerId);
                        return (
                          <button 
                            key={s.id} 
                            onClick={() => vol && onViewVolunteer?.(vol)}
                            title={vol?.name}
                            className="w-full bg-blue-50/50 border border-blue-100 p-2.5 rounded-xl flex items-center gap-2 hover:bg-blue-100/70 transition-all text-left group"
                          >
                            <img src={vol?.photoUrl} className="w-6 h-6 rounded-full object-cover group-hover:ring-2 ring-blue-400" alt="" />
                            <div className="flex-1 min-w-0">
                               <span className="text-[11px] font-bold text-blue-700 truncate block">{vol?.name}</span>
                               {vol?.area && <span className="text-[8px] font-medium text-blue-500/70 truncate block">{vol.area}</span>}
                            </div>
                          </button>
                        );
                      })
                    )}
                  </div>
                </div>

                <div className="space-y-2">
                  <div className="flex items-center gap-1.5 px-1">
                    <Moon size={14} className="text-amber-500" />
                    <span className="text-[10px] font-black uppercase tracking-wider text-amber-600/60">Tarde</span>
                  </div>
                  <div className="space-y-1.5">
                    {afternoonShifts.length === 0 ? (
                      <div className="py-2 text-center text-[9px] font-bold text-slate-300 italic">Vacío</div>
                    ) : (
                      afternoonShifts.map(s => {
                        const vol = volunteers.find(v => v.id === s.volunteerId);
                        return (
                          <button 
                            key={s.id} 
                            onClick={() => vol && onViewVolunteer?.(vol)}
                            title={vol?.name}
                            className="w-full bg-amber-50/50 border border-amber-100 p-2.5 rounded-xl flex items-center gap-2 hover:bg-amber-100/70 transition-all text-left group"
                          >
                            <img src={vol?.photoUrl} className="w-6 h-6 rounded-full object-cover group-hover:ring-2 ring-amber-400" alt="" />
                            <div className="flex-1 min-w-0">
                               <span className="text-[11px] font-bold text-amber-700 truncate block">{vol?.name}</span>
                               {vol?.area && <span className="text-[8px] font-medium text-amber-500/70 truncate block">{vol.area}</span>}
                            </div>
                          </button>
                        );
                      })
                    )}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-2xl font-bold text-slate-900">Mis Compromisos Recurrentes</h3>
              <p className="text-base text-slate-500 font-medium">Gestiona tu disponibilidad semanal</p>
            </div>
            <button 
              onClick={handleOpenAdd} 
              className="group flex items-center gap-2 px-6 py-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-200 transition-all active:scale-95 font-bold text-sm"
            >
              <Plus size={22} className="group-hover:rotate-90 transition-transform" /> 
              Actualizar Mi Horario
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 gap-4">
            {shifts.filter(s => s.volunteerId === currentUser.id).length === 0 ? (
              <div className="col-span-full p-16 text-center border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white">
                <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 mx-auto mb-4">
                  <CalendarDays size={36} />
                </div>
                <h4 className="font-bold text-slate-800 mb-1 text-lg">Sin horario definido</h4>
                <p className="text-slate-400 text-sm max-w-xs mx-auto font-medium">Añade un bloque recurrente por la mañana o tarde para ayudar a la comunidad.</p>
              </div>
            ) : (
              shifts.filter(s => s.volunteerId === currentUser.id).map(shift => (
                <div key={shift.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center justify-between hover:shadow-md transition-shadow">
                  <div className="flex items-center gap-5">
                    <div className={`p-4 rounded-2xl ${
                      shift.period === 'MORNING' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'
                    }`}>
                      <Clock size={28} />
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-xl">
                        {shift.period === 'MORNING' ? 'Turno de Mañana' : 'Turno de Tarde'}
                      </h4>
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {shift.daysOfWeek.sort().map(d => (
                          <span key={d} className="text-[10px] font-black uppercase tracking-wider text-slate-400 bg-slate-50 px-2.5 py-1 rounded-md">
                            {dayNamesMid[d]}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <button onClick={() => handleOpenEdit(shift)} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"><Edit2 size={20} /></button>
                    <button onClick={() => onRemoveShift(shift.id)} className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"><Trash2 size={20} /></button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white relative overflow-hidden group shadow-2xl shadow-slate-900/20">
            <div className="absolute top-0 right-0 p-8 text-white/5 group-hover:text-white/10 transition-colors">
              <Calendar size={140} />
            </div>
            <div className="relative z-10">
              <h3 className="text-2xl font-bold mb-1">Resumen Semanal</h3>
              <p className="text-slate-400 text-base font-medium mb-8">Capacidad para esta semana</p>
              <div className="flex items-baseline gap-4">
                <span className="text-7xl font-black text-indigo-400 tracking-tighter">
                  {shifts.reduce((acc, s) => acc + s.daysOfWeek.length, 0)}
                </span>
                <div className="space-y-0.5">
                  <p className="text-[11px] font-black uppercase tracking-widest text-slate-500">Total</p>
                  <p className="text-[11px] font-black uppercase tracking-widest text-slate-500">Turnos</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] w-full max-w-md p-10 shadow-2xl animate-in zoom-in slide-in-from-bottom-8 duration-500">
            <h3 className="text-3xl font-black text-slate-900 mb-2">{editingShiftId ? 'Editar Horario' : 'Nuevo Horario'}</h3>
            <p className="text-slate-500 font-medium mb-10 text-base">Elige tus bloques recurrentes de disponibilidad.</p>

            <div className="space-y-8">
              <div>
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 block">Días de la Semana</label>
                <div className="grid grid-cols-7 gap-2">
                  {[0,1,2,3,4,5,6].map(d => (
                    <button
                      key={d}
                      onClick={() => toggleDay(d)}
                      className={`h-11 rounded-2xl font-black text-xs transition-all border-2 ${
                        selectedDays.includes(d) 
                          ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100' 
                          : 'bg-white border-slate-100 text-slate-400 hover:border-indigo-200'
                      }`}
                    >
                      {dayNamesShort[d]}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 block">Período Preferido</label>
                <div className="grid grid-cols-2 gap-4">
                  <button 
                    onClick={() => setSelectedPeriod('MORNING')} 
                    className={`flex flex-col items-center gap-4 p-6 rounded-3xl border-2 transition-all group ${
                      selectedPeriod === 'MORNING' 
                        ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700 shadow-lg shadow-indigo-50' 
                        : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                    }`}
                  >
                    <div className={`p-3 rounded-2xl transition-colors ${selectedPeriod === 'MORNING' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-white'}`}>
                      <Sun size={24} />
                    </div>
                    <span className="font-black text-sm uppercase tracking-widest">Mañana</span>
                  </button>
                  <button 
                    onClick={() => setSelectedPeriod('AFTERNOON')} 
                    className={`flex flex-col items-center gap-4 p-6 rounded-3xl border-2 transition-all group ${
                      selectedPeriod === 'AFTERNOON' 
                        ? 'border-indigo-600 bg-indigo-50/50 text-indigo-700 shadow-lg shadow-indigo-50' 
                        : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200'
                    }`}
                  >
                    <div className={`p-3 rounded-2xl transition-colors ${selectedPeriod === 'AFTERNOON' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-white'}`}>
                      <Moon size={24} />
                    </div>
                    <span className="font-black text-sm uppercase tracking-widest">Tarde</span>
                  </button>
                </div>
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => setShowModal(false)} 
                  className="flex-1 py-5 text-slate-400 font-black uppercase tracking-widest text-xs hover:text-slate-600 hover:bg-slate-50 rounded-2xl transition-all"
                >
                  Cancelar
                </button>
                <button 
                  onClick={handleSave} 
                  className="flex-1 py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black uppercase tracking-widest text-xs shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
                >
                  {editingShiftId ? 'Actualizar' : 'Confirmar'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ShiftCalendar;

import React, { useState } from 'react';
import { 
  Check, 
  X, 
  Mail, 
  Phone, 
  AlertCircle, 
  UserCheck, 
  UserX, 
  Clock, 
  Edit2, 
  Filter, 
  Eye, 
  EyeOff, 
  Users,
  Power,
  MapPin,
  Tag,
  ShieldCheck,
  User,
  Search,
  CalendarDays
} from 'lucide-react';
import { VolunteerProfile, UserStatus, UserRole, VolunteerType } from '../types';
import { format } from 'date-fns';
import { es } from 'date-fns/locale/es';

interface AdminDashboardProps {
  volunteers: VolunteerProfile[];
  onUpdateStatus: (id: string, status: UserStatus) => void;
