                           <div className="flex flex-wrap gap-1.5">{shifts.find(s => s.volunteerId === currentUser.id && s.period === 'AFTERNOON')?.daysOfWeek.map(d => <span key={d} className="bg-amber-50 px-2 py-0.5 rounded font-black text-[9px] text-amber-600 uppercase">{['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][d]}</span>) || <span className="text-[9px] text-slate-300 font-bold">Sin asignar</span>}</div>
