        </div>
      )}
      {activeTab === 'admin' && (
        <AdminDashboard 
          volunteers={volunteers} 
          onUpdateStatus={(id, s) => {
            const now = new Date().toISOString();
            const updates: any = { status: s };
            if (s === UserStatus.APPROVED) updates.activatedAt = now;
            if (s === UserStatus.REJECTED) updates.deactivatedAt = now;
            updateDoc(doc(db, "volunteers", id), updates);
          }} 
          onEditVolunteer={startEditing} 
        />
      )}

      {editingVolunteer && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-4xl my-10 p-12 shadow-2xl relative animate-in zoom-in duration-300">
