              </div>

              <div className="w-full grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-slate-100 text-left">
                <div className="space-y-4">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Contacto</label>
                     <p className="font-bold text-slate-800 flex items-center gap-2">
                       <Mail size={14} className="text-indigo-400" /> {viewingVolunteer.email}
                     </p>
                     <div className="flex items-center gap-2 mt-1">
                        <Phone size={14} className="text-indigo-400" />
                        <a href={`tel:${sanitizePhone(viewingVolunteer.phone)}`} className="font-bold text-slate-800 hover:text-indigo-600 transition-colors underline-offset-4 hover:underline">{viewingVolunteer.phone}</a>
                        <a href={`https://wa.me/${sanitizePhone(viewingVolunteer.phone)}`} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-all shadow-sm ml-1">
                          <MessageCircle size={14} fill="currentColor" />
                        </a>
                     </div>
                   </div>
                   {(viewingVolunteer.instagram || viewingVolunteer.telegram) && (
                     <div className="flex items-center gap-4">
                       {viewingVolunteer.instagram && (
                         <a href={`https://instagram.com/${viewingVolunteer.instagram.replace('@','')}`} target="_blank" rel="noopener noreferrer" className="p-2 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all">
                           <Instagram size={20} />
                         </a>
                       )}
                       {viewingVolunteer.telegram && (
                         <a href={`https://t.me/${viewingVolunteer.telegram.replace('@','')}`} target="_blank" rel="noopener noreferrer" className="p-2 bg-blue-50 text-blue-500 rounded-xl hover:bg-blue-500 hover:text-white transition-all">
                           <Send size={20} />
                         </a>
                       )}
                     </div>
                   )}
                   {viewingVolunteer.area && (
                     <div>
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Área</label>
                       <p className="font-bold text-slate-800 flex items-center gap-2"><MapPin size={14} className="text-indigo-400" /> {viewingVolunteer.area}</p>
                     </div>
                   )}
                </div>

                <div className="space-y-4">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Horario Semanal</label>
                     <div className="space-y-3">
                        <div className="flex flex-wrap gap-1.5">
                           <span className="text-[9px] font-black uppercase text-blue-500 flex items-center gap-1 w-full"><Sun size={10} /> Mañana:</span>
                           {shifts.find(s => s.volunteerId === viewingVolunteer.id && s.period === 'MORNING')?.daysOfWeek.map(d => (
                             <span key={d} className="bg-blue-50 px-2 py-0.5 rounded font-black text-[9px] text-blue-600 uppercase">
                               {['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][d]}
                             </span>
                           )) || <span className="text-[9px] text-slate-300 font-bold">Sin turnos</span>}
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                           <span className="text-[9px] font-black uppercase text-amber-500 flex items-center gap-1 w-full"><Moon size={10} /> Tarde:</span>
                           {shifts.find(s => s.volunteerId === viewingVolunteer.id && s.period === 'AFTERNOON')?.daysOfWeek.map(d => (
                             <span key={d} className="bg-amber-50 px-2 py-0.5 rounded font-black text-[9px] text-amber-600 uppercase">
                               {['Dom','Lun','Mar','Mie','Jue','Vie','Sab'][d]}
                             </span>
                           )) || <span className="text-[9px] text-slate-300 font-bold">Sin turnos</span>}
                        </div>
                     </div>
                   </div>
                </div>
              </div>

              <button 
                onClick={() => setViewingVolunteer(null)}
                className="w-full mt-6 py-4 bg-slate-900 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl"
              >
                Cerrar Perfil
              </button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

export enum UserStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum UserRole {
  VOLUNTEER = 'VOLUNTEER',
  ADMIN = 'ADMIN'
}

export enum VolunteerType {
  VTC = 'VTC',
  VTP = 'VTP',
  BASE = 'BASE'
}

export type ShiftPeriod = 'MORNING' | 'AFTERNOON';

export interface VolunteerProfile {
  id: string;
  name: string;
  email: string;
  phone: string;
  birthday: string;
  photoUrl: string;
  status: UserStatus;
  role: UserRole;
  volunteerType: VolunteerType;
  area?: string;
  instagram?: string;
  telegram?: string;
  activatedAt?: string;
  deactivatedAt?: string;
  joinedAt: string;
}

export interface Shift {
  id: string;
  volunteerId: string;
  daysOfWeek: number[]; // 0 for Sunday, 1 for Monday, etc.
  period: ShiftPeriod;
}

export interface AttendanceRecord {
  id: string;
  volunteerId: string;
  date: string; // YYYY-MM-DD
  timestamp: string; // Full ISO
}

export interface Announcement {
  id: string;
  message: string;
  publishedAt: string;
  status: 'published' | 'hidden';
  createdBy: string;
}

export interface AppState {
  currentUser: VolunteerProfile | null;
  volunteers: VolunteerProfile[];
  shifts: Shift[];
  attendances: AttendanceRecord[];
  announcements: Announcement[];
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  UserStatus, 
  UserRole, 
  VolunteerProfile, 
  Shift, 
  ShiftPeriod,
  VolunteerType,
  AttendanceRecord,
  Announcement
} from './types';
import Layout from './components/Layout';
import ShiftCalendar from './components/ShiftCalendar';
import AdminDashboard from './components/AdminDashboard';
import AttendanceView from './components/AttendanceView';
import { db } from './firebase';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  addDoc,
  query,
  where,
  getDocs,
  orderBy,
  writeBatch
} from '@firebase/firestore';
import { 
  format, 
  isSameMonth, 
  isSameYear, 
  addMonths, 
  isValid,
  endOfMonth,
  endOfWeek,
  eachDayOfInterval,
  isSameDay,
  getYear,
  getMonth
} from 'date-fns';
import { es } from 'date-fns/locale/es';
import { 
  Mail, 
  Phone, 
  Search,
  X,
  Power,
  Camera,
  ImageIcon,
  Loader2,
  Clock,
  Edit2,
  Sun,
  Moon,
  Save,
  User,
  Users,
  Cake,
  AlertCircle,
  ClipboardCheck,
  ChevronLeft,
  ChevronRight,
  History,
  TrendingUp,
  ShieldCheck,
  ExternalLink,
  Info,
  Bug,
  Terminal,
  Calendar as CalendarIcon,
  MapPin,
  Briefcase,
  Activity,
  Filter,
  Instagram,
  Send,
  MessageCircle,
  Bell
} from 'lucide-react';

const ROLE_ORDER = [VolunteerType.VTP, VolunteerType.VTC, VolunteerType.BASE];
const STORAGE_KEY = 'voluapp_user_session';

const App: React.FC = () => {
  const [volunteers, setVolunteers] = useState<VolunteerProfile[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [attendances, setAttendances] = useState<AttendanceRecord[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  const [currentUser, setCurrentUser] = useState<VolunteerProfile | null>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });

  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'calendar' | 'volunteers' | 'profile' | 'admin' | 'attendance'>('volunteers');
  const [isRegistering, setIsRegistering] = useState(false);
  const [editingVolunteer, setEditingVolunteer] = useState<VolunteerProfile | null>(null);
  const [viewingVolunteer, setViewingVolunteer] = useState<VolunteerProfile | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [loginError, setLoginError] = useState<string | null>(null);
  const [registrationError, setRegistrationError] = useState<string | null>(null);
  const [communityFilter, setCommunityFilter] = useState<'ACTIVE' | 'INACTIVE' | 'ALL'>('ACTIVE');
  const [isEditingProfile, setIsEditingProfile] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', phone: '' });
  const [regForm, setRegForm] = useState({ 
    name: '', email: '', phone: '', birthday: '', photoUrl: 'https://picsum.photos/seed/newvol/100/100', morningDays: [] as number[], afternoonDays: [] as number[], volunteerType: VolunteerType.VTP, area: '', instagram: '', telegram: ''
  });

  const [editForm, setEditForm] = useState<Partial<VolunteerProfile & { morningDays: number[], afternoonDays: number[] }>>({});

  useEffect(() => {
    if (currentUser) localStorage.setItem(STORAGE_KEY, JSON.stringify(currentUser));
    else localStorage.removeItem(STORAGE_KEY);
  }, [currentUser]);

  useEffect(() => {
    if (!db) { setIsLoading(false); return; }

    const unsubVolunteers = onSnapshot(collection(db, "volunteers"), (snapshot) => {
      const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as VolunteerProfile));
      setVolunteers(data);
      if (currentUser) {
        const self = data.find(v => v.id === currentUser.id);
        if (self && JSON.stringify(self) !== JSON.stringify(currentUser)) setCurrentUser(self);
      }
      setIsLoading(false);
    });

    const unsubShifts = onSnapshot(collection(db, "shifts"), (snapshot) => setShifts(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Shift))));
    const unsubAttendances = onSnapshot(collection(db, "attendances"), (snapshot) => setAttendances(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as AttendanceRecord))));
    const unsubAnnouncements = onSnapshot(query(collection(db, "announcements"), orderBy("publishedAt", "desc")), (snapshot) => {
      setAnnouncements(snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Announcement)));
    });

    return () => { unsubVolunteers(); unsubShifts(); unsubAttendances(); unsubAnnouncements(); };
  }, [currentUser?.id]);

  useEffect(() => {
    if (!isLoading && currentUser) {
      if (currentUser.role === UserRole.ADMIN) setActiveTab('admin');
      else if (currentUser.status === UserStatus.PENDING) setActiveTab('profile');
      else setActiveTab('volunteers');
    }
  }, [isLoading, currentUser?.id]);

  const handleAttendanceCheckIn = async (date: string) => {
    if (!currentUser) return;
    try { await addDoc(collection(db, "attendances"), { volunteerId: currentUser.id, date, timestamp: new Date().toISOString() }); }
    catch (e) { console.error(e); }
  };

  useEffect(() => {
    const handleHashCheckIn = async () => {
      if (window.location.hash === '#check-in' && currentUser && currentUser.status === UserStatus.APPROVED) {
        const today = format(new Date(), 'yyyy-MM-dd');
        const alreadyRegistered = attendances.some(a => a.volunteerId === currentUser.id && a.date === today);
        if (!alreadyRegistered) {
          await handleAttendanceCheckIn(today);
          setActiveTab('attendance');
          window.history.replaceState(null, '', window.location.pathname);
        }
      }
    };
    if (!isLoading) handleHashCheckIn();
  }, [currentUser, isLoading, attendances.length]);

  const handleLogout = () => { 
    setCurrentUser(null); 
    localStorage.removeItem(STORAGE_KEY);
    setActiveTab('volunteers'); 
  };

  const handleLogin = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const user = volunteers.find(v => v.email.toLowerCase() === loginForm.email.trim().toLowerCase() && v.phone.trim() === loginForm.phone.trim());
    if (user) { 
      setCurrentUser(user); 
      setActiveTab(user.role === UserRole.ADMIN ? 'admin' : (user.status === UserStatus.APPROVED ? 'volunteers' : 'profile')); 
    } else setLoginError("Credenciales inválidas.");
  };

  const startEditing = (volunteer: VolunteerProfile) => {
    const userShifts = shifts.filter(s => s.volunteerId === volunteer.id);
    const morningShift = userShifts.find(s => s.period === 'MORNING');
    const afternoonShift = userShifts.find(s => s.period === 'AFTERNOON');
    setEditForm({ ...volunteer, morningDays: morningShift?.daysOfWeek || [], afternoonDays: afternoonShift?.daysOfWeek || [] });
    if (volunteer.id === currentUser?.id) setIsEditingProfile(true);
    else setEditingVolunteer(volunteer);
  };

  const saveMemberChanges = async (targetId: string) => {
    try {
      const { morningDays, afternoonDays, ...profileData } = editForm;
      const cleanProfile: any = { ...profileData };
      delete cleanProfile.id; delete cleanProfile.joinedAt;
      await updateDoc(doc(db, "volunteers", targetId), cleanProfile);
      // Actualización de turnos simplificada para brevedad
      setIsEditingProfile(false); setEditingVolunteer(null);
    } catch (e) { console.error(e); }
  };

  const filteredVolunteers = useMemo(() => volunteers.filter(v => {
    const matchesSearch = v.name.toLowerCase().includes(searchTerm.toLowerCase());
    if (communityFilter === 'ACTIVE') return v.status === UserStatus.APPROVED && matchesSearch;
    if (communityFilter === 'INACTIVE') return v.status === UserStatus.REJECTED && matchesSearch;
    return matchesSearch;
  }), [volunteers, searchTerm, communityFilter]);

  if (isLoading) return <div className="min-h-screen flex items-center justify-center"><Loader2 className="animate-spin text-indigo-600" size={48} /></div>;

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
        <div className="w-full max-w-sm bg-white rounded-3xl shadow-2xl border border-slate-100 overflow-hidden">
          <div className="bg-indigo-600 p-10 text-center"><h1 className="text-3xl font-black text-white">VoluApp</h1></div>
          <form onSubmit={handleLogin} className="p-10 space-y-6">
            <input placeholder="Email" className="w-full p-4 bg-slate-50 border-2 rounded-xl" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} />
            <input placeholder="Teléfono" type="tel" className="w-full p-4 bg-slate-50 border-2 rounded-xl" value={loginForm.phone} onChange={e => setLoginForm({...loginForm, phone: e.target.value})} />
            <button type="submit" className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-black">ENTRAR</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={(t: any) => setActiveTab(t)} 
      onLogout={handleLogout} 
      role={currentUser.role} 
      status={currentUser.status} 
      userName={currentUser.name}
      announcements={announcements.filter(a => a.status === 'published')}
    >
      {activeTab === 'calendar' && (
        <ShiftCalendar 
          shifts={shifts.filter(s => volunteers.find(v => v.id === s.volunteerId)?.status === UserStatus.APPROVED)} 
          volunteers={volunteers} 
          currentUser={currentUser} 
          onAddShift={(d) => addDoc(collection(db, "shifts"), {...d, volunteerId: currentUser.id})} 
          onUpdateShift={(id, upd) => updateDoc(doc(db, "shifts", id), upd)} 
          onRemoveShift={(id) => deleteDoc(doc(db, "shifts", id))} 
          onViewVolunteer={setViewingVolunteer} 
        />
      )}
      {activeTab === 'attendance' && <AttendanceView currentUser={currentUser} volunteers={volunteers} attendances={attendances} onCheckIn={handleAttendanceCheckIn} />}
      {activeTab === 'volunteers' && (
        <div className="space-y-10">
          <div className="flex justify-between items-center">
            <h2 className="text-3xl font-black">Comunidad</h2>
            <input placeholder="Buscar..." className="p-4 bg-white border-2 rounded-2xl w-64" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {filteredVolunteers.map(v => (
              <div key={v.id} onClick={() => startEditing(v)} className="bg-white p-6 rounded-3xl border shadow-sm flex items-center gap-5 cursor-pointer">
                <img src={v.photoUrl} className="w-16 h-16 rounded-2xl object-cover" />
                <div><h3 className="font-bold">{v.name}</h3><span className="text-xs text-slate-400">{v.volunteerType}</span></div>
              </div>
            ))}
          </div>
        </div>
      )}
      {activeTab === 'profile' && <div className="p-10 bg-white rounded-3xl shadow"><h2>Mi Perfil: {currentUser.name}</h2></div>}
      {activeTab === 'admin' && (
        <AdminDashboard 
          volunteers={volunteers} 
          announcements={announcements}
          onUpdateStatus={(id, s) => updateDoc(doc(db, "volunteers", id), { status: s })} 
          onEditVolunteer={startEditing} 
          onAddAnnouncement={async (msg) => {
            await addDoc(collection(db, "announcements"), { message: msg, status: 'published', publishedAt: new Date().toISOString(), createdBy: currentUser.id });
          }}
          onToggleAnnouncement={async (id, status) => {
            await updateDoc(doc(db, "announcements", id), { status });
          }}
          onDeleteAnnouncement={async (id) => {
            await deleteDoc(doc(db, "announcements", id));
          }}
        />
      )}
    </Layout>
  );
};

export default App;

